window.__D("text/torat-chaim/c004",{"p":[[2300670175,"שבהשגה כמו (תהלים פד, ג) לבי ובשרי ירננו כו' (שם קלב, ט) וחסידיך ירננו ואמר בזהר לויך מבעי לי' כו'. וזהו ענין הפסוק הזה ועבד הלוי בשיר להוא דבחי' עתיקא ממש שהוא גלוי התענוג הפשוט שיבא במורגש בהשגה דבינה מטעם הנ\"ל והוא העוה\"ב אשר אהיה דאנא זמין לאתגלאה ממש כמו שהוא בהשגה בבחי' יש מורגש דוקא כנ\"ל וד\"ל). ועם ביאור ענין זה יובן ג\"כ עוד ענין א' המובא בפרדס בענין ג' קוצין שבי' שקוץ העליון הוא בחי' הכתר וגופו של יו\"ד הוא נקודה דחכ' והקוץ התחתון שבה הוא הנמשך ומתפשט לעשות לצורת אות הה\"א באורך ורוחב כי מקוץ התחתון דוקא שנוטה להלאה מן הנקודה הוא שנמשך ההשגה דבינה לאורך ורוחב כנ\"ל. שזהו כח הבינה להבין ולהשיג בלבוש המסתיר ומגשם כו' (והוא מ\"ש הבן בחכמה כנ\"ל) אבל נקודה דחכמה עצמה אין בה רק כמו שהיא בנקודה אחת ואין בה כח זה להביא לידי השגה ממש לפי שאין לו שרש גבוה בכתר כ\"כ בעומק ורוממות העצמות עד שיוכל לבא לידי ירידה והתלבשות כ\"כ כפי כלל הנ\"ל דכל שאינו גבוה כ\"כ לא יוכל לבא למטה כ\"כ אבל בחי' קוץ התחתון דיו\"ד יש ביכולתו להתפשט בהשגה ולעשות מיו\"ד ה\"א לפי ששרשו היינו בחי' קוץ העליון ממש הפונה למעלה ע\"ג היו\"ד שהוא בחי' הכתר עצמו כידוע (שנקרא כתר שבכתר שלמעלה מחכמה שבכתר) שהוא גבוה יותר יותר יוכל לבא למטה שהוא בהשגה דוקא המלביש ומסתיר לנקודה דחכמה וכנ\"ל דכל הגבוה יותר א\"א לו להתלבש כ\"א בלבוש היותר תחתון וכמו משלי שלמה וכה\"ג ונמצא דבחי' קוץ העליון שביו\"ד שהוא בחי' הכתר היינו מ\"ש ועבד הלוי הוא שהוא בחי' בינה שזהו קוץ התחתון דיו\"ד שעושה מיו\"ד ה\"א והוא מ\"ש בזהר דדא הוא עתיקא ממש שאין זה בא אלא מכחו של עתיק ממש שהוא קוץ עליון דיו\"ד שלמעלה מן החכמה שמלובש בקוץ התחתון דוקא כנ\"ל וד\"ל:\n(טו) <b>והנה</b> בכל הנ\"ל מתורץ היטב הקושיא הנ\"ל בה\"א דאברהם שמשמעות הכתוב ששם זה בה\"א נוספת הוא למעלה גדולה ושבח גדול משם הראשון דאברם ע\"כ אמר ולא יקרא עוד שמך אברם כו' (וכל הקורא לאברהם אברם עובר בלאו כו') (ברכות יג ע\"א) אעפ\"י שבחי' ה\"א זה הן בחי' ה\"ח הנגלים ביסוד כנ\"ל הוא בחי' ירידה גדולה לבא מן ההעלם מלמעלה למטה מטה בגלוי גמור ובאמת לפי הנ\"ל בענין ועבד הלוי הוא דא הוא ע\"י כו' הרי מזה יובן דבאמת שם זה דאברהם גדול במעלה הרבה משם דאברם לפי שבה\"א דאברהם ה\"ז בחי' התגלות ממש מן ההעלם דנקודה דחכמה שאין זה בכח דנקודה דחכמה עצמה אלא בבינה דוקא שזהו בחי' ה\"א עלאה שהוא ה\"א דאברהם ששרשו בבחי' עצמו' דאור הכתר שהוא גבוה הרבה מבחי' חכמה שבכתר שנק' אברם בחי' נקודה דחכמה הנ\"ל וע\"כ אמר והיה שמך אברהם בה\"א שהן בחי' ה\"ח שמתגלים מבחי' פנימית הכתר כו' כנ\"ל. וזהו דוקא בשעת מילה ופריעה שאז דוקא היה בכחו של אברם לצאת מן ההעלם הפנימית לידי גלוי בה\"ח פנימיים הנ\"ל ואין זה מצד כח אברם עצמו דאדרבה נק' שכל הנעלם מכ\"ר אלא"],[2300670191,"מצד פנימית אור הכתר שהוא ע\"י כח דבינה דוקא לפי ששרש הבינה בכתר למעלה מן החכמה כנ\"ל וע\"כ בה\"א זה דבינה דוקא הוא שבא מן ההעלם לגלוי ע\"י המילה ופריעה משום דה\"א זה שרשו בכתר עצמו ולזה אמר לו והיה שמך אברהם בה\"א כשנמול שאז נתגלו ה\"ח הפנימיים למעלה ולשבח גדול יותר משמו הקדום דאברם ודוקא מצד כח הירידה דה\"א לקבץ כל הנצוצות דע' שרים וכמ\"ש כי אב המון גוים כו' שהיה זה בשעת מילה דוקא והכל מטעם כלל הנ\"ל דכל הגבוה יותר יותר יש בכחו לירד למטה מטה ביותר וכענין קוץ העליון דיו\"ד שמלובש בקוץ התחתון לעשות מיו\"ד ה\"א כו' שזהו המורה על מעלת הבינה יותר על החכמה כנ\"ל וד\"ל:\n(טז) <b>אך</b> לפי כל הנ\"ל בענין לך לך מארצך שהוא הצווי לצאת מן ההעלם לגלוי כו' עדיין אין מתיישב מה שצוה לו ה' לאברם טרם שנק' אברהם בה\"א שזה היה בשעה שמל א\"ע דוקא ומטעם הנ\"ל אבל בהיותו בשם אברם הוא להיפך שנק' שכל הנעלם מכ\"ר והוא בחי' נקודה דחכמה שאין בכחה להתפשט למטה כלל כנ\"ל באורך ואם מצד שצריך הכנה לזה מזמן קדום וצווי זה הוא על התעוררות הדבר לבד שיתעורר בעצמו לצאת כנ\"ל זה אינו מובן דמאין יהיה לו כח זה בלא ה\"א דאברהם כנ\"ל. והנה תחלה צריך להקדים עוד ענין אחד שאנו מוצאים שהוא בדוגמא דענין ה\"א דאברהם הנ\"ל והוא בענין התורה ומצות. דהנה ארז\"ל ג' נובלות הן נובלות חכמה ש\"מ תורה (ונובלות בינה של מעלה שכינה) וז\"ש (נדה מה, ב) בינה יתירה ניתנ' באשה שהוא בתשבע\"פ יותר מבאיש שהוא תשב\"כ שנק' נובלות חש\"מ גם בבחי' הנובלו' כמ\"ש במ\"א באריכות (ונובלות אורו ש\"מ גלגל חמה) דהנה באמת יש להפליא על מאמר זה למה נק' התור' רק נובלות חש\"מ הלא אמרו דאורייתא מח\"ע נפקת שהוא מ\"ש חכים ולא בחכמה ידיעא כו' וידוע דבחי' חכמה ש\"מ היינו בחי' חכמה שבעצמו' המאציל שהוא בחי' ח\"ס דא\"א הנ\"ל שנק' שכל הנעלם מכ\"ר ונק' פלאות חכמה כנ\"ל וכמ\"ש ולא בחכמה ידיעא כלל וא\"כ לכאורה יש להבין איך אמר דאורייתא מח\"ע נפקת דפי' נפקת היינו שיצאה לחוץ בגלוי מן ההעלם דח\"ס שנק' תעלומות חכמה דאיך אפשר שיצא לגלוי אור מהעלם דנקודה דח\"ס הנ\"ל אחר שנק' שכל הנעלם מכ\"ר שא\"א לבא בגלוי השג' כלל ואם אוריית' מח\"ע נפק' איך באה לנו בגלוי באותיות תושב\"כ במצות המפורשות בתושב\"כ וגם בדינין והלכות דתשבע\"פ וכמ\"ש (דברים כט, כח) והנגלות כו' לעשות אחר שבחי' ח\"ע נק' שכל הנעלם מכל רעיון ממש כנ\"ל וד\"ל:\n(יז) <b>אך</b> הנה התירוץ לזה הוא עצמו ענין המאמר דלעיל דנובלות חש\"מ תורה דאין התורה רק בחי' הנובלות דחש\"מ לבד ולא מגופה של ח\"ע וא\"כ הגם שגוף אור דח\"ע הנ\"ל איננה באה לידי גלוי כלל מהעלמה אבל בחי' הנובלות שנובל ממנה בבחי' חצוניות שבה הוא שיוכל לבא לידי גלוי בטנת\"א דתשב\"כ ובמצות הנגלות לנו וז\"ש דאורייתא מח\"ע נפקת שיצאה מבחי' הנובלות דחש\"מ שהיא התורה הנגלית לנו שבאה"],[2300670206,"בהתלבשות בעה\"ד טו\"ר לברר כו' כידוע דבחכמה אתברירו רפ\"ח כו' (אבל בחי' פנימית דח\"ע הן הנק' נסתרות לה' אלקינו בלתי יוכלו לבא למטה כלל גם לברר לעה\"ד ונק' עה\"ח כידוע וזהו פלאות חכמה שנק' שכל הנעלם מכ\"ר כנ\"ל). אך עדיין יש להבין דהגם שיש בחי' חצונית ואחוריים גם בחש\"מ (וכמו המגלה כתובה פנים ואחור (יחזקאל ב, י) זהו כשבאה לכלל התפשטות והמשכה למטה אבל בהיותה בלתי התפשטות כלל למטה כנקודה די' ואינה בגדר וסוג דבחי' התגלות כלל וכלל איך ימצא ממנה בחי' הנובלות כלל דאין נובלות אלא מצד רבוי ההתפשטות שיצא גם מותרות ונובלות אבל בבחי' ההסתר והעלם לגמרי לא שייך בחי' נובלו' כלל. אך שרש הענין הוא דנובלות הללו אינן באין כלל מצד עצמות הח\"ע כי הוא שכל הנעלם לגמרי ונק' ח\"ס מצד עצמו שלא שייך בו ענין התפשטות כלל שימצא בזה ענין הנובלות כנ\"ל אלא הנובלות באים מצד כח העליון יותר מגופו דח\"ע והוא בחי' עצמות אור הכתר שלמעלה מח\"ע שאינה רק חכמה שבכתר כנ\"ל והיינו ע\"פ כלל הנ\"ל דכל הגבוה יותר יותר יורד ובא למטה וא\"כ נובלות הללו מאחר שהן בבחי' חצונית ביותר ודאי הן באין מכח העליון ביותר שהוא אור הכתר עצמו שלמעל' מן הח\"ע הוא שימציא מציאות הנובלות מח\"ע זו לפי שא\"א שיתלבש עצמות אור הכתר בחכמה עצמה כ\"א בבחי' החצונית ביותר שהוא הנובלות כנ\"ל בענין משלי שלמה וכה\"ג להיות שגם נובלות הללו הן רק בחי' ירידת אור השכל ביותר עד שבא בהתלבשו' בענינים חצונים ופשוטים מאד כמ\"ש (סוכה כא, ב) שיחת ת\"ח צריכה למוד שנא' (תהלים א, ג) ועלהו לא יבול דמצד תוקף כח חכמתו ביותר נמצא גם בדברים הפשוטים שלו שנק' שיחה בעלמא חכמה גדולה שצריכה למוד משא\"כ מי שאינו חכם כ\"כ לא ימצא בדברים הפשוטים שלו שום שכל וחכמה רק דברים בטלים הם ואע\"פ שבאמת אין ערך כלל לבחי' הנובלות חכמה דשיחת ת\"ח לגבי עצמו' חכמתו במושכלות עמוקו' כשמדבר דברי חכמה עכ\"ז יוכלו להכיר בעומק החכ' שבו שלמעל' גם מדברי חכמה שלו בשיחת חולין שלו דוקא לפי שהגם שהחכמה שבשיחה שלו מעט מזעיר היא (כמו מילתא דבדיחותא שנק' גלייך ווערטיל) מאד בבחי' הקטנות אבל בזה דוקא לעומק כח תוקף חכמתו בעצם כח המשכיל שא\"א שיבא בגלוי בכלי שכלו בדברי חכמה לפי שכל הגבוה יותר בעצם כח החכמ' ימצא יותר בחי' חכמה בנובלות שבשיחה שלו וכל שאינו גבוה כ\"כ אין חכמה ושכל שבשיחתו כ\"כ א\"כ בנובלות דוקא ניכר רוממות מעלת העצמות יותר מגופ' של חכמה שבו והוא מטעם הנ\"ל בהתלבשות עומק השכל שא\"י לבא בדבור רק במשלים וחידות דוקא כו' וגם בנובלות דשיחה בטלה אינה באה סבת ירידה העצומ' הזאת רק מכחו של עצם רוממו' המעלה שהוא בבחי' הכתר עצמו שלמעלה ממה שנמשך מכח שכלו להשכיל מושכלות כו' והיינו כשמאיר מעצמות אור הכתר בחכמה נמצא בחי' הנובלות דוקא ולא מצד כח דחכ' עצמה וכמובן מכלל הנ\"ל וד\"ל. (וכמו העלה שצומחת בחצונית והיא שומר לפרי לפי ששרשה היה קודם לצמיחת הפרי כו'"],[2300670221,"ע\"כ יצאה בבחי' חצונית ומותרות כו' וראי' יותר ממה שאנו רואים בבחי' מותרי מוחין שנק' ג\"כ נובלות שכל זמן שאין מותרות במוחין כבן ה' שנה אינו ראוי להוליד מזרעו נפש השכלית בדומה לו אך כשהוא בן ט' שיש בו מותרי מוחין ראוי להוליד כו' שמזה הוראה גמורה שיש בבחי' המותרות דמוחין מעצמות הנפש שיוליד בדומה לו משא\"כ במוחין עצמן כו' לפי שסבת יציאת המותרות באים מתגבורת כח העצמות דוקא שלא יכילו המוחין כו' וכמשל חבית מלאה ביותר שמצד המלוי ביתר מכפי מדתה הוא שיוצא המותרות הנופל לארץ או כמשל האבוקה הגדולה שמאירה למרחוק ביותר שאור המעט דשם בא מכחה הגדול של אבוקה דוקא וד\"ל:\n(יח) <b>וא\"כ</b> הרי מובן במאמר הנ\"ל דנובלות חש\"מ תורה שזהו למעלה ושבח דוקא משום דבחי' הנובלות באים מכח העליון יותר מגופה של ח\"ע שנק' חש\"מ שאין בכחה להתלבש למטה כ\"כ והיינו מבחי' פנימית ועצמות דאור הכתר שנק' תר\"ך עמודי אור שהן תרי\"ג מצות וז' מצות דרבנן כו' שהמצות באו למטה בחצונית דוקא בבחי' דצח\"מ גשמיים לפי ששרשם מבחי' הכתר עצמו וגם בחי' הנגלה שבתורה הניתנה לנו לשמו' ולעשות גבוה יותר בשרשה מבחי' הפנימית דח\"ע שבה שנק' נסתרות שאינו בא בגלוי כלל מטעם כלל הנ\"ל דמטעם זה בחי' הנובלות שרשן למעלה מגוף אור דח\"ע (וכמו שבמ\"ת אע\"פ שבאור פנימית דח\"ע שנק' חש\"מ היה מאיר בי' הדברות מ\"מ העיקר היה בחי' הנגלה שבכל דבור שהן באין בדברים גשמיים לברר לעה\"ד בסור מרע ועשה טוב בפ\"מ שהן כללות דרמ\"ח מ\"ע ושס\"ה ל\"ת שבאים בכללות באנכי ולא יהיה לך כידוע) וכמ\"ש במ\"א ע\"פ כי טובים דודיך מיין (ע\"ז לה, א) ערבים עלי ד\"ס יותר מיינה של תור' כו'. (וכמ\"ש למעלה (בפ' נח) דגופי המצוה למעלה מן טעמי המצות שיתגלו לע\"ל והוא העוה\"ב שמן המצוה בפ\"מ שע\"ז אמר אשר אהי' אנא זמין לאתגלא' שהוא עדן העליון בחי' פנימית הכתר בכלל) (והן בחי' י\"ג חוורתי דגלגלת' כו' שלמעלה מחכ' כו'). והנה מזה הטעם יובן מה שהתורה נתנה לנו בהשגת השכל וטעם גשמי ובדברים גשמיים כמו מצות טלית בצמר דכבשים ותפלין בקלף עור בהמה גשמית וכה\"ג במצות סכה בסכך גשמי וכן תרומות ומעשרות וצדקה וקרבנות הכל בדברים גשמיים דוקא הגם שאמרו דאורייתא מח\"ע סתימאה נפק' שבחי' ח\"ע זו היא בבחי' ההעלם לגמרי ולא יוכל האור לבא למטה כלל אך התורה שבאה לנו בענינים דדצח\"מ גשמיים זהו הוראה על היות שרשה בעוצם הרוממות בבחי' כתר עליון עצמו דוקא שלמעלה מבחי' ח\"ס הנ\"ל שבכחו דוקא לירד ולהתלבש למטה בענינים גשמיים דדצ\"ח דוקא והוא ענין שאמרו דנובלות חכמה ש\"מ תורה שהנובלות באים מכחו של בחי' עצמות הכתר דוקא כנ\"ל וד\"ל:\n(יט) <b>ובכ\"ז</b> הרי יובן דרך כלל עכ\"פ דבתו\"מ בגשמיות שם שורה וגנוז ומלובש מבחי' עצמות אא\"ס ממש שמאיר בבחי' פנימית הכתר בדרך כלל והוא בחי' מל' דא\"ס שבכתר דע\"י וא\"א ולפ\"ז יובן ג\"כ דרך פרט בכל מצוה כמו"],[2300670236,"מצות תפילין בד' פרשיות שהן ד' מוחין דחו\"ב וחו\"ג כידוע הרי בחי' גלוי אור דח\"ע בפ' קדש דלפי שפ' קדש כתובה על קלף גשמי הרי מאיר בה מבחי' עצמות החכמה הקדומה שבעצמות א\"ס שלמעלה הרבה מגוף האור דח\"ע דאצי' וגם למעלה מבחי' ח\"ס דא\"א הנ\"ל לפי שבמצוה זו דתפלין מאיר מבחי' אור פנימית הכתר ששם שורה עצמות אא\"ס ממש (כמ\"ש בר\"מ דאור א\"ס מלגיו וכתרא עלאה מלבר) שהוא היורד ומתלבש למטה מטה דוקא כנ\"ל (כמו העמוד המחבר מעלה ומטה יחד כידוע) (ועד\"ז גם במצות העליונות דז\"א דאצי' כמו שאמרו שהקב\"ה מניח תפלין כו' (ברכות ו, א) מאיר בד' פרשיות מבחי' החכמה ומוחין שבעצמות שלמעלה הרבה מאור דח\"ע דאור אבא שבמוחין דז\"א כו' וכן מצות טלית למעלה שז\"ש שנתעטף הקב\"ה כש\"ץ כו' (ר\"ה יז ע\"ב) שנא' (תהלים קד, ב) עוטה אור כשלמה או (דניאל ז, ט) לבושה כתלג חור כו' הוא בחי' מקיף דציצית שהן ל\"ב נ\"ח כו' וכן מצות צדקה עליונה שהוא בחסד דרוע' ימינא כו' (וכמשי\"ת). וזהו שגם התורה בשרשה הראשון שנק' תורה של מעלה נק' (ש\"א כד, יג) משל הקדמוני או עוטה אור כשלמה בבחי' לבוש שהוא חצוני ועליון יותר מגופו של אור חכמה של מעלה שנקרא ים הקדמוני או אור החכמה מטעם הנ\"ל):\n(כ) <b>ועם</b> כ\"ז יובן ג\"כ הטעם למה נעשו כל יח\"ע באו\"כ דאצי' הכל ע\"י מצות מעשיות שנעשו בדברים גשמיי' דנוגה בעה\"ז דוקא וכמ\"ש בע\"ח דכל עיקר ענין המצוה בפ\"מ אינו אלא להוסיף אורות באצי' וע\"ד דוגמ' במצו' צדקה שלמטה ששרשה ידוע בספרי הקבלה שע\"י שנותן לדל דלית ליה מגרמי' כלום כסף גשמי להחיות רוח שפלים ע\"י זה נעשה למעלה בחי' יחוד עליון דזו\"נ דאצי' דהיינו מה שנמשך עי\"ז למעלה באצי' המשכת חסד ושפע לבחי' המלכות שנק' דל דלית לה מגרמה כלום כמ\"ש בזהר ע\"פ אשרי משכיל אל דל (תהלים מא, ב) והיא השכינ' שנק' דל כמ\"ש (שם קיג, ז) מקימי מעפר דל מעפר דעולם הבריאה וזהו ענין חסד ח\"ס דלי\"ת וגימ\"ל גומל דלים כו' וכאשר בחי' המלכות מקבלת שפע החסד מז\"א אזי נעשה מדלי\"ת ה\"א דוי\"ו שנתוסף בדלי\"ת נעשה צורת ה\"א והוי\"ו הזה נמשך מז\"א כידוע בענין ו\"ה דשם הוי\"ה וז\"ש בזהר דעד דלא קבילת שפע דדכורא נק' המלכות נער חסר ה\"א וכשקבלה השפע מז\"א נק' נערה בה\"א וכ\"ה ג\"כ בענין הצדקה שע\"י הצדקה שלמטה נק' המל' צדקה בה\"א כמ\"ש (שם יא, ז) כי צדיק ה' צדקות אהב שבחי' צ\"ע דהיינו יסוד ז\"א משפיע למל' שנק' צדק נעשה בתוס' ה\"א ונק' צדקה בה\"א לפי שתחלה נקר' המל' צדק דאיהו דין כו' וכאשר נמשך בה ה\"ח שהוא ע\"י הוי\"ו נעשה הדלי\"ת ה\"א כנ\"ל בענין נער ונערה כו' וד\"ל:\n(כא) <b>ובאמת</b> זהו פלא גדול איך יתכן שע\"י מצות הצדקה בגשמיות שהוא נתינת הכסף הגשמי לעני יעורר למעלה בחי' יח\"ע דז\"א במל' להשפיע במל' דאצי' עצמה ה\"ח דזהו גבוה הרבה גם מבחי' הענג העליון דמל' משפיע לנשמות בג\"ע כאשר נעשי' עתיק לבריאה דודאי מה"],[2300670251,"שהמל' מקבלת בעצמה תחלה בעודנה בבחי' האצי' ממש גבוה הרבה ממה שנעשית ראש לשועלים בירידתה בבי\"ע כידוע ואיך נעשה יח\"ע זה ע\"י ענין דמעשה גשמית דנתינת הכסף לעני כמצות הצדקה עפ\"י תורה הנגלית לנו דוקא. אך הענין הוא מטעם הנ\"ל דלפי שהמצות נתלבשו למטה בדברים גשמיים דוקא מזה הוראה על בחי' אור פנימית הכתר שמאיר בהן כנ\"ל דפ' קדש שגנוז בה מעצמות דחכמה דמאציל שלמעלה הרבה מאור חכמה דאצי' כו' מצד אמצעות דבחי' הכתר שבמצות תפלין שנק' תר\"ך עמודי אור כו' ומזה יובן ג\"כ בכל המצות מעשיות שהן בדברים גשמיים כמו הצדקה גשמית שע\"י יהיה בחי' יח\"ע מאד להוסיף אורות באצי' שזהו דוקא מצד ירידת אור הכתר בלבושים דמצות בחצונית יותר מטעם כלל הנ\"ל וא\"כ גם במצות צדקה לפי שהיא במעשה גשמית דוקא עי\"ז מתעורר שיהי' שפע אור דחסד דז\"א במל' דאצי' שנק' יחוד דזו\"נ כנ\"ל וד\"ל:\n(כב) <b>(ודרך</b> כלל הרי מכל מעשה המצות נעשה יח\"ע שנק' יחוד קודב\"ה ושכינתיה שהוא בחי' יחוד דזו\"נ דאצי' והכל מטעם הנ\"ל שבמצות שורה מעצמות אא\"ס שבפנימית הכתר דוקא כנ\"ל) וכמו\"כ במצות אתרוג עם לולב ומיניו דידוע שהאתרוג הוא בבחי' המל' ולמטה הוא אתרוג גשמי ולמעלה גורם ע\"י מצוה זו דלקיחת אתרוג ולולב שיושפע במל' דעת מז\"א כידוע שזה ודאי בא ממקום ומדרגה עליונה ביותר במל' דאצי' שלא היה אור כזה עדיין מז\"א למלכות בכל היחודים שלהם שמקבלים מוחין מאו\"א כו' לפי שנטילת לולב ואתרוג מצוה היא ששרשה בבחי' פנימית הכ\"ע כנ\"ל וירדה ונתלבשה למטה בלולב ואתרוג הגשמיים הרי יורד גם בחי' אור דכ\"ע שהוא שרש כל המצות למעלה שהן בחי' תרי\"ג ארחין דגלגלתא כו' ונתלבש במעשה המצוה הזאת דלולב ואתרוג והוא הגורם בחי' תוס' אורות העליונים במל' שתקבל מז\"א ע\"י הלולב כו' וכך יובן בכל המצות שנעשים בגשמיו' שנעשה עי\"ז יח\"ע באצי' מטעם הנ\"ל (ואפי' במצות ת\"ת נמשך בחכמה מעצמותו ית' והוא לשמה לשם התורה הקדומה וע\"י עסק גשמית התורה שלמטה וכן במצות ק\"ש ביחוד דע\"ס נמשך יחוד עליון יותר מיחוד העליון שכבר הוא בע\"ס דאצי' כו' וד\"ל:\n(כג) <b>והנה</b> אע\"פ שנתבאר למעלה שע\"י התו\"מ בפ\"מ דוקא נעשה יח\"ע באצי' עד רום המעלות מטעם הנ\"ל מ\"מ עיקר סבת גלוי אורות עליוני' ויח\"ע ע\"י המצות הוא שעשו האבות אברהם יצחק ויעקב הכנה רבה לזה ע\"י העובדות שלהם ונסיעתם בא\"י שזהו כל עיקר ענין ספורי מעשיות דס' בראשית מלך לך עד סוף ויחי שכל הספורים הן באבות ושבטים ויוסף שמהם היה הכנה להיות יח\"ע במצות שקבלו ישראל לעשותם בגשמיות וע\"כ נק' ספר בראשית ספר הישר (וכמשי\"ת) ואם לא היה קדימת מעשה האבות ביחודי' עליונים שעשו בעובדות שלהם קודם מ\"ת לא היה יח\"ע כלל במעשה המצות הגשמיים שלא היה יח\"ע תלוי במעשה התחתונים כלל שהרי אין ערך כלל לנברא בע\"ג"],[2300670266,"לגבי הבורא יש מאין וכ\"ש לגבי בחי' האצי' עצמו. ולהבין שרש וטעם הדבר הזה הנה יש להקדים ענין אחד דלכאורה יש להבין במה שאנו מוצאים בספורי מעשה האבות דידוע ששרש אברהם היה בבחי' החסד עליון והיה מרכבה לבחי' חסד דאצי' ע\"כ היו כל מעשיו רק להתחסד עם הבריות יהיה מי שיהיה היה מאכיל זן ומפרנס לכל גם לערביים כו' וכמ\"ש בזהר דהוה עביד טיבו יתירא עם ברייתא וא\"כ יש להבין למה לא סיפר בתורה מעובדות ומעשים של חסד שעשה אברהם בהיותו באור כשדים עד היותו בן ע\"ה שנה ולא התחיל להזכיר חסד וצדקה דאברהם בזריזותו להאכיל אורחים רק כשבא לא\"י (ואחר שמל א\"ע דוקא) והיה יושב באלני ממרא דכתיב והוא ישב פתח האהל וגו' וירא והנה שלשה אנשים וגו' וירץ כו' וביקש והפציר בם שיאכלו בביתו ומספר בזריזותו וכמ\"ש ואל הבקר רץ אברהם כו' וכי לא היה לו מדה זאת קודם לכן עד שבא לא\"י שכבר היה באור כשדים מאכיל וזן לכל בחן וחסד גדול ובזריזות יתירה כו'. אך הענין הוא דזהו ההפרש בין הצדקה וחסד שעשה אברהם בעודנו בח\"ל (וקודם שמל א\"ע) דאע\"פ שעשה כוונות ויח\"ע במס\"נ באה\"ר ודביקות נפלאה בהשפעת כל עצמות שלו ובכל הכוונות העליונות ששייכים למצות צדקה וחסד לא היה פועל עי\"ז רק להוסיף אורות עליונים בחסד עליון דאצי' לבד אך לא היה פועל שיומשך מאצי' לבריא' ומבריאה ליצירה כו' עד העוה\"ז בחי' תוס' אור אלקי להיות למטה כמו למעלה אלא רק כפי סדר ההשתלשלות דאבי\"ע עפ\"י מאמר קו המדה לבד וע\"כ נשאר היח\"ע באצי' לבד כי לא היה עדיין למעלה קשר וחבור ודרך ומעבר להיות הארת אור המאציל לנאצלים ומאצי' לבריאה כו' ביתר מכפי המדה וצמצום הראשון כלל (כמ\"ש למעלה) אלא כל אחד על מקומו ומדרגתו ומה שנמשך מעילה לעלול הכל במדה וצמצום ולא נעשה ונמשך מהעלם העליון לגלוי בתחתון יותר מכפי המדה הראשונה בתחלת ההשתלשלות מעצמות המאציל אפילו כמלא נימא כו' וכנ\"ל ולזאת הגם שעשה אברה' עובדות גדולות בצדקה וגמ\"ח וגלוי אלקות בגלותו אחדות ה' לכל העולם ונתגיירו רבים מעמי הארץ כמ\"ש ואת הנפש אשר עשו בחרן ולא נזכר בתורה כלל ממעשיו והילוכו עד שהיה בן ע\"ה שנה רק כשבא לא\"י אע\"פ שע\"י עובדו' שלו בכל יום היה גורם יח\"ע למעלה באצי' כי רוח אייתי רוח כו' והוא היה דבוק רק למעלה באה\"ר כמ\"ש התהלך לפני ממש כו' אבל באמת בחי' יחודים הללו היה הכל בכל מדרגה ומדרגה דע\"ס דאצי' בכאו\"א כפי מה שהיה תחלת ההשתלשלות ע\"פ מאמר קו המדה בלי תוספת ובלי מגרעת על מדה הראשונה וכך לא היה גלוי ההעלם מעליון לתחתון רק כפי מדה וצמצום הראשון ואע\"פ שהוסיף אור בחסד דאצי' היה נשאר האור באצי' ולא הגיע המשכה נוספת על המדה בבריאה רק כפי צמצו' שבין אצי' לבריאה וכן מבריאה ליצי' כו' וכן ענין גלוי אלקות ביח\"ע ויח\"ת דבחי' המל' ע\"י עבודתו במס\"נ בהתגלות שלו לכל העולם היה ג\"כ עד\"ז שלא היה רק כפי המדה בסדר ההשתלשלו' דאבי\"ע"],[2300670280,"מעילה לעילה כו' אך כאשר אמר לו ה' לך לך מארצך (ולך בשבילך) הענין הוא שיצא מבחי' ההעלם דכתר באברם בחי' ח\"ס הנ\"ל לגלוי יותר מכפי המדה וצמצום הראשון אל הארץ אשר אראך א\"י שנק' עלמא דאתגלייא ששם הוא המקום שיתגלה שם כל יח\"ע מהעלם לגלוי והיינו מה שנעשה מי' דחכמה ה\"א כנ\"ל באריכות בענין ה\"א דאברהם כו' ואזי נעשה בחי' דרך ומעבר להיות חבור וקשר מן עצמות המאציל לנאצלים וכן מאצי' לבריא' כו' להאיר בתוס' אור מרובה ביתר מכפי המדה ע\"י העלאת מ\"ן במעשה התחתונים שז\"ש ויאמר ה' אל אברם לך לך מארצך כו' שיתעורר לצאת מהעלמו לגלוי כנ\"ל וזה היה ההתחלה ממקור הראשון דבחי' ח\"ס שיצא אח\"כ מן ההעלם לגלוי ע\"י מעשה התחתונים בבחי' יח\"ע שבכל ע\"ס דאצי' בתוס' אור מרובה להאיר למטה דוקא כי רוח אייתי כו' דלאחר שכבר נעשה קשר וחבור ודרך ומעבר מלמעלה למטה מן המשפיע למקבל מעצמות המאציל לנאצלים ומאצי' לבריאה כו' כך ממש נעשה בחי' קשר וחבור מלמטה למעלה מן המקבל אל המשפיע דהיינו מה שיש בכח מעשה התחתונים בעובדות שלהם במס\"נ לגרום גלוי אור דיח\"ע בתוס' מרובה מכפי מדה הראשונה להאיר ולהמשיך למטה ממש כנ\"ל וד\"ל:\n(כד) <b>ובכ\"ז</b> יובן סדר דברי פרשה זו במ\"ש ויאמר ה' אל אברם לך לך מארצך כו' שזהו ענין ההתעוררו' של עצמות המאציל להיות דרך ומעבר וקשר וחבור מפנימית העלם העצמות לבא לידי גלוי בתוס' אור מכפי צמצום הראשון מלמעלה למטה מן המאציל לנאצלים וכנ\"ל וז\"ש לו לאברם בחי' ח\"ס לך לך כו' שיתעורר לזה לצאת מהעלם העצמות שלו לגלוי בנאצלי' ומאצי' לבי\"ע כו' וזהו אל הארץ אשר אראך שהוא בחי' המל' כו' דנעוץ תב\"ס דוקא ואח\"כ אמר ואעשך לגוי גדול דקאי על א\"י דוקא ששם יהיה לגוי גדול ע\"י שיהיו ישראל מקיימים תו\"מ בא\"י בשלמות הברורים דרפ\"ח נצוצות שנפלו בז' אומות שהיו אז בא\"י עד בימי דוד ושלמה דקיימא סיהרא באשלמותא כמ\"ש בזהר שהאיר בכל ע\"ס דמל' מפנימי' הכתר בגלוי שכינה בהיכל ק\"ק ובקרבנות כו' וז\"ש ואברכך ואגדלה שמך והיה ברכה להתברך ממך כל הע' שרים העליונים וכמ\"ש ונברכו בך כל משפחות האדמה וד\"ל. וכ\"ז הוא שנעשה ההתעוררות מלמעלה למטה במאמר הזה שא\"ל לך לך מארצך עד ונברכו בך כו' ואח\"כ ממילא נעשה דרך ומעבר וקשר וחבור מלמט' למעלה שיוכל התחתון לעלות למעלה ביתר מכפי כחו הראשון והוא מ\"ש מיד וילך אברם כאשר דבר אליו ה' שהיה יכול להלוך מארצו כו' להיות בא מן ההעלם לגלוי כאשר דבר אליו ה' בהתעוררות מלמעלה למטה כו' עד ויבאו ארצה כנען שהוא א\"י שא\"ל אל הארץ (עם שרי אשתו ולוט שהיא אחוריים דשם מ\"ה דאברם כמשי\"ת) ויעבר אברם בארץ עד מקום שכם העברה זאת היא בבחי' העלאה מלמטה למעלה מטעם שכבר נעשה דרך ומעבר מלמעלה למטה במ\"ש לו לך לך מארצך כו' וזהו שע\"י העברה שלו בארץ עד מקום שכם מיד וירא ה' אל אברם ויאמר לזרעך אתן כו'"],[2300670294,"שיומשך על ידם שלמות הגלוי הזה מן ההעלם ע\"י קיום התו\"מ בארץ הזאת דוקא. וזהו ויבן שם מזבח לה' הנראה אליו פי' הנראה אליו מהעלם העצמות דא\"ס ב\"ה בז\"א דאצי' שהוא שם הוי\"ה סתם בתוס' אור מרובה מכפי המדה הראשונה וזהו הנראה אליו עכשיו בא\"י שלא היה זה בהיותו באור כשדים אע\"פ שא\"ל לך לך כו' ע\"כ עשה מזבח בא\"י דוקא לה' הנראה אליו שם דוקא מטעם הנ\"ל דעיקר גלוי ההעלם שבעצמות ממש הוא בא\"י דוקא ואבות סימן לבנים כו' מפני שא\"י היא בחי' המל' שמקבלת מפנימית הכתר ולכן נקראת א\"י ארץ חפץ כו' וד\"ל:\n(כה) <b>ואח\"כ</b> אמר ויעתק משם ההרה שחזר להיות עולה במעלות דא\"י שהיא בחי' המל' למעלה שכלולה מע\"ס ושכם הוא בחי' אחוריים וחצונית המל' ונעתק משם לעלות ההרה בבחי' כתר מלכות שהוא מקדם לבית אל דאל נהירו דחכמתא והחכמה מאיר בבינה דבחכמה יבנה בית והוא בי\"ת דבינה כו' ויט אהלה בה\"א שהוא בחי' אהל ה\"א דמל' שיאיר בה ממקורא דכולא כו' וזהו ויבן שם מזבח לה' ויקרא בשם הוי\"ה להמשיך מלמעלה למטה ולהעלות הכל מלמטה למעלה וז\"ש ויסע אברם הלוך ונסוע הנגבה לבחי' החסד שבדרום שבמקור הראשון שהן בחי' ה\"ח הראשוני' שנק' חפץ חסד (מיכה ז, יח) שמחמתו חפץ לבא מן ההעלם לגלוי בדרך ירידה גדולה שלא לפי סדר ההשתלשלות כנ\"ל וזהו הלוך ונסוע ואמ' בזהר מדרגא לדרגא ובזה יש ב' אופנים אחת מלמטה למעלה בדרך עלייה וב' בדרך ירידה מלמעלה למטה ושניהם אמת שזהו בחי' רו\"ש כידוע בכל נסיעה יש עלייה וירידה שהיא הנסיע' והחני' ובזה ילך ויתותב ממקום למקום כו' ודרך כלל היינו שהיה עושה קשר וחבור בהלוך ונסיעה זו בא\"י בכל מקומות שבה להיות עלייה מבי\"ע לאצי' מלמטה למעלה וירידה והמשכה מאצי' לבי\"ע תמיד והיה זה הכנה לביאת בניו לא\"י שיהיה ע\"י המצות שיעשו בא\"י העלאה והמשכה מאצי' לבי\"ע כו' (כמשי\"ת) וכ\"ז נעשה ע\"י שאמר לו ה' לך לך מארצך כו' שנעשה בחי' דרך ומעבר מלמעלה למטה שעי\"ז היה אברהם יכול לעשות קשר וחבור ממקורא דכולא מלמעלה למטה וגם להעלות כל הניצוצות מלמטה למעלה משא\"כ קודם לכן שלא היה קשר וחבור לעליונים עם התחתונים כו' כנ\"ל וד\"ל:\n(כו) <b>וזהו</b> שאחר שהיה אברם עם אשתו במצרים ועלה משם בשלום כמ\"ש ויעל אברם ממצרים הוא ואשתו וכל אשר לו כו' וילך למסעיו מנגב עד בית אל פי' לפי שעלה ממצרים שהיפך חשוכא דנ' שערי טומאה דמצרים לנהורא שעי\"ז יבא יתרון האור מן החשך כידוע. ואבות סימן לבנים שגם ישראל זכו ע\"י יצ\"מ למ\"ת פב\"פ כו' ואז וילך למסעיו הראשונים שהיה עושה קשר וחבור מלמעלה למטה ע\"י הכח העליון שא\"ל ה' לך לך מארצך כו' וע\"כ אחר שעלה ממצרים היה עולה במעלות דא\"י למסעיו הראשונים מנגב עד בית אל עד המקום אשר היה אהלה בה\"א בתחלה שהן ה\"ח הראשונים עד\"מ באותו האורח ושביל שבו עוברי' מעיר לעיר יכולים"],[2300670306,"לחזור באותו שביל עצמו בחזירתו וכך באותו דרך ומעבר שכבר נעשה מלמעלה למטה כנ\"ל עי\"ז היה יכול לילך למסעיו הללו מלמטה למעלה בבחי' או\"ח בהעלאת כל הבירורים דרפ\"ח כו' שהעלה ובירר ממצרים כו' וזהו מנגב חסד דמל' שרש אברהם עד בית אל בחי' מל' דבינה שבה אור אבא שנק' אל כנ\"ל שהוא הה\"א שנעשה מקוץ התחתון די' כנ\"ל לפי שנסע במסעיו הראשונים שנסע מלמעלה למטה עד המקום כו' אל המזבח ויקרא שם אברם בשם ה' בתוספת אור מרובה משם ה' שקרא בראשונה מצד יתרון האור מן החשך בעלותו ממצרים וד\"ל:\n(כז) <b>ומעתה</b> יתורץ הקושיא הנ\"ל למה לא ספרה התורה במעלת הצדק' וחסד שהיה אברהם עושה עד בואו לארץ כנען בכוונות ויח\"ע כל ימיו עד שהיה בן ע\"ה שנה הטעם הוא כי שם לא אמר לו עדיין לך לך מארצך כו' שיצא מן ההעלם לגלוי לחבר ולקשר מעצמות המאציל באבי\"ע כנ\"ל שמפני זה לא היה נמשך יחודים הללו למטה כנ\"ל אבל אחר שאמר לו ה' לך לך מארצך כו' שנעשה דרך ומעבר מעצמו' המאציל באבי\"ע כנ\"ל ובא לא\"י שהוא המקום משכן לגלוי אור המל' דאצי' למעלה ולמטה כו' ובמקום המובחר שבה שהוא מקדם לבית אל כו' ע\"כ שם בנה מזבח לה' הנראה אליו כנ\"ל (ואחר שנצטוה על המילה בהיותו בן צ\"ט שנה ונימול הוא וכל ביתו) אזי ספרה תורה בפרטי מעשה הטוב דאברהם והוא במ\"ש וירא אליו ה' כו' והוא יושב פתח האהל כו' שמספר בזריזות צדקתו וחסדו בהכנסת אורחים שמיד שראה את האנשים רץ לקראתם ויאמר אם נא מצאתי חן כו' ואקחה פת לחם כו' וימהר אברהם האהלה כו' מהרי שלש סאים קמח כו' ואל הבקר רץ כו' שנראה מכ\"ז טוב חסדו עם הבריות למטה שעי\"ז עשה למעלה גלוי אור א\"ס בתוס' אור מרובה ביח\"ע בע\"ס דאצי' מעצמות המאציל שיומשך גם למטה מטה מה שלא היה כן בעודנו באור כשדים מטעם הנ\"ל וד\"ל:\n(כח) <b>ואחר</b> כל זה יובן ענין הנ\"ל ג\"כ דהגם שמצד התלבשו' התו\"מ בעניני' גשמיים דוקא הוא שנעשו למעלה כל יח\"ע ע\"י פנימית ועצמות אור הכתר ששם שורה מהו\"ע א\"ס ב\"ה ממש מטעם הנ\"ל מ\"מ עיקר הסבה לזה עצמו שיוכל להיות יח\"ע ע\"י המצות הגשמיות הוא דוקא ע\"י מעשה האבות שקדמו למ\"ת וכמ\"ש באברהם עקב אשר שמע אברהם בקלי וישמור משמרתי מצותי חקותי ותורתי (בראשית כו, ה) ואע\"פ שלא קיים כל רמ\"ח מ\"ע היה כולל כל רמ\"ח מ\"ע במ\"ע זו דצדקה וחסד שהיה איש החסד למטה שעי\"ז היה מקשר ומחבר ע\"י בחי' ה\"ח שבעצמו' המאציל לבא מן ההעלם לגלוי לאצילות ומאצי' לבי\"ע ע\"י שא\"ל לך לך מארצך כנ\"ל הנה ע\"י קשר וחבור הזה שעשה כל ימיו מלמעל' למטה ומלמטה למעלה הרי זהו שרש כל היח\"ע שנעשו בכל הרמ\"ח מ\"ע בכאו\"א מישראל שעושה מצות שנעשה יח\"ע כנ\"ל מזמן מ\"ת עד ימות המשיח והעוה\"ב (וכן יצחק בעובדות שלו במדת היראה ופחד אלקים ע\"י חפירת בארות (כידוע ומבואר"],[2300670318,"במ\"א) וכן יעקב בעובדות שלו במדת הת\"ת שהן ג' קוין דאצי' בכללות כמשי\"ת) ואם לא האבות לא היו נעשה בחי' יח\"ע למעלה ע\"י המצות הגשמיות שנעשו למטה כי לא היה יח\"ע הרוחניים תלוים במעשה התחתונים כלל כי אין חבור וקשר כ\"כ לעליונים עם התחתוני' רק ע\"י כמה מסכים והעלמו' וצמצומים עבים מאד שע\"י הצמצום הראשון דמאמר קו המדה כנ\"ל עד שכל מדרגה ומדרגה גם בע\"ס דאצי' כל א' על מקומו ומדרגתו היה בא ולא נמשך מעילה לעלול רק במדה ושעור בלי תוספת ובלי מגרעת כלל כנ\"ל וד\"ל:\n(כט) <b>ועם</b> כ\"ז יובן שרש ענין כל ספר בראשית שקדם לספר שמות ושאר הספרים לפי שס' זה הוא השרש הראשון לכל המצות שנכתבו בספרים האחרים וע\"כ נק' ס' בראשית בשם ספר הישר כמ\"ש (יהושע י, יג) הלא היא כתובה על ספר הישר שהוא ספר בראשי'. והטעם הוא לפי שעיקר ספר בראשית הוא בספור תולדות האבות והשבטי' וע\"כ הוא מספר ומאריך יותר בפרטי מעשיהם וכל קורותם להיות' שרש ומקור למצות שיכתבו בס' שמות ושאר ספרים כו' להיות מבואר למעלה שאם לא האבות במעשיהם שעשו קשר וחבור מעצמות המאציל לנאצלים בג' קוין דאצי' ימין ושמאל ואמצע (אברהם בקו הימין חח\"ן ויצחק בקו השמאל בג\"ה ויעקב בקו האמצעי דת\"י) לא היו נעשים יח\"ע ע\"י המצות כלל:\n(ל) <b>וז\"ש</b> (תהלים עח, ה) ויקם עדות ביעקב כו' דהנה התורה שנתנה לישראל באה להם ע\"י האבות שקדמו למ\"ת כי האבות היו מרכבה לחג\"ת דאצי' כנ\"ל ואבות הן סימן לבנים (וגם עכשיו הרי ג' הרגלים פסח ושבועות וסכות הן כנגד ג' האבות פסח בבחי' החסד דאברהם ושבועות בבחי' גבורה דיצחק וסכות בבחי' ת\"ת דיעקב וגם בכל יום ג' תפלות האבות תקנום אברהם תקן תפלת שחרית כו' כידוע ובכל תפלה ג\"ר שבה הן לנגד האבות כידוע ותחלת כל תפלה או' אלקי אברהם כו'):\n(לא) <b>ויובן</b> זה עד\"מ האב שמוריש לבנו מכל אשר לו הנה האב הכין הכל ביגיעתו ועבודתו כל ימיו בכל אשר עשה בכל רכושו בכל הדברים במזון ומלבוש ודירה וכסף וזהב וכל הצריך לבנו הכל הכין האב כמו שהכין דוד לשלמה לבנין ב\"ה כל מה שצריך עצים ואבני' וכסף וזה' ונחשת לכל מלאכת הבית כמ\"ש (דה\"א כט, ב) ובכל כחי הכינותי כו' ולא היה צריך שלמה למצוא הדברי' שצריכים לבנין הבית רק לעשות ולבנות בלבד וכ\"ה ענין הירושה לבן מאביו שהכל הניח האב במותו במזומן ובא הבן ויורש כל הדברים המוכנים ועומדים ברשות האב שהכין לו כל ימי חייו ואם לא האב שהכין הכל לא היה לבן כלום מצד עצמו וא\"צ הבן רק לשמור ולעשות בכל הדברים שירש כפי הנאות ונצרך לעסוק בהם בלי תוספות ובלי מגרעת אחר שכבר הכל מן המוכן ועומד מכבר כו' וד\"ל:\n(לב) <b>וכך</b> יובן הנמשל מזה באבות העולם שאין קורין אבות אלא לשלשה (מ\"ש פ\"א הי\"ד ברכות טז, ב)"],[2300670329,"אברהם יצחק ויעקב כידוע שזהו מפני שהאבות הן הן המרכבה לג' קוין דאצי' כנ\"ל. וע\"כ נקראו אבות העולם (שעליהם העולם דאצי' עומד בג' קוין חח\"ן כו' שהוא תורה ועבודה וגמ\"ח תורה בקו האמצעי דיעקב איש תם יושב אהלים תשב\"כ ושבע\"פ כמ\"ש ויקם עדות ביעקב דוקא ועבוד' בקו השמאל דירא' ופחד יצחק וגמ\"ח בקו הימין דחסד דאברהם) והן חח\"ן בג\"ה ודת\"י כו' שיומשך בהן מעצמות המאציל למעלה מצמצום דקו המדה כנ\"ל וע\"כ האבות הללו היו סימן לבנים דהיינו שהיו מכינים בעבודת' בדביקות והתקשרו' האמיתית לעצמות אא\"ס ב\"ה ממש בכל ימי חייהם להוסיף אורות עליונים באצי' והכל היה מן המוכן על ידם בעולם האצי' בשביל בנ\"י לצורך קיום התו\"מ למטה בעוה\"ז כל הצריך להם בכל פרטי מעשה המצות ועד\"מ הנ\"ל בהכנת האב לבנו כל הצריך לבנין בית כו' או שכבר הכין כל טוב והון ועושר בביתו בכל הדברים הצריכים למזון ומלבוש ובנין בית וגם הכין עוד שאר פרטי דברים יקרים דוקא כפי המצטרך לג' אלה מזון ולבוש ודירה וכה\"ג והכל מוכנים ועומדים ומונחים באוצרותיו וכשיבא הבן יקח הכל מן המוכן וא\"צ הבן רק לעשות הלבוש והבנין ולתקן המאכלים כו' וא\"צ לטרוח ולמצוא תבואות ומאכל וצמר ללבוש ועצים ואבנים לבנין כי הכל יש מן המוכן בידו כו' וכך יובן הנמשל למעלה באבות העולם שהם הכינו כבר בעובדות שלהם במס\"נ שעשו יח\"ע למעלה באצי' בג' הקוין חח\"ן כו' אברהם בקו הימין בשרשו בבחי' החסד שבעצמות ויצחק בקו השמאל בבחי' הגבורה שבעצמות כו' (כידוע בענין הגדול בה\"א הידיעה שזהו ע\"י החסד דאברהם וכן הגבור כו') שזה הכל היה הכנה רבה שכבר הוכן המשכות עליונות מעצמות המאציל באצי' לענין היחודים שעתיד להיות ע\"י מעשה המצות שיעשו ישראל למטה בפ\"מ עד שאינם רק כמו הבן שעושה בירושתו שכבר הוא מן המוכן בידו כנ\"ל וכמו שמבואר למעלה בענין החסד שעשה אברהם למטה בבואו לא\"י שעשה עי\"ז יח\"ע מעצמות המאציל באצי' מלמעלה למטה וממטה למעלה בבחי' קשר וחבור אחד עד שעי\"ז נעשה הכנה למעל' בכל זמן שיעשו ישראל למטה מצות הצדקה וחסד גשמי שיהיה עי\"ז יח\"ע באצי' בזו\"נ ואו\"א (כנ\"ל בענין צדקה בה\"א שהוא המשכת תוס' אור החסד מז\"א למל' ממקור כל החסדים העליונים שבעצמות ממש) מפני שאברהם היה מרכבה להוסיף אור החסד שבעצמות א\"ס ממש בקו הימין חח\"ן דאצי' כו' וכה\"ג בכל המצות שהן בבחי' החסד נעשה יח\"ע באצי' ע\"י ישראל שעושין למטה הכל מצד ההכנה שהיה לזה ע\"י עובדא דאברהם איש החסד ואם לא הכנת אברהם בכל מה שעשה כל ימיו לא היה יח\"ע דאצי' תלוי כלל במצות הצדקה וכה\"ג בשאר מצות שהן בקו הימין שעושין למטה בגשמיות וא\"כ ה\"ז ממש כמשל הנ\"ל באב שהכין לבנו העצים ואבנים לבנין וכן ללבוש ומזון והבן אינו אלא בונה ולובש ואוכל ממה שכבר הכין האב כו' וכך א\"צ ישראל רק לעשות מצות הצדקה בפ\"מ בלבד (ודוקא ישראל מצד קבל' התו\"מ ויש להם ירוש' מאבות משא\"כ חסד לאומים כו') וכבר"],[2300670340,"הוכן למעלה שיהיה בזה בחי' יח\"ע בחסד העליון שבעצמות ממש בכל הע\"ס דאבי\"ע כו' וכה\"ג בשאר פרטי המצות שבבחי' החסד בבחי' המשכת גלוי אלקות מלמעלה למטה (וכן בהתפעלות האהבה ודביקות בכאו\"א כמשי\"ת) וכה\"ג בקו השמאל בבחי' גבורה ופחד יצחק היו כל עובדות דיצחק הכנה רבה באצי' להיות יח\"ע בקו השמאל בג\"ה ע\"י המצות שיעשו ישראל למטה שהן בבחי' העלאה מלמטה למעלה כמצות הקרבנות ותרומות ומעשרות (ומצות היראה ולבער הרע בבחי' גבורות) וע\"י העובדות דיעקב שנק' בריח התיכון כו' קו האמצעי הוא הכולל כל ב' מיני מדרגות דאברהם ויצחק וכמ\"ש (בראשית לא, מב) אלקי אברהם ופחד יצחק היה לי ששניה' כלולים בו וע\"כ אמר ויקם עדות ביעקב דוקא שע\"י יעקב וישראל בחיר שבאבות הוקם ונבנה כל שלמות הבנין דתו\"מ שישראל עושים בכל הצריך בפרט להיותו כולל ב' הקוין דאצי' שזהו התורה הכלולה מה\"ח וה\"ג דרמ\"ח מ\"ע ושס\"ה ל\"ת כמ\"ש (דברים לג, ב) מימינו אש דת למו ע\"כ אמר ויקם עדות שהוא קו האמצעי דתורה ביעק' דוקא וד\"ל:\n(לג) <b>(וזהו</b> שגם עכשיו אמר (מיכה ז, כ) תתן אמת ליעקב חסד לאברהם כו'. אמת היא התורה שהיא בקו האמצעי דת\"י שכולל ב' הקוין כנ\"ל וחסד לאברהם בקו הימין חח\"ן כו'. לפי שכבר נשבעת לאבותינו מימי קדם דהיינו שכבר נעשה כריתו' ברית ושבועה לאבותינו שהן המרכבה העליונה לחג\"ת דא\"א וע\"י מימי קדם שיומשך על ידן תמיד מימי קדמונו ש\"ע ממש כנ\"ל) וע\"כ בכל ג' רגלים הן לנגד האבות דוקא וגם בכל יום בג' תפלות וכידוע דגם אוי\"ר שהן שרש רמ\"ח מ\"ע ושס\"ה ל\"ת נמשך בכאו\"א מאברהם ויצחק בכל יום וכמ\"ש במ\"א ע\"פ (ישעי' סג, יז) למה תתענו ה' מדרכיך תקשיח לבנו מיראתך כו' שהוא אהבה דאברהם אוהבי רחימא דמלכא בכל ימיו היה הכנה להיות אהבה זו ירושה לישראל בכאו\"א מיד שיתעורר לבו יבא להתפעלות אהבה כבן היורש מן המוכן כנ\"ל והוא שרש לקיום רמ\"ח מ\"ע וכן יראה ופחד יצחק שהיה בעבודתו כל ימיו נמשך ירושה לישראל בכאו\"א להיות פחד אלקים בלבו. להיות סור מרע בפ\"מ שהוא השרש לשס\"ה ל\"ת וכן בחי' הרחמים דיעקב שכלול מאוי\"ר ירושה לכאו\"א לעורר ר\"ר על נפשו כו' שהוא הכולל להעלות כל המצות שנעשים באוי\"ר כו' וזהו למה תתענו ה' מאהבה דאברהם שנק' דרכיך ותקשיח לבנו מיראתך דפחד יצחק שוב למען עבדיך שבטי כו' וזהו ע\"י ספר בראשית שנק' ספר הישר לעורר ולהזכיר חסדי אבות לבנים להיות מאיר מן ההעלם דעצמות לגלוי בכאו\"א שיוכל לקיים תו\"מ באוי\"ר בכל דור ודור וע\"כ קדמו משה לכתוב לספר בראשית קודם לשאר הספרים (וכמשי\"ת):\n(לד) <b>וזהו</b> שרש ענין ספר בראשית שקדמו משה לכתוב לפני שאר הספרים ולכאורה למה קדם משה לכתוב ס' בראשית שהוא ספורי מעשיות וסדר תולדות הדורות וקורותיהם שאין בהם תועלת ולמה קדמו לעיקר התורה שהן ס' שמות ושאר הספרים שכותב ומספר בפירוש מעשה"],[2300670351,"המצות שזהו עיקר הספר ואיך קדם הטפל לעיקר. אלא הענין הוא דודאי ס' בראשית הוא עיקר הספר ולכך קדם לשאר הספרים כי הנה עיקר ענין ס' בראשית אינו אלא מה שמספר והולך תולדות האבות ומעשיהם בפרטות וכל קורותיהם באריכות. ואגב התחיל במע\"ב ובתולדות אדה\"ר וכל הדורות שאחריו עד אברה' ותחלת הספור הוא באברהם בתולדתו ובסדר כל פרטי מעשיו וקורותיו ונסיעותיו וכל אשר דבר עמו ה' עד שנצטוה על המילה והוא כל ספורי מעשיות שבפ' לך לך עד וירא וכל פ' וירא אחר שמל א\"ע וגם כל סדר פ' חיי שרה עד וימת אברהם כו' ומתחיל בפ' תולדות לספר מתולדות יצחק בן אברהם ועד פ' תולדות נשלמו ספורי מעשיות דאברהם מתחלתו לסופו דהיינו מה שנשלם כל ההכנה העליונה שנעשה ע\"י אברה' למעלה בבחי' קו הימין חח\"ן דאצי' כנ\"ל ואח\"כ מתחיל לספר בסד' תולדו' מכל פרטי מעש' יצחק בחפיר' בארות וקורותיו וברכותיו כו' והיינו מה שעשה יצחק ההכנה העליונה בעולם האצי' השייך לחלקו ומדרגתו בבחי' קו השמאל בג\"ה כו' והוא ע\"י עובדות שלו בחפירות בארות וכה\"ג כו' ואח\"כ בפ' ויצא מספר בתולדות יעקב ונסיעותיו וכל פרטי עניניו וכל מעשיו והנהגותיו עם לבן ועשו עד סוף פ' וישלח ולהיות יעקב בחי' קו האמצעי שכל מעשיו ועניניו היה עושה הכנה למעלה בקו האמצעי דת\"י שכולל ב' הקוין דימין ושמאל (שהוא עיקר התור' כנ\"ל במ\"ש ויקם עדות ביעקב כו') ע\"כ האריך בספורו יותר לפי שהוא העיקר הכוללם יחד כו' וד\"ל ואח\"כ בפ' וישב יעקב מתחיל לספר בתולדו' יוסף בן יעקב וכל קורותיו ומעשיו עם השבטים וכל פרטי תולדותיהם שגם הם אע\"פ שלא נק' אבות הם נק' שרשים הכלליים לגבי הענפים שנסתעפו מהם רק לגבי האבות נק' שבטים כידוע והאריך בספורים דיוסף יותר מיעקב לפי שהוא בבחי' יסוד ז\"א כו' (ויעקב בחי' ת\"ת וגוף וברית חשבינן חד כו') וכמ\"ש אלה תולדות יעקב יוסף כו' והשבטים קבלו ממנו ועל ידו כידוע בענין החלום שלו שאמר והנה אנחנו מאלמים אלמים והנה קמה אלמתי כו' וכמ\"ש הנה נתתי לך שכם כו' ע\"כ מאריך בספורו יותר להיותו עיקר המשפיע סוף וגמר כל שפע העליונה בג' הקוין דאבות להשפיע למל' וכל זה שמספר שנעשה ביוסף ושבטים היה הכנה למעלה באצי' להשפעת התו\"מ לישראל בגשמיות עד תשלום פ' ויחי שמספר במיתת יוסף ואשר אמר פקד יפקד אלקים כו' עד וימת יוסף כו' שזהו תשלום כל ההכנה של האבות ויוסף ושבטים שעשו למעלה בעולם האצי' וד\"ל. ונמצא שכל ס' בראשית הוא מקור ושרש להיות קיום התו\"מ ושיהי' עי\"ז הסתעפות מ\"ת לישראל בהר סיני ושיהי' נעשה כל יח\"ע ע\"י מעשיהם שזהו שמספר אחר ספר זה בספר שמות שבאו למצרים ע' נפש ויצאו משם ע\"י משה ואהרן ועמדו בה\"ס לקבל תו\"מ במעשה גשמי' ומפרש והולך בשאר הספרים פרטי מעשה המצות כולן כו' וכל זה שמספר בס' שמות ושאר הספרים תלוים בעיקר ושרש של התו\"מ שמספר והוא ס' בראשי'"],[2300670362,"שמספר בתולדות האבות ומעשיה' מטעם הנ\"ל ולזה הטע' קדם משה לכתוב ס' בראשית לשאר הספרים שאחריו כי הוא העיק' ושרש להם כמובן מתוך המשל דירושה הנ\"ל וד\"ל:\n(לה) <b>אך</b> הנה עדיין יש להבין למה נק' ס' בראשית בשם ס' הישר דוקא כנ\"ל. וגם יש להבין דלכאורה יש סתירה גמורה לכל הענין הנ\"ל באבות שהן מקור ושרש לתו\"מ שקבלו ישראל שהרי מקרא מפרש ואומר וארא אל אברהם כו' באל שדי ושמי הוי\"ה לא נודעתי להם והקושיא ידוע איך אמר ושמי הוי\"ה לא נודעתי כו' הרי כמה פעמים הזכיר שם הוי\"ה בהגלותו אל אברהם כמו בפ' וירא אליו הוי\"ה וגם קודם שמל א\"ע בהיותו בן צ\"ט שנה אמר וירא הוי\"ה אל אברה' וכן ליצחק וליעקב כמה פעמים וצ\"ל דמפני שלא קבלו האבות תו\"מ בפ\"מ שבהן מלובש שם הוי\"ה ממש שנק' תורת הוי\"ה מצות הוי\"ה ע\"כ אמר ושמי הוי\"ה ממש לא נודעתי להם וא\"כ איך יתכן שעל ידם היה שרש ומקור לתו\"מ ואם מפני שבהכרח צריך לומר שאבו' קיימו התו\"מ ברוחניות עכ\"פ שהרי אמר עקב אשר שמע אברהם כו' וישמר משמרתי מצותי חקותי ותורתי וארז\"ל (יומא כח ע\"ב) קיים א\"א ע\"ה אפי' ע\"ת כו' וכי אפשר שקיים מצו' התלויות בא\"י וביצ\"מ בפסח וסכות וכה\"ג אלא צ\"ל שקיים כל התו\"מ ברוחניות דהיינו כמו שהמצות הן למעלה ברוחני' באורות עליונים דאצי' וכמו עובדא דמקלות שעשה יעקב היה ממש כמו מצות תפלין שלנו כמבואר בזהר וכך היה כל עובדות דאברהם ויצחק כו' ואמנם עדיין אין זה מתיישב דהלא מבואר למעלה דמצות שנתלבשו בגשמיות שרשן למעלה יותר לפי שכל הגבוה יותר יותר מתלבש למטה וא\"כ מצות הגשמיות יותר גבוה ממצות הרוחניות ולז\"א באבות ושמי הוי\"ה לא נודעתי להם לפי שלא קיימו תו\"מ בגשמיות אלא ברוחניו' לבד וא\"כ הדרא קושיא לדוכתא איך אפשר שמעשה האבות היה מקור ושרש לתו\"מ שיעשו ישראל למטה כנ\"ל אחר ששרש המצות בגשמיות יותר גבוה מעובדות שלהם ומחמת זה אמר ושמי הוי\"ה לא נודעתי להם כנ\"ל וד\"ל:\n(לו) <b>אך</b> הנה תחלה יש להבין הטעם שנק' ספר בראשית ספר הישר ובזה יתורץ גם קושיא זו. ויש להבין תחלה בטעם ספורי מעשיות שבס' בראשית שנכתבו באריכות מאד וגם כמה מעשיו' הוכפלו בכתוב כמו מעש' דאליעזר עבד אברהם הוכפלו דבריו בתורה וע\"כ ארז\"ל (בב\"ר פ\"ס, ח) יפה שיחתן של עבדי אבות לפני המקום מתורתן של בנים שהרי כמה גופי תור' ומצות נכתבו ברמז ובקצר' כמו בפ' בסכות תשבו (ויקרא כג, מב) וכן וקשרתם וכתבתם שצריכים פירוש איך לעשות סכה ותו\"מ ודברי אליעזר הוכפלו וזהו פלא גדול למה יהיה שיחתן של עבדי אבות גדול יותר מתורתן של בנים ועוד דהרי יש כמה ספורי מעשיות שאינן שייכים לאבות כספור מלחמה באריכות באמרפל מלך שנער כו' עד שאמר ומלכי צדק כו' וכה\"ג ספורי מעשיו' דדור הפלג' וסדר תולדו' הדורות מאדה\"ר עד נח ומנח עד אברהם וגם בספורי עניני האבות נכתבו באריכות מאד כו' וגם מספר בתולדות"],[2300670373,"הגוים כמו בתולדות חם ויפת ותולדו' עשו וישמעאל עד ואלה המלכים אשר כו'. אך הנה יש להקדים כלל א' אשר כל הספורי מעשיות שבס' בראשית הוא מדבר בבחי' ומדרגה עליונה ביותר עד שהוא גבוה הרבה מכל הספרים האחרי' שמדבר במעשה המצות כמו ספור יצ\"מ ומ\"ת וכל המופתים וקי\"ס ומצוה ראשונה דהחדש הזה לכם כו' וכל המצות שנכתבו בספר שמות וס' ויקרא ובמדבר עד ס' דברים שבאר משה את התורה כו' הכל הוא נמשך ומסתעף רק מס' בראשית מכל אשר נכתב בספר זה מהתחלתו במע\"ב ותולדות אדה\"ר ודורות שאחריו וכל ספורי עניני האבות ואמהות עד סוף ויחי שמסיים וימת יוסף בן מאה כו' וע\"כ אמר על ספר זה שהוא ס' בראשית זה ספר תולדות אדם פי' זה הספר דבראשית נק' ספר תולדות אדם ונק' ג\"כ ספר הישר כמו הלא היא כתוב' על ספר הישר והוא מקור ושרש לספרי' האחרים שנק' תורת האדם וכמ\"ש (ש\"ב ז, יט) וזאת תורת האדם כו' וע\"כ אמרו דיפה שיחתן של עבדי אבות כו' כי גם בס' בראשית עיקר הספור באריכו' יותר הוא במעשה האבות ותולדותם ודרך אגב מספר גם בתולדות זולתם והכל הוא בבחי' ומדרגה עליונה הרבה יותר מגופי תו\"מ שבספרים שאחריו. ושרש הענין הוא כידוע ומבואר במ\"א ע\"פ (איוב כח, כז. כח) אז ראה ויספרה הכינה וגם חקרה ויאמ' לאדם הן יראת ה' היא חכמה וסור מרע בינה פי' אז מקדמת דנא כמו (תהלים צג, ב) נכון כסאך מאז כו' והיינו בבחי' מהו\"ע המאציל ממש דע\"ז אמ' גליף גליפו בטה\"ע והוא מה ששיער בעצמו בכח מה שעתיד להיות בפועל בקו\"ח ואבי\"ע וזה השיעור בעצמו היה עפ\"י קו המדה איך וכמה דהיינו איך יהיה הרצון והחכמה ומדות בהעל' ובגלוי בלי נטייה לימין ושמאל שלא יהיה נטיה לימין ביותר ולא לשמאל ביותר אלא כפי היושר וזה נק' קו הישר כקו המשקולת ששוקל בשוה לימין ושמאל להיותו עיקר המכריע ביניהם כו' וזהו אז ראה ויספרה שזהו ע\"י התורה שקדמה לעולם ששקל בה כל אופן השעור גם בעצמו בכח ובהעל' בע\"ס הגנוזות בעצמות מה שעתיד להיות בגלוי ובפועל בע\"ס דקו\"ח כו' וזהו ראה בחכמה דתורה הקדומה ויספרה בספר שנק' ספר תולדות אדם וזהו שנק' ספר הישר שהוא ס' בראשית ואח\"כ הכינה וגם חקרה להביאה מן ההעלם שבעצמות לגלוי במחשבה ובדבור במחש' ורעותא דלבא היינו כמו במצות הרוחניו' למעלה שזהו היה עובדות דאבו' למטה וגם חקרה בדבור שזהו מ\"ת בי' הדברות שבאה למטה בהתלבשו' בעניני' גשמיי' עד ויאמר לאדם הן יראת ה' היא חכמה וסור מרע בינה שהוא בחי' המעשה בפ\"מ שנק' סוף דבר שבזה נעוץ תחלת הכל שז\"ש ויאמר לאדם דוקא וכמ\"ש (קהלת ז, כט) אשר עשה האלקים את האדם ישר שיהיה בבחי' יושר דתור' הקדומה שאז ראה ויספרה כו' שהיא חכמה ברורה בלי נטיה לימין ושמאל וכמו להגיד כי ישר ה' כו' (תהלים צב, טז) וכן כי ישרים דרכי ה' כו' (הושע יד, י) וזו דוקא כשבא בפ\"מ דע\"ז אמר כי זה כל האדם ובזה יש יתרון מעלה לישראל על האבו' שקיימו התו\"מ ברוחניות"],[2300670383,"ועכ\"ז אם לא האבות שקיימו ברוחניות כמו שהמצות באדם העליון שנמשך ממהו\"ע מבחי' ספר תולדות אדם שהוא ספר הישר דבראשית כמ\"ש אז ראה ויספרה לא היה יורד ונמשך מאצי' לבי\"ע התו\"מ בדבור ומעשה שע\"ז אמר הכינה וגם חקרה ויאמ' לאדם לשמור ולעשות כו'. ובזה יתורץ הקושיא הנ\"ל דאע\"פ שנאמר ושמי הוי\"ה לא נודעתי להם מפני שלא באה להם התו\"מ בגשמיות ששרשן למעלה יותר כנ\"ל עכ\"ז העובדות של האבות היה שרש ומקור להביא התו\"מ מהעלם העצמות ממש לגלוי במחשב' וממח' לדו\"מ כמ\"ש הכינ' וגם חקרה כו' כנ\"ל וזהו כל ענין ספר בראשית שנק' ספר הישר שקדמו משה לספר תורת האדם דמצות הגשמיות וד\"ל:\n(לז) <b>אך</b> עדיין יש להבין למה גם כל ספורי מעשיות שבס' זה דבראשית וגם מתולדות הגוים כישמעאל ועשו שנכתבו נק' הכל בשם ס' הישר דוקא כו' ולמה יהיה גבוה במדרגה מן המצות הכתובות בס' שמות וס' ויקרא כמו ויאמר ה' אל משה שבכל מצוה שהוא בחי' פנימית רצה\"ע ממש ולמה שיחתן של עבדי אבות או ספור מעשה פשוטה או סדר התולדות נכתבו באריכות הרבה יותר והן גבוהות במעלה ומדרגה עד שנק' שרש ומקור לספרים האחרים כנ\"ל אמנם הנה פי' הפשוט בשם ישר הוא כאשר הולך ביושר בלי נטיה כלל לכאן ולכאן שכל דבר שנמשך ממנו בדרך קוין בנטיו' לימין ושמאל אינו נק' ישר אבל ישר הוא דבר ההולך בשוה ובמישור מראש לסוף בלי ינטה לשום צד כמו השכל והרצון שהולך ביושר בלי ינטה לקוין לימין או לשמאל ביתר מכפי שהוא אמיתת הדבר כמו שהוא ממש וז\"ש אשר עשה האלקי' את האדם ישר כו' שהנשמה שנק' אדם נמשך אורה מן העצמות ביושר בלי נטיה כלל לימין ושמאל כו' ובאמת הלא אנו רואים שיש באדם ב' קוין ימין ושמאל ברצון ושכל ומדות וגם בגופו יד ימין ויד שמאל כו' אלא צ\"ל דנטיות הללו עצמן הן באין מכח קו היושר דוקא כמו קו המשקולת שמעמיד כפי המאזנים לימין ושמאל בשוה כנ\"ל ושרש הדבר הוא מה שנק' אדם ישר עד שהקוין שבו בלי נטיה ביותר מכפי מה שהוא באמיתת עצמותו כו' הנה זהו מצד שנמשך מן העצמות בלתי ממוצעים כלל אלא כמו שהוא בעצמות ממש כן נמשך ובא בגופו שאז ודאי הילוכו ביושר בלי נטיה לאיזה צד ממילא כמו (בראשית ב, ו) ויפח באפיו נ\"ח. שהלכה הנשמה שלא ע\"י ממוצעים שאז הולכת ביושר כמו שהיתה כלולה תחלה בעצמותו ע\"כ גם בהתלבשות' בגוף בקוין ימין ושמאל נק' ישר בלי נטיה לצד יותר מכפי שהוא בעצמות ממש ונמצא שפי' ישר בלי נטיה ובלי ממוצע הכל א' דהא בהא תליא שאם היה הולך ע\"י ממוצע ממילא היה נמשך בנטיות לצד בשנוי מכפי שהוא בעצמות כו':\n(לח) <b>ועד\"ז</b> ממש יובן ג\"כ כאן בענין ס' בראשית שנק' ס' הישר להיו' שהוא בבחי' ומדרג' גבוה מאד נעלה דהיינו כמו שהיה הכל כלול במהו\"ע המאציל תחלה איך שיהיה המקור לרצון וחכמה ומדות שבתו\"מ מבחי' היושר שהוא כמו שבאמיתת עצמותו שלמעלה עדיין מהתחלקות"],[2300670393,"והמשכות קוין ימין ושמאל כמו דבר שנמשך ביושר בלי ממוצע שהולך בלי נטיה ממילא כנ\"ל ואמנם זה עצמו הגורם שיהיו הנטיות לצד ימין ושמאל באים מכח היושר דקו האמצעי שלא ינטו לצד רק כפי האמת בלי יתרון שזהו כמו ציור אדם שהוא בצלם אלקים ממש בלי נטיה לימין ושמאל רק בדמותו כצלמו בכל פרטי הקוין שבו כו' וז\"ש זה ספר תולדות אדם ביום ברא כו' בצלם אלקים ברא אתו וכמ\"ש עשה האלקים את האדם ישר והיינו ענין כל ספורי המעשיות דס' בראשית בסדר תולדות אדה\"ר וכל הנטיות שבו לצד ימין ושמאל שהן חג\"ת וענפיהן ופרטיהן בחצונית ובפנימיות והוא שמספר בכל תולדות הדורות עד אברהם וכל קורותם שהן הכל בחי' חצוניות עד אבות העולם וגם באבות מספר מתולדות החצוניות שלהם כישמעאל שיצא מאברהם ועשו מיצחק וקורותם וכל פרטי ספוריהם אבל הכל במדה ושעור דוקא וכמו ואלה המלכים אשר מלכו בארץ אדום וכה\"ג עד שבא אל ספור הפנימיות דאדם שהן האבות והשבטי' וכל קורותם שזהו עיקר האדם שנק' ישר בלי נטיה דהיינו שכל נטיות הקוין שבהן הוא מכח הקו הישר בדומה לעליון ממש כמו שהתורה הקדומה היא במהו\"ע ית' ממש שע\"ז אמר אז ראה ויספרה כנ\"ל מבחי' פנימיו' ועצמות א\"ס ב\"ה ממש ואח\"כ הכינה ע\"י האבות וגם חקרה במ\"ת כמו (משלי כה, ב) וכבוד מלכים חקור דבר שבא מן ההעלם לגלוי בדבור וזהו ענין גלוי התחלקות הג' קוין דאצי' והמשכתן למטה מאצי' לבי\"ע לבא בעניינים גשמיים וכידוע דרמ\"ח מ\"ע הן ה\"ח ושס\"ה ל\"ת הן ה\"ג והממוצע היא התורה וזהו והנגלת לנו ולבנינו כו' לעשות וזהו וגם חקרה ויאמר לאדם הן יראת ה' ברמ\"ח מ\"ע בפ\"מ היא חכמה הקדומה שאז ראה ותורה בפ\"מ היא בינה הקדומה שאמר ויספרה כו' דבסוף מעשה דוקא ניכר תחלת הכל כו' והן הן ס' שמות ויקרא במדבר שהן בבחי' גלוי התו\"מ בג' קוין מאצי' לבי\"ע כמו ויאמר ה' אל משה לאמר לבנ\"י שהן נשמות דבי\"ע בגופים אבל מה שנחלקו בציור ג' קוין וכל פרטיהם כאלה דוקא בלי נטיה כלל לימין ושמאל אפי' כמלא נימא כמ\"ש (משלי ל, ה) כל אמרת אלוה צרופה כו' והזהיר אל תוסף על דבריו (שם, ו) זהו מפני שכבר נמשך ציור זה בבחי' היושר מעצמות ופנימיות א\"ס ב\"ה ממש וזהו ענין ס' בראשית שקדם להם שנק' ס' הישר שהוא העושה התחלקות הג' קוין באצי' מעצמות המאציל בציור זה קודם שניתנה התורה לישראל בבחי' ירידה והמשכת ג' קוין אלה בעשיה בפ\"מ שהן ג' קוין נפרדים ממש (בציור אדם חצוני כו') אבל באצי' הג' קוין הללו שהולכים ביושר מן העצמות ממש כמ\"ש עשה את האדם ישר וזה ספר תולדות אדם כו' ה\"ז מיוחדים בעצמות המאציל דאיהו חד ממש. וידוע דהאבות היו מרכבה לחג\"ת דאצי' ממש כמו שהן בבחי' הפנימית בעצמות וע\"כ גם מה שיצא מהם לצד בבחי' מותרות הכל בא שם במדה ונצרך לספר בהם וכן בתולדות הגוים לכל פרטי ספוריהם והכל מקור ושרש לכל המצות דעשה ול\"ת שבשאר הספרים ולכך האריך בספוריהם יותר מן המצות כנ\"ל וד\"ל:"],[2300670403,"(לט) <b>ומעתה</b> לא יפלא מאמר רז\"ל דיפה שיחתן של עבדי אבות כו' דודאי ספור זה דאליעזר היה להביא את רבקה לייחדה עם יצחק שהוא בחי' מ\"ה וב\"ן דזו\"נ שכפי שהוא בעצמות ממש גבוה הרבה מכמה מצות מעשיות שבשאר הספר שכל עיקר ענינם אינו רק יחוד אחד מיח\"ע דזו\"נ וספור זה מדבר מעצם היחוד דמ\"ה וב\"ן דיצחק ורבקה כמו שהן במקורם וכה\"ג בספורי בנות לבן רחל ולאה עד שנתייחדו עם יעקב והולידו י\"ב שבטים שכ\"ז מדבר בעצם מקור יח\"ע דיעקב ולאה ורחל שבאצי' שהן בחי' ב\"ן שבכל פרצוף וכן אברהם ושרה וכל ספוריהם שהוא בבחי' או\"א דאצי' שע\"ז נתנה כל התו\"מ להיות יח\"ע באו\"א וזו\"נ באצי' ע\"י המצות ולזה הקדים ס' בראשית שבו נזכר עצם מציאו' היח\"ע שבאים בבחי' היושר בג' קוין דאצי' בבחי' מ\"ה וב\"ן דכר ונוקבא כאברהם ושרה ויצחק ורבקה ויעקב ורחל ולאה והמצות הכתובים בשאר הספרים אינן רק לעורר יח\"ע מלמטה למעלה ע\"י המעשה דוקא כנ\"ל וד\"ל (ועכ\"ז אמר על האבות ושמי הוי\"ה לא נודעתי להם מטעם שלא קיימו המצות בפ\"מ מפני שסוף מעשה עבמ\"ת וכנ\"ל במ\"ש ויאמר לאדם הן יראת ה' כו' וכמ\"ש (ירמי' ט, כב) אל יתהלל חכם כו' (וכמשי\"ת):\n(מ) <b>והנה</b> יש להבין עוד בתוס' באור כל הענין הנ\"ל וגם להבין בתוס' באור סדר דברי הפ' הזאת עד ואברה' בן ע\"ה שנה בצאתו מחרן עד סיום הפרשה. דהנה לכאורה יש להבין עוד ב' דברים אחר באור כל הנ\"ל. הא' למה לא זכו בנ\"י לקבלת התו\"מ בה\"ס עד שנכנסו תחלה בעול גלות מצרים בעבודה קשה בחומר ובלבנים דוקא כידוע מאחר שלפי כל הנ\"ל הרי זכו ישראל למצות בגשמיות מצד הירושה מאבות שהכינו להם הכל בעובדות שלהם כנ\"ל ומפני זה הקדים משה לכתוב ספר בראשית שנק' ספר הישר כנ\"ל. והב' מדוע לא נמול אברהם עד היותו בן צ\"ט שנה להיות שמו אברהם בה\"א דוקא כנ\"ל אחר שכבר צוה לו ה' לך לך מארצך כו' שזהו ענין הגלוי מן ההעלם שבעצמות כנ\"ל בהיותו בן ע\"ה שנה היה לו לצוות אותו מיד על המילה ולהיות נק' שמו אברהם בה\"א ומדוע נמשך הזמן כ\"ד שנה מע\"ה עד צ\"ט כו'. ולפי המובן מכל הנ\"ל הרי ודאי כל היח\"ע דאברהם שבהיותו בשם אברם לא היו באים לגלוי כלל למעלה בלא ה\"ח דה\"א דאברהם וא\"כ יפלא יותר מה שנזכר בתורה המסעות שלו בא\"י במ\"ש כאן ויעבור אברם בארץ כו' וירא ה' אל אברם כו' ויסע אברם כו' וכן כשעלה ממצרים וילך למסעיו כו' עד ויקרא שם אברם בשם ה' אחר שלא נעשה ע\"י קריאתו בחי' גלוי מן ההעלם כאשר שמו אברם עד שנק' אברהם דוקא (רק בהכנסת אורחים לא סיפר עליו עד שמל א\"ע). אך כ\"ז יובן עפ\"י הקדמה אחת הנ\"ל בענין המצות שקיים אברהם אפי' ע\"ת כו' אע\"פ שלא היה בא\"י ובזמן ב\"ה שכמה מצות תלויות בהן כו'. אלא הענין הוא שכל המצות קיים ברוחניו' ולא בגשמיו' כנ\"ל. וד\"ז צריך באור איך שייך לומר מצות ברוחניות ולא בגשמיות כו'. אך הענין ידוע שיש"],[2300670413,"מצות הרוחניות למעלה שנק' מצות הוי\"ה ממש בבחי' האצי' (וכמו שאו' מצותי ואנו אומרים אשר קדשנו במצותיו כו') אך מה שאמר באברה' כי ידעתיו למען אשר יצוה את בניו ושמרו דרך הוי\"ה ממש לעשות צדקה ומשפט כו' משמע מצות בגשמיות ואפשר להיותו שרש ומקור לצדקה ומשפט שיעשו בניו בגשמיות כנ\"ל זהו אשר יצוה את בניו כו'. והענין הוא כידוע בע\"ח דעיקר ושרש כל המצות למעלה היינו רק להמשיך תוס' אורות בכלים דאצי' כמו במצות ת\"ת להמשיך תוספת אור דא\"ס בחכמה שהוא חכמה מוחא ובמצות צדקה להמשיך תוס' אור א\"ס בחסד דרועא ימינא כו' וכה\"ג בכל המצות שנק' רמ\"ח אברין דמלכא כידוע. אך לכאורה אין לזה הבנה כלל דהלא כבר נאצלו כל אורות דאצי' בכלים מכלים שונים ונמשך גם תוספות אור בכלי מעצמות המאציל כמשל שלהבת הקשורה בגחלת וכחפירות שמקבלים מן הנהר כו' וא\"כ מהו ענין המצות למעלה ברוחניות שעי\"ז דוקא נמשך תוס' אורות בכלים כו' וגם למה נק' מצות הוי\"ה ברוחניות דאצי' להוסיף אורות בכלים ע\"י מעשה התחתונים דוקא אחר שבלא\"ה נמשך תוס' אורות בכלים כו' וגם א\"כ מהו ההפרש בין קיום המצו' דאבות ברוחניות בעובדות שלהם לקיום המצות שלנו בגשמיות כו' וד\"ל:\n(מא) <b>אך</b> הנה התירוץ לזה ידוע דאורות דאצי' נאצלו מעצמו' המאציל בבחי' צמצום ומדה עפ\"י מאמר קו המדה הידוע שהוא מה ששיער בעצמו בכח איך שיהיה בפועל ועד\"מ הבונה בנין שיומדד בו הרצון ושכל ומדות באופן בנין זה בדקדוק ושיעור בעצמו לא יוסיף ולא יגרע אופן ציור הבנין ואז ממילא נעשה כן בגלוי הרצון ושכל ומדות להביא לידי מעשה הבנין בפ\"מ וכן במע\"ב בי' מאמרות שנתגלה ההעלם של הרצון וחכמה ומדות שבעצמות בדקדוק ושעור ששיער בעצמו איכות אופן הבנין של עולם הגשמי וכך עד למעלה מעלה שע\"ז נא' כי אמרתי עולם חסד יבנה (תהלים פט, ג) גם בעולם האצי' באיכות אופן גלוי ע\"ס כמו שהן בהעלם העצמות הכל היה ע\"פ מדה ושעור ששיער בעצמו תחל' ולפ\"ז כאשר צריך להיות תוס' אור חדש באבי\"ע אשר לא היה כזה בתחלת השעור והמדה שנק' קו המדה (כאמת הבנין ממש שמודד איך וכמה וכמ\"ש (ישעי' מ, יב) מי מדד בשעלו מים כו' וכמ\"ש במ\"א) אזי יש בזה ב' אופנים א' שיהיה התעוררות אור חדש הזה מעצמות המאציל ממש בע\"ס הגנוזות בהעלם העצמו' תחלה וממילא יומשך כן בגלוי דע\"ס דאצי' ומשם לבי\"ע כמו לנשמות בג\"ע עד עוה\"ז השפל לשנות טבע הבריאה דמע\"ב שהן נסים ונפלאות כידוע או שיהיה גלוי אור האצי' בבריא' ביתר מכפי המדה כמו גלוי שכינה בנביאי' ובהיכל ק\"ק או שיעלה מבי\"ע לאצי' ביתר מכפי המדה וצמצום בבטול היש לאין כאליהו וחנוך שעלו למעלה ממש וכה\"ג. והב' שיבא זה ע\"י מעשה התחתונים דוקא שיעוררו לבחי' מהו\"ע המאציל שיאיר בתוס' אור מרובה על העיקר באצי' מלמעלה גם מן הרצון והתענוג שהיה בהעלם העצמות תחלה להוסיף אור חדש ברצון ותענוג הקדום וגם בחכמה הקדומה וממילא יומשך אור חדש זה"],[2300670422,"בכח\"ב ומדות דאבי\"ע כו' וד\"ל:\n(מב) <b>והנה</b> אופן זה שמתחדש מן העצמות ממש ע\"י מעשה התחתוני' להוסיף אור חדש בבחי' חפץ חסד הראשון ששיע' בעצמו בכח כו'. הנה זהו ע\"י מצות מעשיות שלמט' אחר מ\"ת לישראל כמו ע\"י מצות ת\"ת לשמה למטה שהוא לשם התור' עצמה היינו להוסיף אור חדש מעצמו' המאציל באור החכ' שבהעלם עצמותו שיבא לידי גלוי אור בכלי החכמה דאצי' שהוא חכמה מוחא להאיר בחכמה שבתורה דוקא בפרטי המדות כמו בסדר זרעים נמשך ע\"י למוד בדבור בסדר זה תוס' אור חדש בבחי' אור החסד שבחכמ' שבתור' שמאיר בכלי הוא סדר זרעי' בתוס' אור רב (וממיל' נמשך תוס' אור בחסד דאצי' לצורך בנין העולמות או להשפיע לנשמות ומלאכי' עד חסד הגשמי למטה כמו אם לא בריתי כו' (ירמי' לג, כה) וע\"י סדר שני נמשך אור חדש במדה השניה דחכמה וכך כל ו' סדרי משנה ולמעל' היינו ו\"ק דח\"ע דתש\"מ וכ\"ה ע\"י מצות הצדקה למטה נמשך תוס' אור חדש מבחי' העצמות ממש דהיינו מבחי' חסד דא\"ס עצמו באור חסד דז\"א להשפיע למל' כו' בתוס' אור רב ועד\"ז הן כל מעשה המצות שהן רק להוסיף אורות באצי' מעצמות א\"ס ממש שלמעלה מקו המדה הנ\"ל וד\"ל:\n(מג) <b>והנה</b> כאשר קיים אברהם כל התו\"מ ברוחניות כנ\"ל היינו בבחי' ממוצע בין ב' האופנים הנ\"ל דהיינו שע\"י העובדו' שעש' א\"א למט' במס\"נ ובדביקו' אמיתית לעצמות א\"ס ב\"ה ממש עשה התעוררות חדשה בעצמות המאציל להיות מתעורר מכח עצמו להמשיך תוס' אור חדש בכל ההשתלשלות דע\"ס שבהעלם ובגלוי בקו\"ח באבי\"ע כנ\"ל כמו בחסד ואהבה רבה דאברהם למטה נתעורר אור חדש בבחי' חפץ חסד הראשון להאיר תוס' אור בכח\"ב ומדות שבהעלם העצמות להיות תוס' אור באבי\"ע כו' וכן ע\"י עובדות דיצחק ביראה ופחד כו' שכל זה הוא ענין קיום התו\"מ ברוחניות דהיינו בבחי' או\"כ דאצי'. ובזה יובן יותר הטעם שצוה לו ה' לך לך מארצך כו' דהיינו לפי שצריך לקיום התו\"מ ברוחניות דאצי' להוסיף אור חדש מעצמות המאציל כנ\"ל ושיבא גלוי האור בכלים דוקא וכמו בחכמה מוחא חסד דרועא כו' כמו במצוה שלמטה ע\"כ א\"א כ\"א שיצא בעצמו מבחי' ההעלם וצמצום הראשון שהוא השעור דקו המדה הנ\"ל בבחי' הגלוי ביתר מכפי המדה וצמצום הראשון כמ\"ש למעלה ולזאת צוה לו על התעוררות זאת בכלל עכ\"פ באמרו לך לך כו' וד\"ל:\n(מד) <b>אך</b> הנה באמת זה הצווי היה רק על בחי' קיום התו\"מ ברוחניות דאצי' להאיר בתוס' אורות בכלים בג' הקוין דאצי' (שזהו הנק' מצות הוי\"ה למעלה או מצותי ממש כנ\"ל) שיאירו ביתר מכפי הצמצום הראשון דאע\"פ שמאיר לפרקים תוס' אורות בכלים זהו הכל ע\"פ קו המדה מהתעוררות דחפץ חסד הראשון משא\"כ ע\"י עובדות דאבות נמשך ביותר כנ\"ל וזהו הקיום דתו\"מ ברוחניות להוסיף אורות בכלים למעל' הוא כמו הקיום דתו\"מ בפנימית כמו שהוא בבחי' האצי' ממש דאיהו וחיוהי חד כו' (שהוא בבחי' הסוד וטעם שבהם שנק'"],[2300670431,"טעמי תו\"מ שיתגלו לע\"ל ע\"י משיח (וכמו בג\"ע עכשיו כו') אבל כדי שיהי' קיום התו\"מ בגשמיו' דהיינו שיומשך ויתלבש האור בכלי למטה בעשיה גשמית ע\"ד התלבשות האור העליון דאצי' בכלי שלה דאצי' בתוס' אור כנ\"ל (עפ\"י התור' דאצי'). והדוגמא לזה התלבשות ח\"ע הפנימית בפ' קדש דתפלין ול\"ב נ\"ח דמקיף העליון בל\"ב חוטין שבציצית וכה\"ג בכל המצות במצות צדקה ות\"ת שמתלבשים למטה בגשמיות ממש הנה לזה לא היה הצווי אל אברם לך לך מארצך כו' כי לא ניתן לו יכולת הזה להביא ולהמשיך יח\"ע דאצי' שבמצות הרוחניות גם למטה בגשמיו' כ\"א לפ\"ע העלאת מ\"ן שלו מלמטה ע\"י דביקות ומס\"נ שלו בתמידות לעצמות א\"ס ב\"ה שאין זה גורם רק הוספו' אורות בכלי' דאצי' ברוחניות לבד אלא ישראל דוקא הוא שקבלו זה בשעת מ\"ת כידוע וכמ\"ש ושמי הוי\"ה לא נודעתי להם שהוא מצות הוי\"ה שבאו למטה בגשמיו' ששרשם עליון יותר כמשי\"ת ומה שיכלו ישראל לקבל תו\"מ בגשמיות לא היה רק מחמת עול גלות קשה שהיה להם במצרים בעבוד' קשה בחומר ובלבנים שמררו את חייהם ממש (שמחמת עוצם השפלות שנק' עמ\"ת הוא שזכו להיות נמשך להם תו\"מ משרשם העליון ביותר בחי' עו\"ר) אבל לא מחמת שירשו כח זה מן האבות דאין אבות סימן לבנים להוריש להם ירושה כנ\"ל רק במה שהיה בכחם בעובדות שלהם שהוא קיום התו\"מ בפנימיות ברוחניות דאצי' לבד אבל מה שלא זכו האבות בעובדות שלהם שהוא קיום תו\"מ בגשמיות איך יורישום לבניהם וע\"כ הוצרכו ישראל להיות בגלות מצרים כדי שיזכו לקבלת תו\"מ בחצוניות דוקא וד\"ל:\n(מה) <b>ובזה</b> מתורץ הקושיא הא' למה לא זכו ישראל לקבל' תו\"מ עד שנכנסו בגלות מצרים (וז\"ש וארא אל אברהם כו' ושמי הוי\"ה כו' וגם אני שמעתי את נאקת כו' וגם הקמתי כו' דע\"כ זה שזכו ישראל מצד הגלות כבר הכינו להם האבות ליתן ירושה דא\"י לבנים לפי שקיימו התו\"מ ברוחניות דאצי' עכ\"פ וכנ\"ל בענין זה ספר תולדות אדם דהיינו ס' הישר דבראשית דזה עצמו שהתו\"מ שרשן בעצמות א\"ס ממש בבחי' המדה ושעור לנטיה דימין ושמאל כו' הנה נמשך מהעלם העצמות לגלוי ע\"י האבו' כנ\"ל בענין ראה ויספרה הכינה וגם חקרה כו'). אך הנה עדיין דבר זה צריך טעם ובאור למה לא זכו האבות לקיום התו\"מ גם בחצוניות כמו שזכו בקיום התו\"מ ברוחניות ופנימיות הלא יש בכלל מאתים מנה וחצונית נכלל בפנימית כו'. אבל כללות שרש הענין הזה מובן מתוך כלל הנ\"ל שיש שרש לחצונית למעלה יותר משרש של הפנימי' כנ\"ל בענין נובלו' חש\"מ תורה דלשבח קאמר ומקוצו של י' התחתון שעשה צורת ה\"א בהתפשטות הוא קוץ העליון שלמעלה מגופו של נקודה די' דחכמה עצמה שאין בה כח זה להתפשט בבינה כו' והוא עפ\"י כלל הנ\"ל דכל הגבוה גבוה ביותר ירידתו למטה לבא בהתלבשות החצונית ביותר דוקא וכמו משלי שלמה ומשלים דר\"מ כו'. וכה\"ג יובן ג\"כ בענין המצות שמן ההכרח לומר דכל שהאור והשפע דרצה\"ע בא למטה בלבוש דחצונית דחצונית ביותר שזהו ההוראה על"],[2300670440,"עוצם רוממות ערך האור הזה שהוא בא ממקום גבוה מאד נעלה דהיינו מבחי' פנימית שבפנימית ביותר כו' משום דלפ\"ע כח רוממות האו' בשרשו העליון כך ממש ערך כח ירידתו למטה מטה ביותר ואם אינו גבוה כ\"כ אין בכחו לירד למטה מטה כ\"כ כו'. ולפי\"ז הרי יובן ממילא בקיום התו\"מ בחצונית ובגשמיות דדצ\"ח בצמר דטלית וקלף דתפלין וסכך דסכה וכה\"ג דבחי' נוגה דעשי' מזה הוראה הגדולה על בחי' האור העליון הגנוז בהם שהוא רצה\"ע שהוא בא ממקום גבוה ביותר שהוא מבחי' הפנימיות דפנימיות דהיינו מבחי' פנימית דפנימית הכתר העליון שבו שורה פנימית דפנימית מעצמות א\"ס ב\"ה שהוא גבוה הרבה גם מבחי' אור הכתר עליון דאצי' שהיה מאיר ביח\"ע דאצי' בע\"ס או\"כ ע\"י עובדות דאבות שנק' קיום התו\"מ ברוחניות ופנימית הנ\"ל כי מאחר שלא היה ביכולת יח\"ע שלהם לירד ולבא למטה בהתלבשות חצונית בעשיה גשמית ממש כ\"א ברוחניות באצי' לבד הנה מזה יש הוראה גמורה שאין האור העליון שהיה מאיר ביח\"ע שלהם בא ממקום גבוה כ\"כ לפי כלל הנ\"ל וד\"ל:\n(מו) <b>ולזה</b> הטעם יובן מה שלא זכו האבות למצות בחצוני' כי אע\"פ שגם בשביל קיום התו\"מ ברוחניות צוה לו ה' לך לך כו' שיומשך אור עליון מעצמות המאציל מהעלם לגלוי למעלה מכפי המדה וצמצום הראשון דהשתלשלות הקדומה אבל בשביל קיום התורה בגשמיות הרי הוצרך שיבא האור ממקום ומדרגה גבוה הרבה יותר שבעצמות המאציל מטעם כלל הנ\"ל וכמו שיבא התלבשות האור דחכמה עלאה בפ' קדש בקלף גשמי הוצרך שיבא האור מלמעלה מבחי' אור דח\"ע דאצי' מאחר שנמשך ונתלבש גלוי זה בחצונית כ\"כ בקלף גשמי מזה הוראה גמורה ששרש גלוי זה הוא מלמעלה ממקור ההשתלשלות (שאין העלאת מ\"ן במס\"נ בעובדו' מגיע לשם כלל כעובדא דמקלות דיעקב שהן ענין התפלין ממש כמ\"ש בזהר שלא בא האור העליון במקלות ממקום גבוה כ\"כ כמו בתפלין שלנו כו') אשר שם גם החכמה דאצי' בחי' עשיה יחשב כי אצי' ועשיה שוים שם ממש וע\"כ גם בקלף הגשמי יוכל להתלבש כי גם בחי' רוחניות דח\"ע ערך אחד הוא עם האותיות דפ' קדש שבקלף גשמי לגבי מדרג' המקיף העליון הכללי שלמעלה מעלה מכל ההשתלשלות דקו\"ח והן בחי' עגולי א\"א שסובבים ומקיפים עד רגלי העשיה בהשוואה אחת ממש ואין חלוקי מדרגו' בהשתלשלות דאבי\"ע רק בבחי' א\"פ דיושר אבל בבחי' העגולים דמקיפין אין חלוק מדרגות כלל בין עליון לתחתון אצי' ועשי' שוין כו' והוא בחי' מקיף הכללי שמקיף לד' עולמות דאבי\"ע בשוה ממש כידוע וד\"ל:\n(מז) <b>וזהו</b> הטעם ג\"כ שלא נמול אברהם עד שנעשה בן צ\"ט שנה דוקא אע\"פ שכבר נצטוה בהיותו בן ע\"ה שנה לך לך מארצך כו' בשביל קיום התו\"מ ברוחניו' עכ\"פ כנ\"ל שזהו עכ\"פ גלוי ההעלם מן העצמות ביותר מכפי המדה וצמצום הראשון דקו\"ח כו'. אמנם אין זה הצווי רק בשביל היח\"ע דאצי' לבד שנק' קיום התו\"מ למעלה ברוחניות לבד שאין האור הזה בא מפנימית דפנימית כ\"כ כמו שנמשך בשביל"],[2300670449,"קיום התו\"מ בחצונית ובגשמיות מטעם כלל הנ\"ל ע\"כ כל משך זמן כ\"ד שנה הללו שמע\"ה עד צ\"ט היה הכל כל עובדות דאברהם לייחד יח\"ע באצי' (כאדה\"ר בג\"ע קודם החטא דכתיב ויניחהו בגן עדן לעבדה להוסיף אורות באצי' וכה\"ג). אך כדי שיהיה מזה הכנה לבנים להיות קשר וחבור מאצי' לבי\"ע לזאת נצטווה על המילה בהיותו בן צ\"ט שזכה אברהם לקיום מצות מילה בגשמיות בבשר ערלתו ולא מקודם לכן כי עד היותו בן צ\"ט לא היה ביכולתו רק לקיים התו\"מ ברוחניות בבחי' הפנימיות כמו שהן למעלה באצי' לבד רק בהיותו בן צ\"ט שנה ניתנה לו מצות המילה בלבד שיקיימנ' בגשמיות ולא שאר מצות זולתה כמצות תפלין וצצית ושבת וכה\"ג (אע\"פ שבודאי היה שומר את השבת כהלכתו כמ\"ש אשר שמע אברהם בקלי כו' ועשה צדקה ומשפט וצוה לבניו לעשות צדקה ומשפט כו' מ\"מ הרי לא נצטוה ע\"ז (רק בז' מצות ב\"נ על עכו\"ם ג\"ע וש\"ד כו' וכמו שאמרו (ע\"ז יד, ב) עכו\"מ דא\"א ד' מאות פרקי הוה כו') והטעם שלא נתנה לו רק מצו' מילה לבד לאות ברי' עול' כו' הענין הוא כדי שיהיה קשר וחבו' לקיו' התו\"מ ברוחניו' דאצי' עם התו\"מ שבגשמיות ואע\"פ שכבר זכו ישראל לקיום התו\"מ בגשמיות ע\"י הגלות דמצרים כנ\"ל אבל לא היה נעשה ע\"י המצות בגשמיות יח\"ע ברוחניות דאצי' כי אין חבור וקשר כלל לתחתונים עם העליונים רק כפי המדה וצמצום הראשון כנ\"ל אבל ע\"י האבו' הרי היה קיום התו\"מ ברוחניות ופנימיות באצי' וע\"כ מצד שהאבות סימן לבנים יכלו להוריש זה לבניהם דהיינו כאשר יזכו ישראל לקבלת התו\"מ בגשמיות יהיה נעשה עי\"ז יח\"ע באצי' בפנימיות וזכות אבות זה ודאי ירשו בנים מן המוכן שכבר הכינו להם האבות כנ\"ל (במשל ירושת הבן מאשר הכין לו האב כו'). ומזה הטעם הוא שניתן לאברהם מצות מילה דוקא בגשמיות בגופו שאם לא היה אברהם נמול בגשמיות לא היה חבור וקשר לקיום התור' ברוחניות עם קיום התורה בגשמיות בישראל ולא היה מועיל ירושת הבנים מאשר הכינו להם האבות במעשיהם למעל' אחר שאין חבור לתחתונים עם העליונים כנ\"ל. אך לאחר שנמול אברהם בגשמיות הרי עי\"ז ירד גם עליו מאור ושרש דתו\"מ בגשמיות עכ\"פ דרך כלל במצות מילה זו שהיא אות ברית בכללות ואז כאשר הוליד אברהם ליצחק בהיותו מהול כבר היה בו הארה זאת ויצחק נולד מאור שפע זו ממש בהולדו מטפה ראשונה שיצאה מבריתו של אברהם שהיה מהול באות הברית קדש שהרי אברהם נמול בן צ\"ט והוליד ליצחק בהיותו בן מאה והוטבע בנפש יצחק שנולד באור העליון הזה שבמצות מילה ויצחק הוליד ליעקב כשהיה מהול בן ח' ימים שמל אותו אביו אברהם עפ\"י דת התורה ובזה היה נפש יעקב יותר שלם ונק' איש תם יושב אוהלים (בראשית כה, כז) דתושב\"כ ושבע\"פ כו' כי היה שלם בשלמות דאברהם ויצחק בבחי' קו האמצעי דתורה כו' בבחי' החבור דתורה הרוחניות עם התורה הגשמיות וכמ\"ש ויקם עדות ביעקב דוקא וזהו מה שהוריש יעקב לי\"ב שבטים בניו והמשיך גם בהם הארה השלמה הזאת שבמילה ולהיות חבור וקשר זה"],[2300670458,"מסתעף מהרוחניות לגשמיות בתו\"מ שיקבלו במ\"ת שמסבת ירושה זאת במילה הוא שיכלו בנ\"י לקבל תו\"מ בגשמיות ושיהי' לקיום זה חבור וקשר גדול עם קיום הרוחני לפי שירשו מאבותיהם חבור זה דרך כלל עכ\"פ ע\"י מצות מילה דאברהם שהוליד ליצחק מברית מהול שקיים בגשמיות כנ\"ל ואם לא היה אברה' מקיים מצות מילה בגשמיות גופו לא היה יצחק נולד מברית מהול ולא היה קשר וחבור זה כלל דאע\"פ שבודאי היה אברהם מל את יצחק בהמול א\"ע בהיותו בן מאה שנה אבל הרי היה נפסק הקשר וחבור מן הקיום הרוחני עם קיום הגשמי במה שהי' יצחק נולד מברית בלתי מהול בגשמיות שלא היתה מצוה בגשמיות נמצאת עדיין באברהם. ואמנם לזה נצטוה אברהם לימול א\"ע שנה אחת קודם שהוליד את יצחק שמילה זאת לצורך הולדת יצחק היתה כדי שיהיה קשר וחבור עי\"ז להוריש לבניהם אחריהם בחי' קשר וחבור דיח\"ע ברוחניות עם המצות בגשמיות ולכך נצטוה אברהם במצות מילה בלבד ולא בשאר מצות זולתה להיותה בבשר גופו ובברית דוקא שיולד ממנו יצחק כנ\"ל וד\"ל:\n(מח) <b>ועם</b> כל הנ\"ל הרי מתורץ הקושיא הנ\"ל מדוע לא נימול אברהם עד היותו בן צ\"ט שנה כי עד אותו זמן היתה כל עבודתו רק ביח\"ע הרוחניות שנק' קיום התורה ברוחניות לבד וע\"ז נצטוה לך לך כו' והן הכ\"ד שנה שעד היותו בן צ\"ט. אך בשביל תולדות יצחק ויעקב להוריש לבניו ענין הקשר וחבור דקיום הרוחני בקיום הגשמי הוא שנצטו' בהיותו בן צ\"ט על מצות מילה שיקיים רק מצוה אחת בגשמיות בגופו ובברית דוקא מטעם שעי\"ז יהיה חבור לרוחניות המצות עליונות במצות הגשמיות שיעשו בניו כל ימי עולם כנ\"ל וד\"ל:\n(מט) <b>ובכ\"ז</b> יובן מה שמצינו בדברי רז\"ל בטעם שלא זכה אברהם למצות בגשמיות לפי שיצא ממנו ישמעאל ויצחק לא זכה מפני שיצא ממנו עשו רק יעקב לפי שהיה איש תם ושלם בתולדות י\"ב שבטים שבטי יה כו' ע\"כ זכו בניו לקבלת התורה בפ\"מ כו' (ע\"י שקבלו עול גלות דמצרים בחומר ולבנים שנשתתף בזה גם יעקב אביהם באמרו (שם מו, ד) אנכי ארד עמך מצרימה כו') והענין הוא מובן עפ\"י הנ\"ל דאברהם קודם המילה היתה כל עבודתו רק למעלה ברוחניות לבד ולכך היה יכול לצאת ממנו ישמעאל בחי' מותרי החסדי' דקדוש' ואיך יכול אור הפנימי' דפנימית שבמצות הגשמיות להתלבש למטה כי היה גם יניקה לחצוני' שהן מפסולת חסד כו' שהוא ישמעאל חסד דק\"נ וראייה שהחזיר' על כל האומו' ולא קבלוה לפי שלא רצה ה' בקבלתם כלל כמ\"ש וזרח משעיר למו הופיע מהר פארן (דברים לג, ב) לפי שאין התו\"מ בפ\"מ ניתן רק לישראל עם סגולתו והוא מפני שיצאו מיעקב שלא היה בו גם למטה שום נטיה לחוץ בבחי' מותרות כלל ולא כיצחק שאע\"פ שנולד אחר שמל אברהם א\"ע מ\"מ יצא ממנו עשו בחי' פסולת הגבורות הקשות כמ\"ש (בראשית כה, כה) ויצא הראשון אדמוני כו' ונא' בו (שם כז, מ) על חרבך תחיה כו' אבל יעקב היה שלם בשלמות דאדם העליון בבחי' הפנימיות ממש שלזה נק' איש תם כו' שלא יצא ממנו לחצונים כלום והיינו"],[2300670467,"בחי' קו האמצעי שנק' בריח התיכון כו' שעולה עד פנימית הכתר כו' וע\"כ הוליד י\"ב שבטים וזכו בניו לקבלת התו\"מ בפ\"מ ששרשן עליון הרבה יותר מקיום התו\"מ ברוחניות כנ\"ל וד\"ל. וא\"כ מזה המאמ' דמטעם שיצא ממנו ישמעאל לא זכה לקיום התו\"מ בגשמיות אע\"פ שכבר זכה לקיום הרוחני' א\"כ יש הוכחה גמורה ששרש המצות במעשה הגשמיות יותר עליון מן קיום תו\"מ ברוחניות וע\"כ לא זכה לקיום הגשמיו' לפי שיצא ממנו ישמעאל וכן יצחק לפי שיצא ממנו עשו כו'. ואמנם עכ\"ז בשביל שיצא ממנו יעקב בבחי' תם כנ\"ל שיוריש לבניו קיום התו\"מ בקשר וחבור אחד עם הרוחני כנ\"ל הוצרך אברהם לימול א\"ע דוקא קוד' שיוליד ליצחק מטעם הנ\"ל כדי שיהיו בנ\"י יכולים לקבל התו\"מ בחיצוני' ולהיו' לקיום הזה קשר וחבור עם קיום הרוחני להוסיף אורות באצי' בכל מצוה מן המצות שיעשה כ\"א מישראל בכל דור מטעם הנ\"ל וד\"ל:\n(נ) <b>ובכ\"ז</b> יובן הפסוק כי הוא עשנו ולא אנחנו (תהלים ק, ג) ויש קרי וכתיב הקרי ולו בוי\"ו והכתיב ולא באל\"ף. דהנה מ\"ש כי הוא עשנו הוא זה ל' נסתר היינו בחי' עצמות אא\"ס שבפנימית הכתר שהוא אות האל\"ף שנק' אלופו של עולם כו' וכידוע בסדר הא\"ב האל\"ף הוא בבחי' הכתר והבי\"ת בבחי' החכמה כי כמו שהאל\"ף הוא ראש לכל האותיות כך הכתר הוא ראש ומקור לנאצלים כידוע. ובאור הענין הנה ידוע דישראל עלו במחשבה שהוא פנימית הרצון ותענוג העצמי כו'. ואמנם ירדו הנשמות למטה בגופים בעה\"ז וכמו אתה נפחת בי כו' וזהו כי הוא עשנו כמ\"ש (ישעי' מג, ז) בראתיו יצרתיו אף עשיתיו בראתיו במחשבה כו' ולפי שנעוץ תב\"ס דוקא ע\"כ על בחי' העשי' דוקא אמר כי הוא עשנו ולו אנחנו כו'. ויובן זה ע\"פ כלל הנ\"ל דכל הגבו' גבוה יותר יותר יורד ומשפיל א\"ע למטה יותר וכך בבחי' מקיף דכתר הכללי שמקיף לד' עולמות דאבי\"ע להיותו למעלה מכל ההשתלשלות דאבי\"ע ביכולתו להשפיל א\"ע למטה מטה מכל ההשתלשלות דאבי\"ע וכמו העיגול ממש שסובב למעלה ולמטה בהשואה אחת ממש ולמעלה הוא בתכלית הרום ולמטה בתכלית העומק וכמו (דברים לג, ז) ומתחת זרועות עולם וכתיב (תהלי' קיג, ה. ו) המגביהי לשבת המשפילי לראות כו' וכן אמר (דברים ה, לט) בשמים כו' כידוע וגם כאן להיות שמסיים בפסוק זה עמו וצאן מרעיתו לפי שמצד הנשמה נק' בנים כמ\"ש כי הוא עשנו כנ\"ל ואומ' אבינו ומצד התלבשות הנשמה בגוף שהוא בחי' יש נפרד או' מלכנו שנק' מלך על עם נפרד ממש כו'. ולכאורה אין לך ירידה גדולה מזו לבחי' עצמות המאציל שהוא בחי' מקיף הנ\"ל להיות מלך על עם כו' להיות אנחנו עמו וצאן מרעיתו על יש נפרד כנשמות בגופים חומריים כ\"כ. אך לזה תירץ בתחלת הפסוק כי הוא עשנו פי' בחי' עשיה דנשמות ישראל גם בהיותם בגופים הרי שרשם נעשה ונמשך מבחי' הוא שהוא בחי' האל\"ף דפנימית הכתר שמקיף לכל ההשתלשלות דאבי\"ע ומתעגל עד למטה כמו למעלה מתחלה לסוף הכל בהשואה אחת ממש לפי שכל הגבוה יותר בעמ\"ר משפיל א\"ע למט' יותר בעומק תחת וע\"כ יכול להיות שאנחנו כמו שהנשמות"],[2300670476,"בגופים עמו וצאן מרעיתו ממש מלך על עם נפרד ממש מאחר שהוא נבדל בערך לגמרי מכל סדר ההשתלשלות דאבי\"ע הרי מעלה ומטה שוין לפניו ממש וראייה מן העה\"ב שיבא בגלוי למטה ממש כמו למעלה כידוע וזהו כי הוא עשנו בבחי' עשיה למטה כמו שהנשמות עלו במחשבה למעלה ממש בלי שנוי כלל וכלל וד\"ל:\n(נא) <b>וזהו</b> ענין הקרי וכתיב בתיבת ולו ולא כנ\"ל דהנה פי' ולו בוי\"ו היינו בחי' הוי\"ו דז\"א דאצי' שהן בחי' המדות שמשם הוא שרש ומקור של נש\"י שנולדו מבחי' יחוד זו\"נ כמו אור זרוע לצדיק עליון כו' (וכמ\"ש בחמץ (שמות יב, טו) ונכרתה הנפש ההוא מיום הראשון עד יום השביעי שהן ז' מדות דזו\"נ דאצי' כו') וזהו ולו אנחנו (והן בחי' עצם המדות שהן ו\"פ וי\"ו שהוא ל\"ו כידוע) אבל באמת אין עיקר וראשית מקור התהוות הנשמות ממדות דאצי' שבאים בדרך יחוד להוליד הנשמות אלא מקור הראשון הוא בבחי' האל\"ף דכתר שהוא בחי' א\"א דאצי' וכמ\"ש בתחלה כי הוא עשנו כו' (והוא בחי' אנפי רברבי שמשם מקור הראשון לתולדות המדות דז\"א שנק' אנפי זוטרי שלמטה מן השכל כמ\"ש (משלי ל, ד) מה שמו ומה שם בנו כו') וזהו ולא באל\"ף והכוונה הוא דשניהם אמת לו ולא לו בז\"א ולא בא\"א ומשניהם יחד הוא מקור ושרש נש\"י דהיינו מבחי' הארת אור א\"א בז\"א מאל\"ף דכתר בוי\"ו דז\"א שזהו מבחי' האין וההעלם דכתר לבחי' גלוי דיש דמדות כו' ואע\"פ שהן ב' הפכי' דאין הוא בלתי בא בגלוי יש ומציאות כלל וזהו ולא בלאו שקדם להן ולו הוא אשר בא בגלוי יש מאין באצי' כמו המדות דז\"א ומאצי' לבי\"ע כו' (עד נפש דעשיה שהוא מכלים החצונים דז\"א כו') אך לזה הקדים בתחלה במ\"ש כי הוא עשנו שהוא בעצמות המאציל שבפנימיות הכתר בכלל ששם שוין בחי' ההעלם דאין עם בחי' היש דמדות שזהו לו ולא לאו והן צמצום והתפשטות יחדיו ישכנו שם ואינם ב' הפכים כלל והטעם ידוע במה שאמ' על בחי' אא\"ס שבפנימית הכתר בכלל דאיהו תפיס בכ\"ע ולית מאן דתפיס ביה כלל הרי יש כאן ב' הפכים בנושא א' דנתפס בכ\"ע ואינו נתפס כלל שהרי אמר למת\"ב כו' ושניהם אמת דאע\"פ שנתפס בכ\"ע אין לעולמו' תפיסה ביה כמארז\"ל (מד\"ת פ\"צ, י) הוא מקומו של עולם ואין העולם מקומו (וזהו (ש\"א ב, ג) ולא נתכנו עלילו' ולו נתכנו קרי וכתיב ג\"כ כי מצד דאיהו תפיס בכ\"ע ולו בוי\"ו ומצד דלמת\"ב ולא באלף ואמנם לו ולא זה שניהם כאחד הוא משום דבשעה שנתפס למת\"ב כלל) וכ\"ה גם כאן בלו ולא אנחנו דמצד דאיהו תפיס בכ\"ע אמר ולו בוי\"ו דהיינו במדות דז\"א שנמשך ממדות דא\"א בבחי' גלוי ההעלם מאין ליש בבי\"ע כנ\"ל ומצד פנימית אור הכתר שלמעל' מכל ההשתלשלות דאבי\"ע ולא באל\"ף משום דלמת\"ב ושניהם כאחד הוא ואינם ב' הפכים כלל משום דבעצמות המאציל שניהם שוים העלם וגלוי כו' וע\"כ גם כשנתפס למת\"ב כמ\"ש במ\"א וזהו ולו ולא שניהם יחדיו ישכנו כאחד והוא לפי שהוא עשנו שהוא מבחי'"],[2300670485,"פנימית ועצמות דא\"ס שבפנימית הכתר כנ\"ל וד\"ל וכ\"ז מצד שבא האור מעצמות הא\"ס שנבדל בערך מכל ההשתלשלות דהעלם וגלוי שבא להיות מקור להשתלשלות כנ\"ל ע\"כ יכול להיות בהתלבשות בעשיה כמו באצי' ממש והן נשמות שבגופים שאמר כי הוא עשנו בבחי' עשיה להיות עמו וצאן מרעיתו ממש כמו שהן בשרשן למעלה בעצמות המאציל ממש בהשוואה אחת מטעם כלל הנ\"ל שכל הגבוה יותר יות' יוכל להשפיל א\"ע למטה בלבושים החצונים ביותר. ובזה יובן ענין האל\"ף דאנכי שהוא מצוה ראשונה די' הדברות נאמרה באלף דוקא כי ידוע דאנכי הוא בחי' פנימית הכתר שאנכי מורה על אמתת אור העצמות ממש והוא כ\"ף דאנכי דהיינו פנימית בחי' אין דכתר וכמ\"ש במ\"א דאין אותיות אני וכמ\"ש (ישעי' מד, ו) אני ראשון שהוא בחי' הכתר כו'. ולהיות שבמ\"ת בי' הדברות הרי נמשך האור דעצמות א\"ס ממש לבא בהתלבשות למטה ממש בדברים גשמיים במצות הגשמיים בעשיה גשמית שזה א\"א כ\"א מכח העליון ביותר מכל ההשתלשלות דהעלם וגלוי כנ\"ל ע\"כ התחלת דבור הראשון היה באל\"ף דאנכי דוקא שהוא פנימית הכתר כנ\"ל וד\"ל:\n(נב) <b>והנה</b> עם כל הנ\"ל מתורץ גם הקושיא הג' דלמה לא נזכר מעלת אברהם בחסד וצדקה שעשה בהכנסת אורחים רק אחר שמל א\"ע כמ\"ש בפ' וירא ולא קודם לכן רק בדרכי נסיעותיו בא\"י נזכר בו מקודם המילה כמ\"ש ויעבר אברם בארץ כו' וקודם שבא לא\"י עד היותו בן ע\"ה שנה לא נזכר בו כל צדקה וחסד שעשה ולא כל מעשיו והילוכו כו'. הרי שיש כאן ג' מדרגות א' עד היותו בן ע\"ה שנה והב' מע\"ה עד צ\"ט שהן כ\"ד שנה והג' אחר היותו בן צ\"ט לאחר המילה כו'. והענין הוא דמדרגה הראשונה כשהיה באור כשדים קודם שא\"ל לך לך כו' אע\"פ שכבר קיים שם כל התו\"מ ברוחניות למעלה באה\"ר ודביקות אמיתית וגייר רבים מעמי הארץ כו' הרי היה כל יח\"ע שעשה רק בהעלם בבחי' ח\"ס שנק' אברם כנ\"ל ע\"כ לא נזכר מכל עניניו ומעשיו כלום עד שהיה בן ע\"ה שנה שיצא מאור כשדים והוא מדרגה הב' שא\"ל לך לך מארצך כו' שהוא להתעורר לבא מן ההעלם לגלוי באצי' עכ\"פ עד שבא לא\"י עלמא דאתגלייא אז נזכר בו כל נסיעותיו ואשר קרא שם בשם הוי\"ה כו' כנ\"ל ואע\"פ שעדיין נק' בשם אברם כו' והן אותן כ\"ד שנה עד שהיה בן צ\"ט שנה שנמשך כל יח\"ע מן ההעלם לגלוי מעצמות המאציל בע\"ס דאצי' עכ\"פ שנק' קיום הרוחני כנ\"ל. והמדרגה הג' הוא כאשר נצטווה על המילה בהיותו בן צ\"ט שנה שהוא בשביל קשר וחבור דקיום הרוחני דאצי' לבא בגלוי בבי\"ע במצות הגשמיות להוריש לבניו כנ\"ל וע\"כ רק למצות מילה בלבד זכה לקיים בגשמיות מטעם הנ\"ל ואז נק' אברהם בה\"א שהן בחי' ה\"ח הראשונים שבעצמות ממש שיכול לבא למטה ממש ע\"כ נזכר בו אז מכל החסד בהכנסת אורחי' שלו שבא יח\"ע שעשה למעלה גם למטה ממש והוא מ\"ש בפ' וירא וכן מ\"ש המכסה אני מאברהם כו' כי ידעתיו את אשר יצוה את"],[2300670494,"בניו כו' ושמרו דרך הוי\"ה לעשות צדקה ומשפט דהיינו מה שעל ידו נעשה קשר וחבור להמשיך יח\"ע הרוחנית למצות הגשמיות וזהו שיצוה לבניו לעשות ולשמור דרך הוי\"ה שלמעל' לבא למטה בגשמיות וזהו למען הביא ה' על אברהם כו' שזהו גלוי אלקות בא\"י ע\"י קיום התו\"מ דבנ\"י כו' ונמצא דג' מדרגות הללו הן בירידת האור למטה יותר שזהו מורה על עוצם מעלת האור בשרשו יותר כפי כלל הנ\"ל והיינו שקיים היח\"ע שהיה בהעלם דח\"ס עד שהיה בן ע\"ה שנה ואח\"כ יצא לגלוי באצי' בכ\"ד שנה הנ\"ל ומצ\"ט שנה ע\"י המילה שירד האור יותר לקשר ולחבר אצי' בבי\"ע כנ\"ל וד\"ל:\n(נג) <b>ומעתה</b> יובן סדר דברי הפרשה הזאת בתוס' באור במ\"ש ויאמר ה' אל אברם לך לך מארצך כו' אל הארץ אשר אראך שזה מבואר למעלה ויש בו ב' פירושים כנ\"ל הא' כפי' הזהר מלמעלה למטה דהיינו מארצך בבחי' בינה סתימאה שמקבלת מח\"ס וע\"ז אמר לך לך מארצך שבחי' נקודה דח\"ס דטמיר וגניז בבינה לבא מן ההעלם לגלוי למטה בבחי' המל' דאצי' סופא דכל דרגין דאצי' שהוא א\"י כו' ופי' הב' שבס' לק\"ת הוא להיפך שיעלה מלמטה למעלה בבחי' או\"ח להביא ולהעלות מעולם הפירוד שנפל למטה דהיינו מארצך אור כשדים ויעלה משם לעולם היחוד בפנימית דבינה עלאה שז\"ש אל הארץ אשר אראך שהוא א\"י העליונה ה\"א עלאה דשם הוי\"ה כידוע ושני הפירושים אמת כנ\"ל בפי' וילך למסעיו שהיה קשר וחבור מלמעלה למטה ומלמטה למעלה וכמ\"ש אל המקום אשר היה אהלה כו' וכן בפי' אראך דקאי על א\"י או על אברהם שני הפירושים אמת וכנ\"ל וד\"ל:\n(נד) <b>ומעתה</b> יש להבין מ\"ש ואעשך לגוי גדול ואברכך ואגדלה שמך כו'. דהנה מה שלא אמר לו עד כה שיברכנו ויגדל שמו אע\"פ שכבר היה ראוי לכך מצד מעשיו הטובים בכל יח\"ע שעשה בעבודתו ותפלתו אבל היה הכל עדיין בבחי' ההעלם דח\"ס הנ\"ל אך כאשר יצא מההעלם לגלוי שז\"ש לך לך מארצך כו' שאז יתגלו יח\"ע שלו מעצמות המאציל באצי' בתוס' אור בכלים כנ\"ל ע\"כ אמר לו עכשיו דוקא ואברכך ואגדלה שמך למעלה בכל האורות העליונים מפני שיומשך מבחי' מל' דא\"ס תוס' ברכה ע\"י היח\"ע הללו שנק' שמו הגדול ויתגדל שמך כשמו הגדול ממש כמו ענין יהא שמיה רבא כו' כידוע והוא לפי שיומשך הכל בא\"י שהוא הארץ אשר אראך ששם יהיה לגוי גדול ע\"י בירור הניצוצות דתהו שנפלו שם מז' מלכין קדמאין כו' וז\"ש ואעשך לגוי גדול ואברכך כו' עד והיה ברכה שיתברכו בו כל האורות ומדרגות העליונות ביחודים שתעשה למעלה מצד בחי' הבירורים דניצוצות דתהו שע\"י עולים למעלה ומוסיפים תוס' אור גדול כמו הגרים אשר עשה וכל אשר העלה ממצרים כמ\"ש ויעל אברם ממצרים כו' ובפרט ע\"י מצות מילה שנק' אב המון גוים שז\"ש והיה ברכה לעתיד וד\"ל:\n(נה) <b>וכל</b> ענין הברכה הזאת הוא בקו הימין חח\"נ דוקא שמאיר בתוס' ברכה עליונה מעצמות המאציל"],[2300670503,"ע\"י הצדקה וגמ\"ח ובירור הניצוצות דתהו כו' וכמ\"כ עכשיו בכל תפלה בג\"ר שבה הרי בברכה הראשונ' שהיא לנגד אברהם או' אלקי אברהם כו' אל עליון גומל חסדים טובים קנה הכל כמו ברוך אברם לאל עליון קנה כו' וכמאמר ה' קנינים הן אברהם קנין א' כו'. והענין הוא לפי שגמל חסדים טובים מחפץ חסד הראשון שנק' חסדים טובים שיורדים בה\"א דאברהם למטה מטה ביותר מטעם כלל הנ\"ל ע\"כ קונה הכל להעלות כל הניצוצות דתהו מעולם הפירוד לעולם היחוד שנק' קנין מרה\"ר לרה\"י כו' ואח\"כ זוכר חסדי אבות שהוא בחי' חסד דאברהם להיות גואל לב\"ב למען שמו פי' למען שמו הגדול באה\"ר שהיה נמשך ע\"י אה\"ר דאברהם להיות כריתות ברית זה לבניו לעולם וכמ\"ש (ויקרא כו, מד) לא מאסתים כו' להפר בריתי אתם כו' שזהו ענין הברכה בפנימית לזכור חסדי אבות לבנים להיות יח\"ע שבעצמות ממש למטה כמו למעל' ממש והוא בימי המשיח והעוה\"ב והכל ע\"י אהבה וחסד דאברהם וזהו ומביא גואל ראשון ואחרון לב\"ב הכל למען שמו באהבה שז\"ש כאן ואברכך ואגדלה שמך בכתר שם טוב דמשיח שיהיה עליית המל' בבחי' מל' דא\"ס ממש וכמו עד דוד הגדיל (ש\"א כ, מא) וכמ\"ש במ\"א ומסיים בברכה זו מגן אברהם שזהו נמשך מבחי' מקיף דכתר הכללי הנ\"ל וכמ\"ש אנכי מגן לך שכרך הרבה מאד בחי' א' דאנכי הוא המגן ומקיף לחסד דאברהם כו' שכרך ע\"י הבירור דניצוצות דתהו הרבה מאד בלי גבול מצד יתרון האור כו' וד\"ל:\n(נו) <b>וילך</b> אברם כאשר דבר אליו ה'. פי' מיד שנתן לו ה' כח לצאת מן ההעלם דבחי' ח\"ס הנ\"ל הנק' שכל הנעלם מכ\"ר כנ\"ל תיכף הלך אברם בכח הזה דוקא מבחי' ההעלם שבעצמות ונתגלה אורו למטה בעולם דאצי' להוסיף אורות ויח\"ע בגלוי מן ההעלם וז\"ש וילך אברם כו' (ומ\"ש כאש' דבר אליו ה' היינו שהלך רק כאשר דבר אליו ה' שלא נטה ימין ושמאל רק כפי שהוא באור אמתת עצמות המאציל כנ\"ל בפי' אז ראה כו'). וילך אתו לוט. פי' לוט הוא גי' מ\"ה והוא בחי' אחוריים דשם מ\"ה דאברם כידוע דאברם אבר מה לאחר שנפרד לוט מעמו וכמ\"ש וה' אמר אל אברם אחרי הפרד לוט מעמו כו' ותחלה קוד' שנפרד לוט היה כלול באברם דקדושה כמו שבחי' האחוריים וחצוני' טפל ונכלל בפנימית ויוצא עמו יחד כו' וזהו וילך אתו לוט בבחי' אחוריים דשם מ\"ה ממילא ומאיליו כו'. ובאור ענין לוט היינו בחי' הסיגים ופסולת דחכמה דקדוש' שנק' אור אבא בכלל ואב רם נק' ח\"ס כמו שהחכמה בבחי' אין ומ\"ה ממש ולוט הוא בחי' החצונית וסיגים שבחכמה והוא בחי' גבורות קשות שמסתעפים מכח הדין שבחכמ' כו' וע\"כ נק' לוט לווטין וקללות. וע\"ד דוגמא ממה שאנו רואים במי שמדקדק בעומק החכמה במדת הדין יותר ימצא החוב גם להרשיע את הצדיק וכו' והוא ענין הסתעפות הגבורו' קשות דת\"ח כענין חויא דרבנן (שבת קי, א) שכועס ביות' כנחש דלית לי' אסוותא כו' וכמ\"ש במ\"א בענין נחש הנחשת דמשה וגם כאן מיד שיצא בחי' החסד דאברם דבחי' ח\"ס כנ\"ל יצא"],[2300670512,"ונטפל אתו לוט בחי' אחוריים דאבא (שהוא בחי' גבו' דחכ' החיצונית) וז\"ש וגם ללוט ההולך את אברם היה צאן ובקר כו' וגם בענין הצווי לאברם לצאת מן ההעלם לגלוי וילך אברם כאשר כו' שהוא בחי' אור פנימית אבא מיד יצא וילך אתו לוט שנטפל לצאת גם בחי' אחוריי' דאבא יחד עם בחי' הפנימי' וזהו שלא נברר ונבדל עדיין הפנימית מן החצונית כי היה הכל בתערובת יחד בלי הבדלה כלל ע\"כ אמר וילך אתו לוט כו':\n(נז) <b>ויובן</b> ד\"ז ע\"ד שאמ' בזהר ביצחק ועשו דרישא דעשו בעטפוהי דיצחק כו' פי' עשו איש שעיר והוא אדמוני מבחי' גבורות קשות שנופל מבחי' מותרות ופסולת דגבור' דיצחק דקדושה שנק' פחד יצחק כידוע וקודם שנברר הפנימית דגבו' דיצחק מן החצונית היה שרש עשו נכלל בפנימית דגבו' דיצחק בלי הבדלה כלל לפי שלא היה ניכר בחי' הסיגים ופסולת בגבו' דקדושה כלל בפ\"ע מצד התכללותם בפנימי' דגבו' והיו לאחדים ממש וכמשל המצרף לכסף שקודם ההתוך הסיגים מעורבים ומתכללי' בטוב ומובחר בלתי ניכרים לפסולת כלל ואחר גמר ההתוך במצרף שיוצאים הסיגים מובדלי' בפ\"ע וניכרים יותר והטוב שנעשה ברור מכל סיג בתכלית במעלה הרבה מכמו שהיה בראשונה בהיותו מעורב עם הסיגים יחד וכן במשל המסנן יין משמריו. וכה\"ג יובן שאחר הבירור דגבו' דקדושה יצאו גבו' קשות דעשו הנק' סיגים נבדלים בפ\"ע אבל קודם הבירור היה נכלל בגבו' דקדושא וז\"ש רישא דעשו בעטפוהי דיצחק ממש כו' וגם כאן יובן עד\"ז בבחי' החכ' דאברם שקודם הבירור היו בחי' אחוריים וחצוניות דלוט גי' מ\"ה דחכמה כלולים באור הפנימית דאבא ומתאחד בו ממש וזהו וילך אתו לוט אתו עמו ממש (והוא בחי' יש דחכמ' כמו ראית איש חכם בעיניו כו' (משלי כו, יב) שמזה מסתעף גבו' קשות דלווטין וקללות כנ\"ל) בהתאחדות והתכללות אחת כמו הסיגים שבכסף קודם שבאו בהתגלות בהבדלה בפ\"ע כו' ואחר שנברר הפנימית דחכמה דמ\"ה העליון מן החצונית והסיגים אמר אברם אל לוט הפרד נא מעלי אם השמאל כו' שלא ילך בחי' החצונית עם הפנימית בתערובות אלא אם הימין להרחיק החצונית דחכמה דמ\"ה דקדושה כו' (מצד שהיה מריבה בין רועי לוט עם רועי אברם מפני בחי' תערובות טו\"ר בחסדים עליונים כו') שנמשך ביותר לחצוניות ואחוריים כו' וז\"ש והכנעני והפריזי אז בארץ שמקבלים החצונים בארץ כנען קודם הבירור דשם ב\"ן כו' וזה היה ענין הבירור בין פנימית לחצוניות כדי שיובדלו הסיגים דלוט בפ\"ע בעשו שיצא מיצחק (אבל ישמעאל שנולד מאברם ממש לא הפרידו מעמו אדרבה בקש עליו לו ישמעאל יחיה לפניך אע\"פ שהיה גם הוא מבחי' המותרות דחסדים דקדושה כו') וזה שהפריד לוט כדי שלא יעבור עמו בארץ כנען שהוא חלקו של אברהם להיות ששם לא יומשך רק מבחי' הפנימי' דקדושה לבד וזהו ויסע לוט מקדם כו' אברם ישב בארץ כנען כו' ואחרי הפרד לוט מעמו אמר לו שא נא עיניך כו' כי את כל הארץ אשר כו' קום"],[2300670521,"התהלך בארץ כו' שלא יתערב זר בתוכה לאחר שנפרד לוט וישב בערי הככר וז\"ש ויאהל אברם כו' וד\"ל:\n(נח) <b>והנה</b> לאחר שנפרד לוט שהוא בחי' אחוריים דשם מ\"ה דחכ' דקדושה והיו בבחי' סיגים גסים ביותר ומובדלים ע\"ד הנ\"ל בעשו שיצא מיצחק כו' אז נעשה מקור להוליד לבחי' חו\"ב דקליפה שהן עמון ומואב שהוליד מב' בנותיו שלא היה בא לזה בהיותו באחדות והתכללות עם בחי' פנימית דמ\"ה דאברם כו'. והענין הוא כידוע דעמון אותיות נועם והוא בחי' בינה דקליפה והטעם הוא לפי שהתענוג הנק' נועם עיקר התגלותו בבחי' התרחבות דבינה שנק' רחובות הנהר (בראשית לו, לז) והוא לנגד בחי' בינה דקדושה שבה התגלות התענוג שנק' נועם העליון וע\"כ בא בתבת עמון בהפוך אתוון וקליפה דמואב הוא מבחי' אב דהיינו בחי' חכ' דקליפה כמ\"ש במ\"א בענין אכלה ער מואב כו' (במדבר כא, כח) שהוא מחצונית ואחוריים דחב\"ד דקדוש' שנק' אב כידוע וב' בנות לוט שהולידו ב' אומות הללו ששרשן בחו\"ב דקליפה נתבררו ויצא מעמון נעמה העמונית אמו של רחבעם בן שלמה ורות המואביה כידוע וד\"ל. ועיקר הבירור שלהם היה בימי שלמה כשישב על כסא ה' בבחי' שלימות דח\"ת בח\"ע דכתיב (מ\"א ג, טז) אז תבואנה שתים נשים זונות כו' (שהן בחי' חו\"ב דקליפה עמון ומואב שנתבררו אז דוקא כידוע):\n(נט) <b>ואברם</b> בן חמש שנים ושבעים שנה בצאתו מחרן וארז\"ל בצאתו מחרון אף של מקום כו'. ולהבין זה הנה יש להקדים תחלה מהו ענין חרן כו' להיות מבואר בכתבי האר\"י ז\"ל בענין חרן שזהו בחי' מיצר הגרון ששם בחי' דינין דמוחין דקטנות ביותר וע\"כ נק' חרון אף כו'. ובאור הדברים הנה ידוע בענין בחי' מיצר הגרון שהוא המקום הממוצע בין בחי' המוחין שבראש לבחי' המדות שנולדים מן השכל וע\"כ נקרא מצר כמו שמבואר בענין יצ\"מ במ\"ש (תהלים קיד, א) בצאת ישראל ממצרים כו'. והענין הוא כידוע בנפש האדם בהתהוות תולדות התפעלות המדות שבלב מן ההשגה ושכל שבמוח שזה בא בבחי' דלוג הערך ממהות למהות אחר ממש כי מהות התפעלות המדות אינם מסוג וערך למהות השכל שבמוח ואין המדות אף בדומה למהות השכל כלל לא מניה ולא דוגמתו וכל מוליד יוליד בדומה לו עכ\"פ ואם יחוייב ענין תולדות התפעלות המדות מן השכל שבמוח הרי היה בהכרח שיהיו המדות בדומות למהות השכל עכ\"פ וא\"כ לכאורה איך יתהווה מהות המדות שבלב מן השכל שבמוח ואנו רואים שתיכף שיתפעל בשכל יתפעל בלב כפי אופן התפעלות השכל ממש כו'. אך הענין הוא כידוע שהשכל וההשגה משכנו בכלי המוח ואם היה מהות התפעלו' השכל מיד שנתפעל במוח יורד ללב לא היה באפשרי כלל להשתנות למהות מדה שבלב. אך הנה כל התפעלות שבמוח יורד ונמשך מן המוח אל הלב דרך ממוצעים והן קנה וושט והעיקר הוא הקנה שהוא הממוצע בין המוח והלב להביא ולהמשיך בכלל בחי' רוחניות החיות שבמוח ללב (כמ\"ש במ\"א בענין תלתא קני הוו חד"],[2300670530,"פריש ללבא וחד פריש לריאה כו' (חולין מה, ב) וע\"כ גם באור התפעלות השכל שבמוח הוא בטעם האהבה או היראה שנק' שכליים שבמוח כאשר יורד ללב בא ונמשך ע\"י הקנה שבגרון הממוצע הנ\"ל (ושם הוא יציאת הקול הממוצע מהבל הלב והמוח יחד ע\"כ קול מעורר הכוונה שבלב ומוח יחד כו'). ואמנם בהגיע אור שפע המוחין בגרון שם השכל והטעם שבמוח מתצמצם ומתעלם לגמרי דהיינו שמתקצר ועולה למעלה כאילו אינו במציאות שכל עד שמושלל שם מבחי' השכלה שכליי' לגמרי כי נפשט ונתעלם מצד בחי' מצר הגרון שמצמצמו ומעלימו לגמרי לפי שצריך שיומשך ויתהווה התחלת התפעלות המדה בלב במהות אחר לגמרי ואמנם גם מבחי' מדה מושלל שם עדיין אחר שצריך לבא שם בשנוי המהות ממהות שכל להיות מהות המדה ע\"כ אין שם לא ממהות השכל ולא ממהות מדה כדרך כל ממוצע שמתעלם בו העליון אז מביא לידי גלוי בשנוי המהות האחר כו' ע\"ד דוגמא מן החטה שצריך שתרקב ויבוטל ממשה וצורת' הראשון ואז מתלבש בה כח הצומח להצמיחה מחדש שבודאי בהיותה מורקבת לגמרי אינה כלום מצד שהפסידה צורתה הראשון שנכללה בכח הצומח ועדיין לכלל צורה החדשה לא באה כו' וכך כל תולדה חדשה צ\"ל בטול והסתלקות בתחלה ואח\"כ יומשך בשנוי מהות כו' וכמ\"ש במ\"א. וגם כאן יובן בבחי' מצר הגרון דלזה נק' בשם דינין דקטנות ונק' מצר מי לפי ששם הוא בחי' תכלית צמצום והסתלקות המוחין למעלה וגם צמצום דמדות שלא בא עדיין למהות מדות כנ\"ל ולכך שם הוא תכלית הדינין והקטנות מכל צד מצד המוחין והמדות כו' עד שיתפשט האור למהות מדות בלב דוקא (כמשי\"ת) וד\"ל:\n(ס) <b>וזהו</b> כללות ענין חרן הנ\"ל שהוא בחי' מיצר הגרון שמפסיק ומבדיל בין המוחין שבראש למדות שבלב להיותו בבחי' ממוצע כנ\"ל וע\"כ שם הוא תכלית הדינין והקטנות והצמצומים שנק' חרון אף של מקום וד\"ל:\n(סא) <b>וזהו</b> ואברם בן חמש שנים ושבעים שנה בצאתו מחרן פי' חמש שנים תחלה ואח\"כ שבעים שנה להיות ידוע בענין שבעים שנה שזהו כאשר ז' המדות כלולים כאו\"א מי' עולה ז\"פ י' שבעים כזקן בן שבעים שנמשך מבחי' ג\"ר כח\"ב בכל מדה מז' המדות וכמ\"ש ראב\"ע הרי אני כבן ע' שנה כו' (ברכות יב ע\"ב) משא\"כ כשאין המדות כלולים רק מז' שהן ז' פעמים ז' שהן מ\"ט ש\"ב לבד כידוע וגם כאן הנה מבואר למעלה בפי' חרן שהוא מצד הגרון ששם המוחין בהסתלקות ונעשים שרש להתחלת מציאות המדות ע\"כ שם הדינין וקטנות דכאשר המוחין מתפשטים במדות בהרחבה נמתקו כל הדינין וקטרוגים לפי שיש בכח החכ' להמתיק כל הדינין בחסדים להיות החכמה הוא מקור החסד שזהו קו הימין חכ' חסד נצח וכידוע דאבא מקור החסדים כמו אבינו אב הרחמן כו' שכל שיש הרחבת המוחין יכול למצא שכל לזכות וחסד ולהמתיק לדין הפוכו וכמו ויאמר לא אוסיף לקלל כו' כי יצר לב האדם רע כו' (בראשית ח, כא) הרי אותו הטעם שחייבה מדה\"ד שאמר כי רבה רעת האדם הוא עצמו נהפך לזכות כי יצר כו' וכן"],[2300670538,"היה בי' דורות שמנח עד אברהם שלא היה גלוי אור המדות עליונו' במוחין דחב\"ד רק בהעלם בתוך כל מדה והגם שכל מדה כלולה מז' שהן זפ\"ז שלא היו מבחי' אור אבא בגלוי בכל מדה ע\"כ היה אז בחי' גבורה ודינין הרבה וכ\"ז מצד שהיו המוחין במצר הגרון שנק' חרן והוא חרון אף של מקום כמו בדור המבול ודור הפלגה וכה\"ג עד שהיה אברם שהוא בבחי' ח\"ס שיצא מבחי' גלוי החכ' בכל מדה שהן ע' שנה שכלולים כאו\"א מחב\"ד חג\"ת נהי\"מ הרי נמתקו כל הדינין שבמיצר הגרון והוא לפי שיצא אור המוחין דחב\"ד להתפשט במדות ולהיות בהרחבה וגדלות הפך הקטנות וצמצום המוחין ומדות ומצר הגרון כו'. אך ענין חמש שנים שהזכיר קודם לע' שנה הן בחי' ה\"ח דאבא שנמשך מאור הכתר להגדיל המדות בבחי' הפנימית שלהם והוא בחי' ג\"ר כח\"ב שבכל מדה דאע\"פ שגם תחלה היו המדות כלולים מי' עדיין לא היה בחי' הכתר בכל מדה שהוא בחי' הפנימית ועצמות שלמעלה גם מן החכ' (וכמו יהי רצון מלפניך שיכבשו רחמיך את כעסך הרי נתגבר רצון של חסד ורחמים על רצון של דין שנגד השכל והטעם מצד הארת פנימית הכתר בכל מדה עד שיכול לגבור בכח ורצון של חסד לכבוש לרצון דמדה\"ד כו'):\n(סב) <b>וזהו</b> ואברם בן חמש שנים ה\"ח המגדלי' המדות להיות כלולים מכח\"ב ושבעים שנה הן ע' שנה דזקן שקנה חכמה שאז נמשך מוחין דגדלו' במדות ונמתקו כל הדינין דקטנות וזהו בצאתו מחרן מחרון אף של מקום שיצא אז מכל הדינין דקטנות שמסתעף מזה חרון אף כו' כי האיר מאז והלאה פנימית דאור הכו\"ח במדות ונמתקו הדינין כנ\"ל וד\"ל:\n(סג) <b>ויעבר</b> אברם בארץ עד מקום שכם עד אלון מורה פי' לאחר שהאיר אור פנימית החכמה (שנק' פנימית אבא שהוא ח\"ס הנ\"ל והוא פנימית ע\"י כמ\"ש בע\"ח) בכל ע\"ס דאצי' שבכאו\"א מן המדות דאצי' כנ\"ל ויצא מחרון אף של מקום להמתיק כל הדינים בחסדים העליונים משם עבר אברם עוד לבא למטה יותר דהיינו לבחי' המל' דאצי' (שהוא בחי' נוק' דז\"א) שהוא בחי' שם ב\"ן וקודם הברור נק' ארץ כנען כידוע להאיר בה בכל הע\"ס שבה באו\"כ מבחי' פנימית דאור אבא דאצי' וזהו ויעבר אברם בארץ שעבר הארתו גם בארץ כנען וע\"ז היה עיקר הצווי דלך לך מארצך אל הארץ אשר אראך בחי' עלמא דאתגליא כנ\"ל משום דנתב\"ס דוקא מבחי' שם ע\"ב דחכמ' והוא גי' חסד שהוא חסד דאברהם להאיר בסופא דכולא דוקא שהוא שם ב\"ן דארץ כנען קודם הבירור כמ\"ש והכנעני אז בארץ שיונקים בה גבו' קשות דחם אבי כנען כו' והן מ\"ח צרופי' האחרוני' דשם אלקים שירד למטה ביותר בז' אומות הכנעני והחתי כו' שהן שיורי הז\"מ שלא נתבררו כו'. וזהו עד מקום שכם פי' שכם הוא הכתף והוא בחי' אחוריים דחו\"ג ואחוריים דדעת כי בפנים מאיר מפנימית המוחין דחב\"ד במדות דלב ובב' ידים ימין ושמאל ולנגד זה נמשך באחוריים דמוחין בכתפיים בחצוניות דחו\"ג והוא כתף ימין וכתף שמאל כו' מבחי' הדעת דבין כתפיים"],[2300670546,"כידוע וגם כאן אמר שעבר אברם בארץ כנען שהוא בחי' שם ב\"ן דאצי' שירד למטה מאד ונק' ארץ כנען כנ\"ל עד בחי' אחוריים דנוק' והוא בחי' כתפיים דהיינו אחוריים דחו\"ג שבה מחצונית הדעת כנ\"ל ואלון מורה הוא בחי' ת\"ת דנוק' דז\"א כו'. והענין הוא לפי שכל עיק' ענין העברה זו דאברם בארץ היה רק להמשיך במל' מכל פנימיות האורות עליונים דחו\"ב ומדות דז\"א בנוק' שהוא שם ב\"ן להאיר גם בבחי' אחוריים וחצונית שבה בהיותה בהתלבשות בכנעני בבחי' גבו' קשות מאד להמתיק אותן ג\"כ באור חסד עליון דאברהם כו' לפי שכח דאור אבא הפנימית שבאברם גדול יותר עד שיכול להוריד האור והשפע גם למטה מטה ביותר גם באחוריי' דע\"ס דנוק' דז\"א כו' להמתיק גם בחי' הגבו' קשות דכנען שמקבל מפסולת דגבורה דקדושה וזהו שעבר עד שכם ואלון מורה לברר ולהעלות גם לבחי' הכתפיים דנוק' כמו לע\"ל דכתי' (צפניה ג, ט) אז אהפוך אל עמים שפה ברורה כו' לעבדו שכם אחד וכ\"ז מטעם כלל הנ\"ל שכל הגבוה גבוה יותר יותר יוכל להוריד ולהשפיל עצמו למטה ביותר והיינו שהיתה תחלת ירידתו של אברם מלמעל' למטה באמרו לך לך מארצך כו' להאיר אור אבא בכל הע\"ס דאצי' כנ\"ל עד שירד עד למטה יותר עד מקום שכם ואלון מורה כנ\"ל וד\"ל:\n(סד) <b>ויעתק</b> משם ההרה מקדם לבית אל כו' פי' אחר עוצם היריד' שירד מאד למט' מטה עד מקום שכם ואלון מורה כנ\"ל שזהו בבחי' או\"י דחסדים דאבא שהולך ונמשך עד למטה מטה מאד להאיר גם את החשך דק\"נ דגבורו' קשות דכנען שנאחזים באחוריים דשם ב\"ן כנ\"ל אז אח\"כ חזר ועלה מלמטה למעלה עלייה דאו\"ח עד בחי' פנימית הכתר דמל' שאין שם שום צד לחצונים כלל וכמ\"ש (ישעי' מב, ח) וכבודי לאחר לא אתן כו' וזהו ויעתק משם ההרה בה\"א הידיעה דהיינו בראש ההרים כמו מי יעלה בהר ה' כו' (תהלים כד, ג) וטורי נהורא הן מדות שבחכמה וה\"א דההרה הן למעלה מן מדות דחכ' שהוא בפנימית הכתר דמל' (שנק' טורי חשוכא והן הרי קדם כעליית המל' ביו\"כ דכתיב (בראשית ח, ד) ותנח התבה כו' וזהו מקדם לבית אל דחכ' נק' אל והוא בחי' חכמה שבמל' כמו בראשית בי\"ת דבראשית היא החכ' שנאמר (משלי כד, ג) בחכמה יבנה בית שהן כל מע\"ב והוא כאשר החכ' מאין דכתר תמצא בגלוי מן ההעלם והוא בי\"ת דבראשי' שע\"כ אמרו (ר\"ה לב ע\"א) בראשית נמי מאמר הוא כידוע וזהו שנק' בית אל דחכ' אבל מקדם לבית אל היינו למעלה מן החכמה והוא בבחי' ההעלם דעצמות אור הכתר שבמל' שנק' ההרה וד\"ל. ועלייה גדולה זו מלמטה למעלה כ\"כ היה מצד שירד בתחלה למטה בירידה עד מקום שכם כו' לברר ולהפוך חשוכא לנהורא מגבו' קשות דק\"נ ועי\"ז נעשה יתרון האור מן החשך שלמעלה מן אור דחכמה כו' דהיינו להיות גלוי האור מבחי' ההעלם דחשך סתרו כידוע וכח ירידתו היה מבחי' הכתר דוקא כנ\"ל וד\"ל:\n(סה) <b>ויט</b> אהלה והיה צריך שיכתוב אהלו בוי\"ו ואמר אהלה בה\"א לפי שהיא עליית המל' בבחי' כתר מלכות"],[2300670554,"שע\"ז נאמר (משלי יב, ד) אשת חיל עטרת בעלה לאחר שלמות הברור דשם ב\"ן כמ\"ש (תהלים קיח, כב) אבן כו'. וזהו ויבן שם מזבח לה' ויקרא בשם הוי\"ה כו' והגם שכבר אמר בהעברתו בארץ ויבן שם מזבח לה' הנראה אליו לא אמר שם ויקרא בשם ה' עד שנטה אהלה מקדם לבית אל כו' בבחי' העלייה דוקא לפי שבבחי' הירידה שירד מלמעלה למטה להאיר במל' בנה מזבח שם לה' הנראה אליו שם מן ההעלם לגלוי בלבד אבל בחזירתו לעלות ההרה שבא עם העלאת הבירורים דרפ\"ח כו' שבירר והעלה משם ב\"ן שיש מזה יתרון אור גדול מבחי' חשך סתרו העליון יותר אז בנה שם מזבח חדש להוי\"ה בתוס' אור גדול ויקרא בשם הוי\"ה שהיה ביכולתו לקרוא ולהמשיך שם הוי\"ה דאו\"א שבז\"א לבחי' המל' לייחד יחוד דזו\"נ שהן ב' שמות דהוי\"ה ואלקים בחי' מ\"ה וב\"ן משא\"כ קודם הברור דשם ב\"ן אע\"פ שנראה אליו ה' היה רק אליו לבדו כמו שהוא בבחי' שם מ\"ה. ואמנם לאחר עלייתו למקדם לבית אל בבחי' פנימית הכתר אז קרא בשם הוי\"ה במל' שיהיה נק' שם להוי\"ה ביחוד גמור וכמו ביום ההוא יהיה הוי\"ה אחד ושמו אחד (זכרי' יד, ט) למהוי אחד באחד ממש ולא יהיה שם ב\"ן בבחי' פירוד משם מ\"ה דהוי\"ה לעולם וד\"ל:\n(סו) <b>וכ\"ז</b> היה קודם המילה שעשה קשר וחבור באצי' לבי\"ע עד למטה ביותר (וכמו שמסיים ויסע אברם הלוך ונסוע הנגבה בה\"א הידיעה בבחי' העלאה דרו\"ש להעלות הכל ביח\"ע עד בחי' ה\"ח הראשונים שבנגב דדרום מקור כל החסדים דאבא והוא מנגב לבית אל דחכמה כו'). אך אחר המילה מעלה יתירה היה בו שהיה יכול לאסוף ולקבל כל נצוצות דתהו שנתפזרו בע' שרים דנגה כמ\"ש כי אב המון גוים כו' וגם ישמעאל כשנמול אמר לו ישמעאל יחיה לפניך ממש כו' משא\"כ קודם לכן לא היה ביכולתו לחבר ולהעלות הנפרדים ממש שהוא רע גמור דנוגה שהוא עכשיו התשובה שהרע עצמו נהפך לטוב ממש כידוע אלא דוקא אחר שקרא בשם ה' ונבנה בנין המל' גם בבחי' האחוריים וחצונית כשכם ואלון מורה כנ\"ל אזי ממילא נכללו בה כל הניצוצות שנדחו ונתפזרו ונשקעו בע' שרים בבחי' רע גמור שיוכללו גם הם בקדושה כבטול הנר בפני האבוקה וכמ\"ש כי אב המון כו' וזהו מצד ה\"א דאברהם דוקא כנ\"ל וכמ\"כ יובן הטעם שאחר המילה אמר שרי אשתך לא תקרא את שמה שרי כי שרה שמה בה\"א כי מיו\"ד נעשה ה\"א מטעם בירור דשם ב\"ן לכל ניצוצות שנפלו בע' שרים נק' שרה מטרוניתא כו' והעיקר בשביל לידת יצחק שיתגלה בלידת יצחק מבחי' הפנימית דכתר עליון שנמשך בה\"א דאברהם ע\"י המילה כמ\"ש כי ביצחק יקרא לך זרע מטעם הנ\"ל בירושת האבות לבנים חבור וקשר דקיום התו\"מ ברוחניות עם קיום תו\"מ בגשמיות כו' וע\"כ כשהיתה אשת אברם נק' שרי ביו\"ד דהעלם החכ' ובלידת יצחק נק' שרה בה\"א שהוא בחי' המל' בבנין שלם דוקא כנ\"ל וד\"ל:"],[2300670032,"(א) ויראו אותה שרי פרעה ויהללו אותה אל פרעה"],[2300670048,"<b>ותקח</b> האשה בית פרעה. הנה איתא בלק\"ת שיש בס\"ת דד' תיבות הללו שר\"י פרע\"ה ויהלל\"ו אות\"ה שם הוי\"ה וזה דבר פלא ביותר איך שייך כאן בשרי פרעה י\"ה ובויהללו אותה ו\"ה הכתיב (ישעי' מב, ח) וכבודי לאחר לא אתן כו'. אך הנה ידוע דאת זה לעומת זה עשה כו' (קהלת ז, יד) דנגד שרים העליונים דקדושה שנק' שרי פרעה דמל' דקדושה כ\"ה במל' דקליפה נק' שרי פרעה ובהתלבשות מל' דקדושה בסוד גלות השכינה בע' שרים זהו ירידת שרה דמל' דקדושה בשרי פרעה מל' דקליפה שראו אותה ויהללו אותה אל פרעה עד ותקח האשה כו' וד\"ל:\n(ב) <b>והנה</b> תחלה יש להבין בשרש בחי' שרה מל' דקדושה וענין שרי פרעה דמל' דקדושה להיות ידוע בשרש בחי' אברהם ושרה שהוא בחי' מ\"ה וב\"ן דאברהם אבר מה הוא בחסד דז\"א והוא אברהם דלעיל' שמשפיע למל' בה\"א דאברהם שהן ה\"ח דז\"א שע\"ז אמר (ישעי' טז, ה) והוכן בחסד כסא בחסד דאברהם בה\"א כו' ושרה העליונה היא בחי' ב\"ן נוק' דז\"א שמקבל ה\"ח דה\"א דאברהם וז\"ש בשביל לידת יצחק דוקא שלא תקרא שמה שרי ביו\"ד דחכמה כמו שהיא בשרשה באור אבא דאבא יסד ברתא וכמ\"ש אחותי בת אבי היא כו' כי ביו\"ד דחכמה הוא בבחי' ההעלם דאין שלא יוכל להיות התגלות והתפשטות כלל אלא שרה בה\"א שמה בבחי' ה\"א דבינה שבא בהשגה והתפשטות מאין ליש ואז תוליד ותקרא אם הבנים כו' וד\"ל. וכ\"ה לענין התהוות העולמות מאין ליש ממש מבחי' המל' הוא שנק' שרה בה\"א דוקא שז\"ש בהבראם בה\"א בראם באברהם והוא ה\"א דשרה כשנק' שר ה\"א לשון שררה ואדנות כו' שהוא בחי' כתר מלכות שבבינה שבאה לגלוי להיות ראש ומקור להחיות העולמות בדבור בי\"מ והוא הנקרא בזהר בשם מטרוניתא או אימא תתאה כו' שזהו ה\"א תתאה דמל' להיות כתר לבי\"ע כידוע וד\"ל:\n(ג) <b>והנה</b> זהו בחי' פרעה דקדושה ל' פריעה והתגלות דבחי' המל' הוא רק ענין ההתגלות דכתר מלכות במדות ודבור כמו דבר מלך שלטון כו' (קהלת ח, ד) שהדבור הוא לשון הנהגה כמו ידבר עמים כו' (תהלים מז, ד) ובל' תרגום דברא כמו דבר אחד לדור כו' (סנהדרין ח, א) והוא הנהגת המדות והמוחין שבהם שנמשך ומתנהג ע\"י הדבור כו' וזהו דבר מלך כו'. אך הנה ידוע דבקול ודבור נמשך מן הקנה שהוא הגרון והן קנה וושט שנק' ב' שרים שר המשקים ושר האופים (והורידין נק' שר הטבחים) שנק' שרי פרעה והן ב' קנים דקנה חכמה וקנה בינה וענין הקנה שר המשקים הוא שנמשך ממוח החכמה דוקא שהוא קר ולח בלחלוחית דיסוד המים שמוליד ומצמיח כל שכל וחכמה כו' והוא הממשיך חכ' דתורה בלב כאו\"א מישראל בקנה הנמשך ללב ע\"י הריאה ששואבת כל מיני לחלוחית כו' שזהו קנה חכמה (משלי ד, ה) כי שרש החכ' בבחי' החסדים דמים. ומטעם זה יש בכח קול דתורה אחר התפלה לקרר צמאון יסוד האש שבלב שהיה בתפלה בבחי' רצוא כו' כמו הריאה שמנשבת על הלב לקררו כו' וכמ\"ש כי אמרתך חיתני (תהלים קיט, נ) וד\"ל:"],[2300670064,"(ד) <b>והיינו</b> ג\"כ בחי' הבטול לאין האלקי בבחי' כח מ\"ה דחכמה שבמוח שנמשך בלב דוקא בבחי' שוב שאחר הרצוא והוא בחלל הימני שבלב שבו רוח החיים וזהו ג\"כ קנה חכמה בלב שנק' שר המשקים דמים דתורה ויש עוד שר המשקים שהוא העיקר והוא ביין המשמח דיינה של תורה בפנימיות ורזין דאורייתא שנכנס יין יצא סוד מן ההעלם דחכ' שנק' ח\"ס כמ\"ש שר המשקים בחלומו והנה גפן לפני כו' ואקח את הענבים כו' עד ואתן את הכוס על כף פרעה (בראשית מ, ט) שזהו בחי' כוס של ברכה דבחי' המל' ולע\"ל יהיה כוס ש\"ב ביין המשומר בענביו מו' ימי בראשית (כמ\"ש במ\"א). והנה שר האופים הוא הוושט שאוכלים בו ששרשו במוח בינה שהוא חם ויבש מבחי' הגבו' דאימא כמ\"ש (משלי ח, יד) אני בינה לי גבורה כי בינה מקור הגבורה כידוע דבינה מינה דינין מתערין והיינו מה שנמשך מן הוושט בחלל השמאלי שבלב ששם יסוד האש שהוא ההתלהבות ברשפי אש התשוקה בלב בבחי' רץ לבך שנתפעל מן ההשגה שבמוח בינה דוקא ולא מן החכ' שהוא קר ולח כנ\"ל כי ע\"י ההשגה בטוב טעם במוח בינה יוליד התלהבות מורגש ביסוד האש בלב וזהו בינה לבא ונק' שר האופים כמו האפיה והבשול שמהפך ע\"י האש לדבר שיותן בו שיהיה ראוי למאכל כך ע\"י התלהבות רשפי אש האלקי שבמוח בינה בלב יהופך מדותיו הטבעיים שבלב להיות נק' לב בשר רך כמו (יחזקאל לו, כו) ונתתי לכם לב בשר כו'. והנה הקול היוצא מן הגרון מורכב הוא מב' שרים הנ\"ל. א' מן הקנה שנק' קנה חכמה שיורד לריאה שנק' שר המשקים כנ\"ל בקול דתורה. והב' מהבל הלב שבחזה ששם יסוד האש מן הוושט ששרשו במוח בינה שהוא חם ויבש ועולה מלמטה למעלה ומלמעלה למטה כו'. וזהו שהקול מורכב מאש ומים ורוח אש דושט שבחזה הלב ומים מן הקנה שבמוח החכמה ורוח הוא הממוצע שהוא הבל רוח הדבור שמרוח החיים שבלב שנק' רוח ממללא כו' וז\"ש (במדבר כא, יח) באר חפרוה שרים שהן ב' שרים דקנה חו\"ב הנ\"ל שנמשכים ללב שהוא בחי' המל' שנק' באר כידוע והוא בחי' דבור העליון שנק' דבר מלך שמקבל מחו\"ב שבלב שנק' שרי פרעה (והוורידין שבצואר נק' שר הטבחים שהוא הממוצע בין ב' שרים הנ\"ל בהיות שסבוב הילוך הדמים שבגוף מלמעלה למטה ומלמטה למעלה מתחבר ע\"י הוורידין של נגד העורף ומפרקת בחצוניות שנק' אחוריים דב' קנים הנ\"ל בחי' חו\"ב) (וכמו שהקנה וושט מחברים המוחין שבראש עם הלב וכל האברים הפנימי' כך הוורידים שבצואר מחברים העורף עם המפרקת בחצונית חיות הגוף שיהי' קשר וחבור לראש עם הגוף כו'):\n(ה) <b>והנה</b> הדוגמא מכ\"ז יובן למעלה באדם העליון דאצי' שמבחי' מוחין דחו\"ב דמל' דקדושה שנק' פרעה פריעה והתגלות כל האורות העליונים כו' כנ\"ל הוא שנמשך בב' מדרגות דב' קנים דחו\"ב קנה חכמה קנה בינה בלב שבאדם העליון לבחי' הדבור העליון שמורכב משניהם ע\"י קול הגרון שבא ממוח החכמה בקנה מלמעלה למטה. וממוח בינה שבלב הרי עולה מלמטה למעלה ורוח הדבור העליון"],[2300670080,"הוא הממוצע כו' וכ\"ה בהמשכת חיות אלקי בעולמות במלאכים ונשמות שהן כלולים ג\"כ מבחי' רו\"ש דב' קנים הנ\"ל כמ\"ש (יחזקאל א, יד) והחיות רצוא ושוב וכן הנשמות יש בהם רו\"ש וממוצע כידוע וד\"ל:\n(ו) <b>והנה</b> ידוע דאת זלע\"ז עשה האלקים כו' (קהלת ז, יד) וכמו שיש בחי' שרי פרעה במל' דקדושה שנק' שרה שר ה\"א בחי' כתר דחו\"ב כידוע דמוח חכמה ומוח בינה מקבלים מעצם הגלגלת דחפיא על מוחא כו' כך לעומת זה יש בבחי' חצוניות ואחוריים במל' דק\"נ שמקבלים מאחוריים וחצוניות דכתר דמל' דקדושה והוא בחי' פרעה ושריו דק\"נ כידוע דפרעה בהפוך אותיות הוא עורף והוא בחי' העורף שלנגד הפנים שנמשך לשם בחי' התמצית וחצונית לקיום חצונית הגוף ג\"כ ע\"י השרים הנ\"ל דכמו שהשפע הפנימית הולך ממוחין דחו\"ב בקנה וושט מבפנים לנגד הפנים ללב כנ\"ל כך ע\"י אותן השרים עצמן הולך בחי' חצונית ותמצית ואחוריים אל העורף שעומד באחוריים דפנים למפרקת (שהוא סמוך לשר הטבחים שהן הוורידין שבצואר) ולמעל' היינו מה שהשפע הפנימית הולך משרים דחו\"ב דמל' דקדושה בקנה חו\"ב הנ\"ל מהן נמשך גם למל' דקליפה שהוא בבחי' עורף ששם נק' שרי פרעה דק\"נ (חצוניות ואחוריים דכ\"ע) וכמו שאנו רואים בטבע סדר מקום מעמד הקנה וושט שנק' שר המשקים ושר האופים שבחי' פנימיות האור וחיות שלהן קשור ודבוק למעלה בפנימיות המוחין דחו\"ב שבפנים עצמן שדבוקים בעצם הגלגלת החופף ע\"ג המוחין דחו\"ב כו' ובחי' החצונית שלהם דבוק בעורף ליתן שם ג\"כ שפע חצוניות (והיינו ע\"י הוורידין שבצואר שסמוך למפרקת יותר כו') וא\"כ הרי ב' קנים דחו\"ב הנ\"ל הן כמו בחי' ממוצעים בכלל בין בחי' הפנימית שבפנים שנמשך ממוח ללב ובין בחי' חצוניות ואחוריים שנמשך בעורף ומפרקת לחצונית הגוף וד\"ל:\n(ז) <b>והנה</b> בכל הנ\"ל יובן דרך כללות מ\"ש ויראו אותה שרי פרעה ויהללו אותה כו' דכל הנ\"ל בענין שרי פרעה דקדושה שהוא ב' קנים דחו\"ב שממשיכים גם השפע החצונית לעורף בחי' פרעה דק\"נ הנה בהתלבשו' מל' דקדושה שנק' שרה במל' דק\"נ בסוד גלות השכינה כנ\"ל זה היה ענין ירידת אברם ושרה למצרים שיקבלו השפע ממל' דקדושה בהסתר והעלם כו' וזהו ותקח האש' בית פרעה האשה דוקא שהיא שרה ולא אברם כו'. ותחלה יש להבין לאיזה טעם היה ענין ירידה זאת דאברם ושרי למצרי' כי ודאי האבות הן סימן לבנים דהיינו שכל מהלכם ומעשיהם וכל הקורות אותם היה סימן לבנים ודורות שאחריהם בכל פרט ופרט וגם כאן ירידת אברם ושרי למצרים היה סימן לירידת ישראל למצרים בגלות קשה רד\"ו שנה כו' שיוכלו לצאת משם מאפלה דנ' ש\"ט לקדושה האלקית בקבלת התורה פב\"פ כו' ע\"כ היה ירידת אברם ושרי לשם תחלה ובכח היח\"ע שעשה שם ואשר היתה שרה מל' דקדושה בגלות בבית פרעה ויצאה משם בקדוש' וטהרה כמ\"ש ויעל אברם ממצרים הוא ואשתו וכל אשר לו כו' נמשך כח ועוז לאלקים בחי' מל'"],[2300670096,"דקדושה בהיות ישראל בגלות מצרים שגלתה שכינה עמהם כמ\"ש (בראשית מו, ד) אנכי ארד עמך כו' שיעלו משם בקדושה וטהרה כו' וד\"ל:\n(ח) <b>אך</b> הנה היה עוד כוונה בירידת אברם ושרה לפרעה מלך מצרים כדי להעלותו בזה על כל האומו' כי פרעה זה היה זקנו של פרעה מלך מצרים ששיעבד בישראל והיה צריך שיתעלה תחלה ע\"י אברהם ושרה דוקא מפני שעתידים ישראל בניהם להיות בגלות תחת נינו ונכדו. כי הנה ידוע דכל אומה ומלכות שישראל יבאו בהם בגלות הן מתעלים תחלה בתכלית העלוי ביותר מכל האומות והולכים ומתגדלים בהיות ישראל תחתם דוקא וכמו במלכות נבוכדנצר שנתרומם תחלה על כל הגוים והיה מולך בכפה כדי שישראל יומסרו ליד מלך על כל הגוים ולא ביד אומה שפלה וכן במלכות רומא בבית שני כו' כידוע. והטעם הוא לפי שבכל גלות ישראל גלתה שכינה עמהם כמאמר גלו לאדום שכינה עמהם ואין כבוד השכינה שהוא בחי' המלכות להיות בגלות רק אצל מלך על כל הגוים משום שנא' (תהלים קג, יט) ומלכותו בכל משלה כו' וד\"ל:\n(ט) <b>וכ\"ה</b> בכל הגליות כמו בגלות האחרון הזה כמו שרואין בכל דור ובכל זמן שאומה שישראל תחתם בגלות מתנשאת על כל הגוים כו' וכן היה בתחלת הגלות הראשון דישראל למצרים משום דשכינה ירדה עמהם כמ\"ש אנכי ארד עמך כו' ע\"כ היה בתחלה עלייה גדולה לאומה דמצרים בעושר וכבוד וגדולה על כל הגוים והיה ראשית והתחל' לעליית מצרים בימי פרעה הראשון ע\"י אברם ושרה שירדו למצרים והוא ע\"י הרעב שהיה בכל הארץ ובאו כלם לשבור אוכל למצרים וקבץ כל כסף וזהב שבעולם כמו שהיה ע\"י יוסף במצרים לפרעה נינו ונכדו ונתגדל ביותר עד שפרעה נינו ונכדו היה מולך בכיפה כו' וכל הגדולה היתרה הזאת לא היה יכול להיות נמשכת לפרעה זה שהוא בחי' מל' דק\"נ אם לא שהיו אברם ושרי אצלו בתחלה וז\"ש ויהי רעב בארץ וירד אברם מצרימה כו' ודוקא ע\"י שרי אשת אברם שהיא בחי' מל' דקדושה שיורדת להשפיע למל' דק\"נ בסוד גלות בהעלם והיה הטעם בזה כדי לבררו וליתן כח לבנ\"י בהיותם בגלות של פרעה נכדו שיצאו משם ברכוש גדול כו' כנ\"ל וזהו שנלקחה שרה לבית פרעה כמ\"ש ותקח האשה בית פרעה כי עי\"ז שהיתה שרה בחי' מל' דקדושה בבית פרעה מל' דק\"נ נמשך שפע רב וגדולה יתירה למל' דק\"נ עד פרעה האחרון ששיעבד בישראל. ואמנם כ\"ז היה רק להוציא כל בחי' הטוב העליון דקדושה האלקית שהיה גנוז בהן כמ\"ש (קהלת ח, ט) עת אשר שלט האדם באדם לרע לו כו' כידוע וד\"ל:\n(י) <b>וזהו</b> ויראו אותה שרי פרעה תחלה כו'. כי ענין ירידת האור דמל' דקדושה במל' דק\"נ א\"א כ\"א ע\"י בחי' שרי פרעה תחלה שיהללו אותה אל פרעה כו' ואח\"כ ותקח האשה בית פרעה וד\"ל. ובאור הענין יובן עפ\"י כל הנ\"ל בשרש בחי' ב' שרים דקנה חו\"ב שר המשקים ושר האופים דמל' דקדושה שהן קנה וושט שהן בחי' ממוצעים בין הפנימית"],[2300670112,"דמוחי' דפנימית לחצונית השפע שנמשך בעורף כנ\"ל וע\"כ בהכרח שבהגלות נגלית האור דמל' דקדושה שהיא שרי אשת אברם במצרי' במל' דקליפה הוצרך להיות שיהיה הולך גלוי האור ושפע לפרעה מל' דקליפה ע\"י שרי פרעה תחלה שמקבלים מקנה וושט שרים דמל' דקדושה שמשפיעים להם בחצוניות כנ\"ל וזהו ויראו אותה שרי פרעה תחלה שתחלת הגלוי לראות למל' דקדושה היה אצל שרי פרעה דקליפה שראו אותה תחלה ויהללו אותה אל פרעה פי' ויהללו בהלל והודאה שהוא ענין תוס' אור כמו בהלו נרו (איוב כט, ג) וכהלל דפסד\"ז בהללויה כידוע כך שרי פרעה מל' דקליפה יהללו את בחי' מל' דקדושה לפני פרעה דקליפה וכמו הללו את ה' כל גוים שבחוהו כל האומים כו' (תהלים קיז, א) וכן כל העמים תקעו כו' הריעו לאלקים כו' (שם מז, ב) וכידוע דכל הע' שרים דק\"נ או' שירה בכל יום וע\"י ההלל והודאה זאת דשרי פרעה דק\"נ מהללים ומשבחים לאלקים חיים שהוא שרי מל' דקדושה המה ממשיכים תוס' אור הקדושה ויניקה יתירה מבחי' מל' דקדושה אל פרעה מל' דק\"נ וז\"ש ויהללו אותה אל פרעה בבחי' המשכה והתפשטות למטה שיורדת מל' דקדושה להתלבש בתוס' המשכה במל' דק\"נ ודוקא ע\"י שיהללו אותה שרי פרעה וכ\"ה בכל דור ודור דכל חכמי הגוים כו' (ירמיה יו\"ד, ז) קרו ליה אלקא דאלקיא כו' וכתיב מי לא יראך מלך הגוים (שם) ואז מלך אלקים על גוים (תהלים מז, ט) להשפיע להם בחצונית כו' ואמנם הגם שמהללים ומשבחים כל חכמי הגוים וקרו ליה אלקא כו' וכיתרו שאמר (שמות יח, יא) עתה ידעתי כי גדול ה' מכל האלקים וכן נבוכדנצר שהודה ושבח כו' וכן כל ע' שרים בכל דור וזמן עכ\"ז אין בחי' הבטול האמיתי כמו לע\"ל דכתיב (צפני' ג, ט) כי אז אהפוך אל עמים שפה ברורה לקרוא כולם בשם ה' ממש כו' וא\"כ הרי התגלות השכינה בגלות אצלם דהיינו בבחי' ההעלם והסתר כענין רם על כל גוים ה' (תלי' קיג, ד) בבחי' מקיף בהעלם (כמשי\"ת) וזהו ג\"כ ענין ויראו אותה שרי פרעה בתחלה בראיה מרחוק דוקא כמו ראיה במראה הנבואה דבלעם הרשע שאמר (במדבר כד, ד) מחזה שדי יחזה כו' וכה\"ג וד\"ל ואח\"כ ויהללו אותה למל' דקדושה בהלל והודאה אל פרעה להוסיף יניקה למל' דק\"נ (וכ\"ז בבחי' גלות השכינה דוקא אבל בעליית המל' דקדושה כמו במלכות דשלמה היה להיפוך דבחי' שרי פרעה דמלכות דק\"נ היו בתכלית הבטול במציאות לקבל יניקה ממל' דקדושה וכמ\"ש בזהר בענין תרין צפרין דינקין בכל ליליא ממל' דקדושה והן בחי' חו\"ב דק\"נ שנק' שרי פרעה דינקי בכל ליליא ממותרי השפע בגבול ומדה מחכ' שבמל' דקדושה (וכמו בימי יוסף שקבלו זקני חרטומי מצרים מחכמת יוסף וכמ\"ש (תהלים קה, כב) וזקניו יחכם. וכן בימי משה בנסים ונפלאות שעש' בעשר מכות נכנעו חרטומי מצרים ביותר כו' ויותר מכל זה היה בימי שלמה שאמ' בזהר ע\"פ אז תבאנה שתים נשים זונות אל המלך (מ\"א ג, טז) שהן עמון ומואב חו\"ב דקליפה שנכללו ונתבטלו בחכמת שלמה מל' דקדושה בתכלית כמו שהיו כל מלכי העולם שולחים לו מנחה ושומעים את חכמתו כידוע"],[2300670128,"וז\"ש אז תבאנה אז דוקא ולא מקדמת דנא ויותר מזה יהיה במלך המשיח דכתיב ונהרו אליו כל הגוים כו' (ישעי' ב, ב) בתכלית הבטול האמתי כנ\"ל וד\"ל) ולהיפוך בגלות השכינה בע' שרים דק\"נ אע\"פ שנא' מלך אלקים על גוים כו' ובכל חכמי הגוים כו' ונק' מלך הגוים כנ\"ל דקרו ליה אלקא כו' מ\"מ נק' גלות השכינה שבחי' מל' דקדושה מלובשת בהעלם גדול במל' דק\"נ להוסיף להם אור וחיות האלקי וז\"ש ויראו אותה כנ\"ל וד\"ל):\n(יא) <b>ובכל</b> הנ\"ל הנה יובן ענין שם הוי\"ה שיש בס\"ת דשרי פרעה ויהללו אותה בד' תיבות הללו דוקא כמ\"ש בלק\"ת כנ\"ל והנה בב' תיבות ויראו אותה יש בס\"ת ו\"ה וב' תיבות דשרי פרעה בס\"ת י\"ה הרי ו\"ה קודם לי\"ה ונמצא שיש עוד שם הוי\"ה בס\"ת דויראו אותה שרי פרעה בהפוך דו\"ה קודם לי\"ה ובכלל הרי אותיות דו\"ה שבס\"ת דויראו אותה קודם לשם הוי\"ה שבס\"ת דד' תיבות שרי פרעה ויהללו אותה הנ\"ל. והענין הוא כידוע הכלל הידוע בכ\"מ דכל אותיות דר\"ת הוא בבחי' הפנימיות של האור עצמו ואותיות דסופי תיבות מורים על בחי' החצונית דשפע שנמשך מן הפנימית כו' וכ\"ה כאן בס\"ת בשם הוי\"ה בד' תיבות דשרי פרעה כו' שהוא בחי' ההמשכה החיצונית ואחוריים דמל' דקדושה שנמשך אל פרעה דמל' דק\"נ כמאן דשדי בתר כתפוי להיותה שם בבחי' גלות כנ\"ל ע\"כ שם הוי\"ה זה הוא בס\"ת דשרי פרעה ויהללו אותה לפי שמל' דקדושה מתלבשת תחלה בשרי פרעה בחי' חו\"ב דק\"נ וזהו י\"ה דשרי פרעה שי\"ה הוא בחו\"ב כידוע ובחי' ו\"ה דויהללו אותה היינו בחי' ההמשכה והתפשטות למטה בהלל והודאה שלהם כנ\"ל וד\"ל. אך ענין ו\"ה דויראו אותה שלפני י\"ה דשרי פרעה כו' דו\"ה קודם לי\"ה הטעם הוא לפי שכל עיקר תחלת גלוי האור האלקי דמל' דקדושה הרי הוא בא בבחי' ההמשכה והתפשטות מלמעלה למטה בדרך דלוג הערך וצמצום ההמשכה בציור אות וי\"ו ואח\"כ ה\"א והוא הבא בגלוי לשרי פרעה שהן חו\"ב דקליפה שיוכלו לראות בראיה כמו במראה הנבואה דבלעם כנ\"ל שע\"כ ביקש משה שלא תשרה שכינה באוה\"ע כו' משום דקמיה גם חשך לא יחשיך כו' (תהלים קלט, יב) וזהו ויראו אותה בראיה מרחוק ע\"י צמצום והסתר גדול בסוד גלות השכינה באוה\"ע כנ\"ל וזה היה דוקא ע\"י ו\"ה שבס\"ת דויראו אותה כו' ואח\"כ ויהללו אותה ששרי פרעה בחי' חו\"ב דק\"נ מהללים אותה שהוא כדי להמשיך האור דמל' דקדושה אל פרעה מל' דק\"נ שיקבל גם הוא אור ושפע ע\"י יחודו במל' דקדושה ואם לא בחי' ההלל דשר\"י פרע\"ה אחרי שרא\"ו אות\"ה בהגלות האור אליהם תחלה ע\"י ו\"ה דס\"ת דויראו אותה לא היה יכול פרעה ליקרב למל' דקדושה כלל וד\"ל:\n(יב) <b>והנה</b> מעתה יש להבין מ\"ש עוד ותקח האשה בית פרעה כו'. הלא כבר אמר שראו אותה שרי פרעה ויהללו אותה אל פרעה שזה היה בחי' המשכת האור דמל' דקדושה ע\"י בחי' ההלול דשרי פרעה בחי' חו\"ב דק\"נ וא\"כ למה הוצרך שתוקח האשה בית פרעה ממש כו'. אך"],[2300670144,"הענין הוא דבאמת אע\"פ שאמר ויהללו אותה למל' דקדושה כמו הללו את ה' כל גוים כו'. ובכל חכמי הגוים מודים שאין כמוך כו' וייראו מה' כל ארץ כו' (מנחות קי, א) וקרו לי' אלקא דאלקיא כו' כנ\"ל. עכ\"ז אין זה בא בתוך תוך לבם ונפשם כלל רק מן השפה ולחוץ דהיינו רק בבחי' הודאה על האמת שכן הוא כו'. אבל לא נגע יראת אלקים ורוממותו בפנימיות נפשם לפי ששרשם מעולם הפירוד שכבר הפרידן מיחודו כו'. ולז\"א רם על כל גוים הוי\"ה בבחי' הרוממות והתנשאות מרחוק ה' נראה עליהם והוא בתכלית ההסתר והצמצום דשם אלקים שמלך על גוים ע\"י הרבה צמצומים עד במ\"ח צירופים האחרונים שבו שמאיר בהם בגלוי ע\"כ הם תמיד בבחי' הפירוד רק לפרקים אומרים שירה והלל והודאה כנ\"ל. ולזה הטעם גם כאשר באה בהם התלבשות מל' דקדושה בסוד גלות השכינה להשפיע להם תוס' יניקה יתירה כמו בעושר וכבוד וגדולה והצלחת תולדות פרי הארץ וכה\"ג כנ\"ל בשר של מצרים ששלטו על ישראל וכנבוכדנצר כו' הרי א\"א שיומשך בהם השפע האלקית מרוחניות לגשמיות ממש אם האור האלקי דבחי' המל' מרחוק מאד בהעלם והסתר גם ע\"י ההלול דשרי פרעה לא יוכל להיות המשכת שפע ממש בקירוב אלא דוקא ע\"י ירידת המל' דקדושה עצמה ומהותה כמו שהיא למעלה בהיכל מלך העליון הוא שתרד למטה ותבא בהיכל מלך ושר של אומה ההיא וז\"ש ותקח האשה בית פרעה ממש שנלקחה לשם להיות היא עצמה בהיכלו ולא ע\"י ההלול שיהללו אותה מרחוק לבד שרי פרעה שהן חו\"ב דק\"נ שזה לא יועיל לענין גוף השפע ממש וזהו ענין גלות השכינה בע' שרים בכל גלות שהשכינה עצמה באה ומתלבשת בבית פרעה מל' דק\"נ ועכ\"ז אין זה כמו שנלקחה אסתר לבית אחשורוש לשם אישות ממש שזהו להתייחד בה בגלוי גמור להיות נק' אשתו לכל דבר כו' אבל כאן אמר רק ותקח האשה בית פרעה שהיתה שם לפי שעה הגם שאמר פרעה ואקח אותה לי לאשה לא לקחה ליחוד ממש עדיין רק שהיתה בביתו כי לא נגע בה כלל וכלל והענין הוא דעיקר בחי' גלות השכינה כמ\"ש (ישעי' נ, א) ובפשעיכם שלחה אמכם כמו שרה שנלקחה לבית פרעה וכה\"ג (וכן בכל גליות בגלות אדום ויון השכינה עצמה בגלות שם כמו שר\"א ור\"י הלכו תמיד לרומי כו') היינו שעי\"ז יהיה נמשך רוב שפע וברכה גשמית לאותו השר והאומה בכמה מיני המשכות פרטיות עד כמה דורות לפי שע\"י בחי' יחוד זה שמל' דקדושה בבית המלכות דק\"נ אע\"פ שלא נגע בה ביחוד וקירוב ממש רק שהוא עמה בהיכל אחד לבד כשרה שהיתה בבית פרעה ובכל היכליו וארמנותיו היה לו עי\"ז רוב שפע וברכה לכל עמו וזהו שנק' יחוד חצוני שמקיף א' במה דהיכל אחד מקיף לשניהם לבד ולא יחוד פנימי כלל כו' וד\"ל:\n(יג) <b>וזהו</b> ותקח האשה סתם שזהו סוד גלות השכינה בבית פרעה ביחוד חצוני בהיכל אחד עמו שמזה נעשה מקור ממשיך כל שפע גשמית לפרעה מלכות דק\"נ עד כמה דורות שבהיות ישראל בגלות תחת פרעה נינו ונכדו יוכלו"],[2300670160,"לצאת משם ברכוש גדול וינצלו את מצרים כנ\"ל מכל הניצוצות דקדושה שנפלו שם כו' וכמ\"ש (קהלת ח, ט) עת אשר שלט האדם באדם לרע לו כו' וד\"ל:\n(יד) <b>אך</b> הנה מפסוק זה מובן דותקח האשה כו'. שלא יוכלו החיצונים לקבל מבחי' או\"פ דקדושה כלל כי בבחי' פנימי' דקדושה לא יוכל להגיע להם שפע וכמ\"ש (ישעי' מב, ח) וכבודי לאחר לא אתן (וע\"כ השם הוי\"ה דשרי פרעה כו' הוא בס\"ת לבד כנ\"ל) ובזה הובדלה יניקת החיצוני' מן הקדוש' האלקית שלא יוכלו לקבל שפעם בגלוי דאו\"פ בכלי רק בבחי' מקיף מרחוק כו' וכמו כאן דגם שנלקחה שרה לבית פרעה ממש לא קבל ממנה בגלוי וקרוב כלל רק ע\"י היחוד חצוני שהיה עמה בהיכל א' לבד כנ\"ל. כי א\"א שיגיע להם אור ושפע האלקית בקרוב ובגלוי דאו\"פ רק בבחי' מקיף מרחוק כו'. וראייה לדבר מן הלבונה שבי\"א סממני הקטורת שמאיר בבחי' מקיף דק\"נ והוא בחי' הממוצע כו' וד\"ל. (וכ\"ה בכל"],[2300670176,"גלות הרי השכינה בגלות עם ישראל דוקא כמא' (מגיל' פ\"ד) גלו לאדום שכינה עמהם דוקא וכמ\"ש ליעקב אנכי ארד עמך דוקא כו' רק שמתלבשת בהיכל מלכות דק\"נ כמו ותקח האשה כו') ואמנם אם לא ע\"י הלול דשרי פרעה לא היתה מתלבשת במל' דק\"נ גם ביחוד בהיכל אחד כו'). ואף גם על זאת שנלקחה שרה לבית פרעה לקה פרעה בנגעים גדולים ואת ביתו על דבר שרי כו' מפני שאין החיצונים יכולים לקבל גם מבחי' המקיף דקדושה שמסמא עיניהם כו' וכאשר לפרקים מקבלים אור מבחי' המקיף העליון דמל' כמו כאן כשנלקחה לביתו הוכה בנגעים גדולים (מטעם המבואר בלק\"ת) דנגע אותיות ענג דכתר שנק' נגעי' דוקא כמו כאשר משפע נעשה פשע נק' פשע רב כו' ומ\"ש (ויקרא יג, ב) אדם כי יהיה בעור בשרו נגע צרעת כו' זהו רק ביניקות החצונים במדות דאדם בעור בשרו החצונית שאין אור אבא מאיר שם כמ\"ש בזהר ולא נק' נגעים גדולים רק בפגם דאור הכתר כו' שהוא הפך ענג העליון כו'. וז\"ש וינגע ה' כו' נגעים גדולי' על דבר שרי אשת אברם כו' קודם שנעשים מקור לבי\"ע כו') והוא ע\"ד שנלקחה שרי בהיכל פרעה שהוא בבחי' מקיף כחופה כו' וד\"ל (ומ\"ש ואקח אותה זהו בבחי' אירוסין וחופה לבד כו') וזהו ולאברם היטב בעבורה שנתברר וניתן לאברם כל הטוב דקדושה מפרעה דק\"נ ובעבור' דשרי דוקא ויהי לו צאן ובקר וחמרים ע\"ס דק\"נ ועו\"ש דק\"נ וגם אתונו' וגמלים כל כתרין דק\"נ דכר ונוק' דעו\"ש ואתונות וגמלים כו' וזהו כמו וינצלו את מצרים כו' (שמות יב, לו) שעשאוה כמצולה כו' (ברכות ט' ע\"ב) וז\"ש ויעל אברם ממצרים הוא ואשתו וכל אשר לו ורבותא יתירא היתה באשתו שרה שעלתה מבית פרעה גם שהיא בחי' ב\"ן דמל' דקדושה דע\"ז אמר ומלכותו בכל כו' ונק' מלך אלקים כו' דהכל מקבלים ממנה ואעפ\"כ לא נגע בה פרעה כלל ואדרבה ויעל אברם כו' ברבוי העלאת הנצוצות כו' כי אברם הוא בחי' מ\"ה דח\"ס כו' דבח\"ע דוקא אתברירו כו'. ועכ\"ז אמר ולאברם היטב בעבורה דוקא שזהו כשהיתה בבית פרעה כו' (וכ\"ה בכל גלות השכינה בבית המל' דק\"נ כו') וילך למסעיו כו' (כמ\"ש בפ' יתרו) וזהו מ\"ש בזהר פ' חיי שרה דשרה תקנה לחטא דחוה דחוה שהיא אחוריים דשם ב\"ן כו' נחתת ולא סלק' משום דחויא אתדבק בה כו' דבא נחש על חוה כו' (ע\"ז פ\"ב) ושרה נחתת בבית פרעה כמ\"ש ותקח האשה כו' וסלקת משם בעלוי רב מאד לבד שלא נגע בה כלל וכמ\"ש ויעל אברם כו' ואשתו כו' הגם שהיתה בהיכל מל' דק\"נ ממש עלתה משם בכל העלאת ניצוצות רבות שנפלו שם כו' לפי ששרי הוא בחי' שם ב\"ן דכתר דקדושה ממש כנ\"ל וד\"ל. והתורה נצחית היא בכל דור ובכל זמן כי מעשה אבות סימן לבנים שכל זה שהיתה שרי בבית פרעה ועלתה משם היה כח ועוז מזה ליציאת ישראל ממצרים ושכינה שעמהם ברכוש גדול ברבוי העלאת הניצוצות שהיו שם כמ\"ש וינצלו את מצרים כו' משום דאבות הן סימן לבנים כנ\"ל וד\"ל:"],[2300670033,"(א) <b>בעצם</b> היום הזה נמול אברהם וישמעאל בנו כו'. ואמרו במדרש ב\"ר נמול מאליו שה' עזרו ששלח ידו ואחז עמו וכרת עמו הברית (נחמי' ט, ח) לו לא נאמר אלא עמו כו'. משא\"כ בבני ביתו כתיב וימל את בשר ערלתם כו'. והנה יש להבין ממ\"ש בעצם היום הזה ולא אמר ביום הזה כו' ועוד למה חזר וכפל הדבר אחר שכבר אמר וימל את בשר ערלת' בעצם היום הזה כאשר דבר אתו אלקים ואברהם בן צ\"ט שנה בהמולו בשר ערלתו (בהמולו מעצמו וגם בישמעאל אמר כן וכשכפל הדבר אמר בעצם היום הזה נמול אברהם וישמעאל בנו וכל אנשי ביתו כו' נמולו אתו) והנה באמת יש להבין למה נצרך אברהם לקבל מצות מילה ע\"פ צווי ה' בהיותו בן צ\"ט שנה הלא כבר קיים אברהם כל התו\"מ אפי' ע\"ת שנא' עקב אשר שמע כו' וישמור משמרתי מצותי כו' ולמה לא קיים מצות מילה עד שציוהו ה' והלא מצות מילה ראשונ' לכל המצות וכוללת כל המצות שבתורה והיא באמת למעלה מכל התו\"מ (ברכות מח, ב) (מפני שנכרתו עליה י\"ג בריתות והתורה נכרתה בג' בריתות וע\"כ מקדים לומר בבהמ\"ז ברית לתורה ועל בריתך שחתמת בבשרנו ואח\"כ ועל תורתך שלמדתנו כו' כמ\"ש בדרז\"ל (שם) וצריך להקדים ברית לתורה) ויש רמז לזה שמצות מילה למעלה מכל התו\"מ שפסוק מי יעלה לנו השמימה כו' (דברים ל, יב) ר\"ת מילה וס\"ת שם הוי\"ה כו' דמרמז בזה שמצות מילה למעלה הרבה משם הוי\"ה שכולל כל התו\"מ שנק' מצות הוי\"ה תורת הוי\"ה בכלל ובפרט כו' וד\"ל וע\"כ מצות מילה בר\"ת דמי יעלה כו' וס\"ת שם הוי\"ה כו' וד\"ל:\n(ב) <b>אמנם</b> להבין זה וגם להבין דא\"כ למה קיים אברהם כל התו\"מ קודם מצות מילה עד היותו בן צ\"ט שנה (ואם מפני שזה שקיים כל התו\"מ היינו רק ברוחניו' ולא בגשמיות ומצות מילה קיים בגשמיות היא גופא יש להבין דהיה לו לקיים מצות מילה בגשמיות תחילה ואח\"כ לקיים מצות הרוחניות (כרמז דמי יעלה כו' שמילה בר\"ת כו') אך הנה באמת שמצות מילה למעל' היא מכל התו\"מ כמו שמובן"],[2300670049,"ברמז זה דר\"ת דמי יעלה לנו כו'. דהנה מ\"ש לא בשמים הוא לאמר מי יעלה לנו השמימה כו' לכאורה יש סתירה לזה ממ\"ש מן השמים השמיעך את קולו כו'. וכמאמ' דהתורה מן השמים ניתנה כו'. אך הענין הוא דודאי התורה מן השמים ירדה לארץ וכמ\"ש (שמות יט, כ) וירד ה' על הר סיני כו'. והארץ האירה מכבודו אין כבוד אלא תורה והמלאכים ביקשו (תהלים ח, ב) תנה הודך על השמים כו' וכידוע (וגם קדמה לעולם ונק' ים הקדמוני (יואל ב, כ) או משל הקדמוני (ש\"א כד, יג) שהן מ\"ע שמעל השמים כמ\"ש יהי רקיע כו') אמנם כאשר ירדה התורה למטה בארץ אז נא' (דברי' ל, יב) לא בשמים היא אלא בארץ דוקא וכמו (ב\"מ נט, ב) שאמר ר' יהושע לחכמי' אין משגיחי' בבת קול מן השמים משום דלא בשמים היא עכשיו אלא בארץ כו'. וע\"כ גם נביא בדבר ה' אין רשאי לחדש דבר שנגד הכתוב בתורה ומקובל בפי חכמי ישראל ממשה (שבת קד, א) (ונידון כז\"מ כו') ושרש הענין הוא דהתורה היא בב' מדריגות פנימיות וחיצוניות כמ\"ש (דברים כט, כח) הנסתרות לה' כו' והנגלות לנו ולבנינו כו' וכמ\"ש (יחזקאל ב, י) כתובה פנים ואחור כו' ובחי' הפנימית שבה הוא בחי' עה\"ח שלמעלה מעה\"ד כו' וכמ\"ש (משלי ג, יח) עץ חיים היא כו'. וע\"ז נאמר (איוב יא, ט) ארוכה מארץ מדה ורחבה מני ים שלא יכילנה ארץ וים עלמין דאתגליין ועלמין דאתכסיין כו' וזהו שא' שהתורה מן השמים ניתנה כו' בחי' שמים העליונים שהוא בחי' מקיף הכללי דסובב כ\"ע ומה שא' לא בשמים עליונים היא לאמר מי יעלה לנו כו' היינו כאשר ירדה התורה מן השמים לארץ כנ\"ל. והוא בחי' מדרגה הב' שבתורה שירדה למטה לברר לעה\"ד טו\"ר דוקא שזהו בחי' חיצוניות והנגלות לנו כו' (ונק' נובלות חש\"מ כידוע ומבואר למעלה שיש בה יתרון מעלה על בחי' הפנימית והוא ה\"א דאברהם שע\"י מצות מילה בגשמיות כו') וזהו שא' ר\"י אין משגיחין בב\"ק דלא בשמים היא דהיינו לאחר שירדה מן השמים לארץ דוקא משום דירידה זאת הרי היא רק לברר לעה\"ד טו\"ר בכל העולמות דבי\"ע והוא דוקא בהיות גלוי אור דתורה בא בבחי' דיבור העליון בי' הדברות (שהדיבור הוא בבחי' מל' דאצילות) באמרו אנכי ולא יהיה לך שזהו כללות הבירור בין טו\"ר שבמצות שאז כאשר נמצא התורה למטה בדיבור העליון אינה נמצאת למעלה מבחי' הדיבור שהוא הנק' שמים העליונים וז\"ש לא בשמים היא לאמר מי יעלה לנו כו' וד\"ל:\n(ג) <b>ולהבין</b> ביאור הדברים יש להקדים תחלה ענין א' מ\"ש בפ' נצבי' אחר שאמר הנסתרות לה' כו' והיה כי יבאו עליך כל הדברים האלה הברכה והקללה כו' והשבות אל לבבך בכל הגוים כו' ושבת עד ה' אלקיך ושמעת בקולו ככל אשר אנכי מצוך היום כו' בכל לבבך כו' ושב ה' את שבותך כו' וקבצך מכל העמים כו' אם יהיה נדחך בקצה השמים משם יקבצך כו' והביאך אל הארץ כו' וירשתה והטיבך והרבך מאבותיך כו' ומל ה' את לבבך ואת לבב זרעך לאהב' את ה' בכל לבבך כו'. ויש להבין בסדר פ' זו דהלא תחלה א' שאחר שיהיו בגלות ויעשו תשובה שלימה"],[2300670065,"ושבת עד ה' כו' יזכו לקיבוץ גליות מקצה השמים ולביאת הארץ ברוב טובה יתירה מאבותיהם וא\"כ אחר כל אלה איך אמר ומל ה' את לבבך כו' לאהבה את ה' בכל לבבך כו'. למה יצטרכו אז שימול ה' את לבבם לאהבה כו' אחר שכבר עשו תשובה שלימה בהיותם בגלות וכמ\"ש ושבת כו' בכל לבבך כו' ועשו מע\"ט הרבה עד שזכו לקיבוץ גליות וימות המשיח ויהיה בהם כל טוב העליון שלא הי' כזה איך יתכן שעדיין יצטרכו למול לבבם הערל שיוכלו לאהוב את ה' כו'. אך הענין הוא שיש במילה ב' מדריגות א' מילה שהיא מלמטה למעלה דוקא כמו ומלתם את ערלת לבבכם שאתם תמולו כו' והב' מילה שהיא מלמעלה למטה דוקא והוא מה שא' ומל ה' את לבבך כו' דמה שימול ה' את לבבך זהו מלמעלה למטה דוקא והוא לאחר שנימול מצד עצמו במילה שמלמטה למעלה כו' וזהו ענין תשובה תתאה ותשובה עילאה בכלל שאין תש\"ע כ\"א אחרי תש\"ת דוקא והוא מ\"ש תחלה והיה כי יבאו עליך כו' הברכה והקללה שהוא ע\"י הטו\"ר ויתבררו ביסורי הגלות דתיסרך רעתך כו' (ירמיה ב, יט) אז והשבות אל לבבך כו' ושבת עד ה' אלקיך כו' שהוא בחי' תש\"ת בלב נשבר ונדכה להסיר הטמטום הקשה שבלב שלא יהיה לבו כלב האבן בקשיות לילך בשרירות לב רק רע כל היום וע\"י הכנעה עצומה בלב נשבר הוסר ונשבר הקושי הזה ונעשה לבו רך וטוב שהוא ההתעוררות הטוב שבלבו לילך אחר ה' ותורתו ומצוותיו ולידבק בו באמת וזהו ומלתם את ערלת לבבכם כמ\"ש כי כל הגוים ערלים וכל ישראל ערלי לב (שם ט, כה) דכמו שעיקר ההבדלה בגשמיות בין ישראל לאחרים הוא באות ברית קודש שהוסר הערלה הגשמיות ואינו נק' ערל בגשמיות כך צריך להיות הבדלה זו עצמה ברוחניו' הנפש והוא בערלת הלב שנק' ערלי לב להסיר הערלה הדבוקה על הלב ומכסה ומסתיר על בחי' הפנימית הטוב שבה לגמרי והוא ענין הטמטום הקשה שבלב שקשה כאבן ממש ולע\"ל נאמר והסירותי את לב האבן מבשרכ' ונתתי לכם לב בשר כו' (יחזקאל לו, כו) ועכשיו צריך האדם להסיר בעצמו לב האבן הזה להיות רך לפני ה' שהוא לב בשר הרך והוא ע\"י תשובה בקירת ועומק הלב בלב נשבר מאד כנ\"ל במרירות ושפלות והכנעה עצומה על רוע לב ופירודו העצום מה' אחד ובזה הוסר ערלת הלב הקשה הנ\"ל ונגלה בלב בחי' התעוררות הטוב לילך אחר ה' בכל לבבו כו' בתו\"מ בבירור הרע מן הטוב שהן שס\"ה ל\"ת ורמ\"ח מ\"ע וז\"ש ושבת כו' ושמעת בקולו ככל אשר אנכי מצוך היום ושב ה' כו' בקיבוץ גליות (שיהיו כנ\"י קומה שלימה בבחי' אדם אדמה לעליון ולא בפיזור בד' רוחות כו' שהוא כמו התחלקו' האברי' בפיזור ופירוד כו') והטיבך כו' פי' אחר שימולו א\"ע בתשובה שלימה כנ\"ל ובמע\"ט דתו\"מ להבדיל בין טו\"ר בסו\"מ וע\"ט ויזכו לקיבוץ גליות אז אתעדל\"ת זאת יעורר אתעדל\"ע להיות מילה הב' שהיא מלמעלה למטה דוקא והוא מ\"ש ומל ה' את לבבך כו'. אחר המילה דבזמן הגלות דומלתם את כו' בתשובה ומע\"ט שאתם תמולו ואז ימול ה' את לבבך כו' שהוא ענין ובחי'"],[2300670081,"בירור אחר בירור שאחר שנבררו כנ\"י במילה שבזמן הגלות בתשובה ומע\"ט יבאו לבירור השני הפנימי דמילה עליונה שימול ה' את לבבך כו' (וזהו ענין גדולה מילה שנכרתו עליה י\"ג בריתות שלמעלה מברית דתו\"מ וע\"כ ר\"ת דמי יעלה לנו כו' מילה מ\"ל י\"ה שימול ה' כו' מלמעלה למטה כנ\"ל כו'. וס\"ת הוי\"ה שהיא מילה שע\"י תו\"מ מלמטה למעלה כו' וכמשי\"ת ב\"ה וד\"ל):\n(ד) <b>ולהבין</b> זה הנה תחילה יש להבין שרש ענין המילה בגשמיות ודוגמתה יובן במילה הרוחנית שבערלת הלב הנ\"ל. דהנה עיקר ענין המילה הוא להבדיל ולהפריש הערלה החיצונית מן בחי' הפנימיות שביסוד שאז נק' אות ברית קדש וכמו שאו' ועל בריתך שחתמת בבשרנו וכן או' וצאצאיו חתם באות ברית קדש וכמ\"ש לאברהם זאת בריתי אשר תשמרו ביני וביניכם ובין זרעך אחריך המול לכם כו' ונמלתם את כו' והי' לאות ברית ביני וביניכם. והנה ענין אות הברית הזה הוא כאשר הוסר' הערלה החיצוניות ויתגלה בחי' הפנימית ולא יכסה הערלה החיצוני' על הפנימית כו' זאת אות הברית ביני וביניכם כו' שזהו עיקר ההבדלה בין ישראל לעמים שאו' בהבדלה המבדיל בין קדש לחול ובין אור לחושך ובין ישראל לעמים כו'. ושרש ענין הזה אינו רק ענין ההבדלה וההפרשה בין הטוב ובין הרע להבדיל ולהפריש הרע מן הטוב לבלתי יתערב וידבק בו כלל וכלל שזהו הבדלת החיצוניות מן הפנימיות כנ\"ל. והטעם הוא כי בבחי' יסוד הוא בבחי' ההשפעה העליונה וכאשר הערלה דבוקה בבשר יומשך השפע גם לחלק הרע שבערלה ושניהם מקבלים יחד ולא עוד אלא שיכסה הרע על בחי' הטוב שבפנימי' יסוד ונמצא מתערבי' יחד קבלת הטוב עם קבלת הרע בלי הפרש כלל ביניהן (כמו שהי' קודם מילה דאברהם שהי' ריבוי שפע דניצוצות דקדושה גם בע' שרים אך ע\"י המילה נתקבצו כולם אל בחי' הפנימי' דוקא שז\"ש כי אב המון כו'). אך כאשר הוסר הערלה לגמרי ונגלה רק בחי' הפנימית ע\"י הפריעה דוק' (דמל ולא פרע כאלו לא מל) (שבת פי\"ט) אז הקבלת השפע הוא בא רק בפנימית הטוב שמקבל מבחי' פנימית יסוד העליון דאור זרוע לצ\"ע כו' בלי שום תערובת קבלת רע כלל כו' (דאעפ\"י שאין רע יורד מלמעלה רק טוב ואיך יהיה קבלת הרע כלל מאחר שאין זה במשפיע כלל. הענין הוא כידוע דבכל שפע דמשפיע יש פנימיות וחיצוניות עכ\"פ ובתערובות (כמ\"ד שיש בו פסולת כו') ובהגיע למקבל יפרד חלק החיצוניות מן הפנימיות בערלה הדבוקה שמקבל החיצוניות ויהיה לרע ממש דכל התהוות חלק הרע בא רק מצד המקבל שמקבל החיצוניות ושמרים כו' (ודוגמא לדבר השליא שנעשה מן פסולת הדמים שבולד שבא מפסולת מ\"ד ומ\"ן כו') וע\"ד שאמרו (אבות פ\"א, יא) חכמים הזהרו בדבריכם (שיהיה נקי מכל סיג) שלא ישתו התלמידים הבאים אחריכם מים הרעים ממש להפוך מטוב לרע ומאמת לשקר כו'. וכד' מדות בתלמידים א' קולט את השמרים כו'. וכה\"ג יובן בחיצוניות השפע עליונה שנמשך לע' שרים דנוגה וד\"ל):"],[2300670097,"(ה) <b>וזהו</b> ענין המילה שמלמטה למעלה כמ\"ש ומלתם את ערלת לבבכם שהוא ע\"י תשובה אמיתית ומע\"ט דתו\"מ כי כמו שהטעם הוא בהבדלת הערלה הגשמית כנ\"ל כך הוא ממש בענין מילה ברוחניות בהבדל' הערלה שבלב הנ\"ל שישראל נק' ערלי לב וצריך להסיר לערלת הלב שלא תקבל היא עם בחי' הטוב יחד ויכסה על הפנימית ויהופך מטוב לרע כו'. וכמו שאנו רואים בחוש שבכל אדם שמתפעל בהתפעלות אלקות בתפלה בנפשו מחמת התעוררות המשפיע שנמשך מלמעלה לכלל התעוררות בנפשו באוי\"ר שמצד השכל והשגה אלקית ביגיעת המוח והלב כידוע והנה מיד שמתפעל באהבה בלב בחלל הימיני ששם משכן הניצוץ האלקי שבודאי אהבה אמתית היא שהיא בניצוץ האלקי מצד בחי' הארה האלקית כידוע אבל גם נפשו הטבעית שבלב בשר בחלל השמאלי תתפעל גם היא לפי שעה כו'. ובו ערלת הלב דבוקה שמקבל בחי' החיצוניות ופסולת שאינה מצד אלקות כלל רק לגרמי' וישות וגסות בלבד וזהו עיקר ענין התערובות טו\"ר אמת ושקר יחד וכמ\"ש במ\"א ע\"פ לא יחפוץ כו' כ\"א בהתגלות לבו (משלי יח, ב) ואז מיד אחר התפלה מתגברת האהבה רעה שבנה\"ט למשוך אחר תאות הבהמיות ונהפך גם הטוב דאהבה האלקית ונבלע באהבה הרעה כפרות הרעות שבלעו את הטובות כו'. וזהו מצד שלימות הערלה שבלב שלא הוסרה כלל וכלל כי לא נשבר לבו בתשובה אמיתית מעולם ולבו קשה כאבן ובעודנו בקשיו ושלימות שלו יבא גם הוא להתפעל בהתפעלות אלקות עם בחי' הטוב דאהבה האלקית שבפנימית הלב ע\"כ מתערב טו\"ר ויכסה הרע על הטוב כו'. ולזה צריך להסיר ערלת הלב בלב נשבר לגמרי כמ\"ש (דברים י, טז) ומלתם כו' שאז נפרד הרע מן הטוב לגמרי שהיא אהבה הרעה שבנה\"ט מן הטוב שבנה\"א עד שהשפע עליונה בנה\"א מקבל ועולה רק בחי' הטוב ופנימי' שבה בלי תערובת זר כלל וכמ\"ש מי יעלה בהר ה' נקי כפים ובר לבב (תהלים כד, ג-ה) (דוקא) אשר לא נשא לשוא נפשו ורצונו כלל הוא ישא ברכה בבחי' הפנימי' כו' וד\"ל ואז גם בבחי' מעשה הטוב דמצות ובסור מרע כל היום יהי' ג\"כ בתכלית הכשרון לב בתמימות העבודה בלי שום תערובת זרה כלל רק לעשות רצון קונו לבד כו'. וזהו ענין המילה שבזמן הגלות ע\"י תשובה ומע\"ט לבער הרע להבדילו מצד העבודה השלימה בבחי' בר לבב הנ\"ל בתפילה שהוא ע\"י התשובה מן המיצר שמשבר את הערלה והן בירור דיסורי הגלות כו' וכמ\"ש ובקשתם משם (דוקא) את ה' כו' ומצאת כי תדרשנו בכל לבבך כו' (דברים ד, כט) וע\"י תו\"מ לבער הרע בסו\"מ וע\"ט שזהו בירור הראשון מלמטה למעלה שא' ע\"ז ומלתם דוקא שאתם תמולו בעצמכם כו' שהוא להבדיל הפסולת הרע מן הטוב והשקר מן האמת כו'. והוא ענין בירור דרפ\"ח ניצוצין מעה\"ד טו\"ר שזה תלוי במעשה התחתונים דוקא וד\"ל:\n(ו) <b>אך</b> הנה אחר הבירור הזה דומלתם את ערלת לבבכם מלמטה למעלה דוקא כנ\"ל. שהוא ע\"י הבדלת הרע מן הטוב בתכלית בתשובה שלימה ובמע\"ט דתו\"מ"],[2300670113,"להבדיל בין טמא לטהור כו' בעבודה השלימה בסו\"מ וע\"ט וע\"י בירור וצירוף ביסורי הגליות שיסורי' ממרקי' כו' (ברכות דף ה, א) ויהיה אח\"כ קיבוץ גליות כמ\"ש אם יהיה נדחך כו' והטיבך והרבך מאבותיך אז ומל ה' את לבבך לאהבה את ה' כו'. וזה פלא גדול למה יצטרכו אז למילה זאת שימול ה' את לבבם אחר שאין ערלה בלב כלל וכלל כו'. אך הענין הוא דאחר אתעדל\"ת דכנ\"י בתשובה תתאה בלב נשבר ונדכא בתשובה שלימה עד שנברר הרע מן הלב ונקי מכל סיג ונק' בר לבב וגם ע\"י הבדלה דתו\"מ כנ\"ל. אז נתעורר אתעדל\"ע דהיינו שישוב ה' אלינו מלמעלה למטה כמו ישוב ירחמנו (מיכה ז, יט) וא' בזוהר ישוב מאן אתר מההוא עתיקא סתימאה כו'. והוא שיאיר מבחי' פנימית המוחין דע\"ס מי\"ג מדות הרחמים בפנימית יסוד דע\"י שנק' צ\"ע בבחי' פנימיות שבו בלי העלם ולבוש כלל וזהו שנק' למעלה תשובה עילאה שאחר תש\"ת הנ\"ל דוקא וד\"ל והוא ענין המילה שמלמעל' למטה (שבבחי' פנימית יסוד דע\"י וא\"א ששרשו ביסוד דא\"ק כו' כמ\"ש במ\"א ע\"פ למנצח על השמיני' כו') (תהלים יב, א) שא' ומל ה' את לבבך כו'. אחר שכבר נימול מצד העבוד' דתו\"מ ותש\"ת הנ\"ל. וע\"ז ארז\"ל גדולה מילה שנכרתו עליה י\"ג בריתות שהן י\"ג מדה\"ר הגדולים שמתגלים בבחי' הפנימית דע\"י מבחי' רדכ\"ר שבמצחא כו' ונק' מילה גדולה כמ\"ש גדולה מילה שנכרתו עליה כו' והטעם הוא כי עיקר ענין המילה בכללותה הוא ענין כריתת ברית לבד כמ\"ש לאברהם והקימותי את בריתי ביני וביניך ובין זרעך אחריך כו'. וא' זאת בריתי אשר תשמרו ביני וביניכ' כו' המול לכם כל זכר כו' ונמלתם כו' והיה לאות ברית ביני וביניכם כו' כידוע. אך בענין הכריתות ברית יש ב' מדרגות א' כמו ב' או\"נ שיעשו ביניהם כריתות ברית שזהו מצד שהגם שהן או\"נ יוכלו להפרד זה מזה במשך זמן רב שתשכח האהבה מן הלב או מצד איזה סיבה שיפרידו ביניהן דברי נרגן כו' (משלי כו, כב) לפי שבעצם הן נפרדים זה מזה ואהבתם ניקנית אצלם בדרך בחי' תשוקה והמשכה מן המוח ולב כמים כו'. וכמ\"ש כמים הפל\"פ כו' כן לב האדם לאדם (שם כז, יט) ומצד ריחוק ופירוד שלהם יש בזה הפסק וביטול לפרקים כמו כשבטל דבר בטלה האהבה אם האהבה תלויה בדבר כו' (אבות פ\"ה, טז) וכמו כן כריתות ברית מגבוה לנמוך כמו מלך ושר לעני ושפל שאין ערך ביניהם כלל אך הכריתות ברית שלהם מכריח לגבוה להשפיל א\"ע תמיד להדבק בנמוך כו' שאין זה מצד עצם האהבה כלל שאין להם ערך זע\"ז כלל. והמדרגה הב' היא כריתות ברית בב' או\"נ בנפשותם ממש כאהבת דוד ויהונתן שאהבת נפשו אהבו שלא יפרדו לעולם וכן אהבה עצמית דאב לבן וכה\"ג שזהו כאהבת אדם לעצמו ממש שלא יתכן בזה ענין אהבה בתשוקה והמשכת הלב כלל וא\"כ ענין הכריתות ברית בהם הוא בבחי' עצמיות שהוא בחי' התקשרות האמיתית בעצמיו' נפשם שהן לאחדים כנפש א' ממש ואין ענין הכריתות ברית בהם רק להיות להם לאות וזכרון הברית העצמי הזה ע\"כ צריך להיות אות הברית הזה המורה על בחי' התקשרות העצמיות"],[2300670129,"דוקא ולא בשביל שלא יפרדו שא\"א להם להפרד כלל לעולם וד\"ל:\n(ז) <b>והנה</b> הדוגמא מכל זה יובן בדרך כלל למעלה בכנ\"י עם הקב\"ה שיש ב' מיני כריתות ברית. א' הברית הפנימי והעצמי שכרת עם א\"א ע\"ה ע\"י המילה כנ\"ל. והב' כריתות ברית שכרת משה עם ישראל ע\"י התו\"מ והוא ברית דתורה שנכרתו עליה ג' בריתות לבד אבל ברית דמילה נכרתו עליה י\"ג בריתות כנ\"ל. וע\"כ צריך להזכיר בבהמ\"ז ברית קודם לתורה כמ\"ש ועל בריתך שחתמת בבשרנו ואח\"כ ועל תורתך שלמדתנו כנ\"ל וד\"ל. ואעפ\"י שגם בברית דתורה יש ג\"כ ענין מילה שז\"ש ומלתם את ערלת לבבכם שזהו ע\"י הבדלה דטו\"ר שע\"י מצות ותשובה. הענין הוא עד\"מ בשני בנ\"א האהובים שכורתים ברית לבל יפרדו כו' שאהבתם נעשית ע\"י הרכבה בדבר מה בשכל ומדו' שיכול להפרד ע\"כ כורתי' ברית כו'. וכך הוא בענין ברית דתו\"מ דכנ\"י שניתן להם בבחי' ברית שלא יפרדו לעולם מאלקי' חיים והוא בג' מדרגות דמוח ולב ומעשה בבחי' אדם דהיינו בג' מדרגות דתורה ומצות שיתקשרו בחכ' שבתורה שנק' תורת האדם ובמדות שבה והוא ע\"י אוי\"ר שנוגע למעשה והמעשה עיקר ע\"י קיום המצות בפ\"מ שהוא העיקר להקים את דברי הברית דתורה כו'. שעי\"ז נמשך ג\"כ אא\"ס אליהם בהתקשרות דג' מדריגות האלה שלמעלה בשורש התו\"מ שהן מוחין ומדות ומעשה שהן כללות ע\"ס דאדם דאצי' וז\"ש כמים הפנים לפנים בהעלאת מ\"ן דתורה ומצות דישראל כן לב האדם העליון לאדם דכנ\"י באהבה וחסד כו' וכמו והיה אם שמוע תשמעו כו' ונתתי מטר כו' וכן אם בחוקתי תלכו כו'. שבזה יש ברית והתקשרות דכנ\"י בהקב\"ה וכמאמר ג' קשרים הן ישראל מתקשראן באורייתא ואורייתא בקודב\"ה כו'. ולכך נכרתו ג' בריתות נגד חב\"ד חג\"ת נה\"י בכלל ובפרט כו'. וז\"ש לעברך בברית ה' אלקיך דוקא שזהו ע\"י תו\"מ דוקא (שכללותם הוא בחי' נר\"נ דאדם ע\"י תו\"מ שנק' תורת האדם ורמ\"ח מ\"ע שהן רמ\"ח אברים דמלכא כידוע) אבל ענין הברית דמילה הוא בחי' כריתת ברית העצמות כמו בב' אוהבי נפש בנפשותם הנ\"ל וכאב עם הבן שא\"א שיפרדו לעולם משום שנפשם א' הוא ממש ואין אות הברית הזאת רק הוראה על התקשרות העצמית לבד כנ\"ל. וכך הוא בכנ\"י ובכל א' בפרט בבחי' יחידה שבנפשו שההתקשרות הוא שם בעצמות הנפש ממש שבלתי מורכב בדבר מה כלל רק רצון עצמי ופשוט שלמעלה מן הטעם ודעת וגם למעלה מבחי' החכ' שבתורה ומצות (כמו בע\"ת אמיתית כתשובה דראב\"ד כו' (ע\"ז פ\"ק) שעולה ומתקשר למעלה מצד העצמיות לבד שזהו בחי' ומדרגה דמשיח שיגאלו ע\"י תשובה שלמעלה מן הברית דתו\"מ כו'. ומזה יהיה העוה\"ב שנא' (שמות כא, ב) ובשביעית יצא לחפשי חנם חנם בלא מצות כמ\"ש במ\"א) שאין בזה הפסק וביטול לעול' רק הכריתות ברית הוא על בחי' הפנימיות ועצמיות דהתקשרות הזאת וזהו אות הברית דמילה שא' לאברהם זאת בריתי אשר תשמרו ביני וביניכ' (ממש) המול לכם כל זכר כו'. שמורה על פנימית ועצמיות כמו ההתקשרות דאב לבן"],[2300670145,"שנבדל מכל חיצוניות זולתו שהוא למעלה הרבה מג' בריתות דתו\"מ שהן רק בבחי' נר\"נ דאדם כנ\"ל. שיש בזה הפסק וביטול כמו אם בחוקותי כו'. ואם לאו תופר הברי' הזה להתהפך מאהבה לשנאה להמשיך להם קללה כו'. וכן בסיבת הריחוק זה מזה משך זמן רב בגלות שנשכח הברית שבגלות נאמ' (ישעי' נ, א) ובפשעיכם שולחה אמכם דאתתא אתתרכ' מבעלה וקודב\"ה בגלותא אסתלק לעילא לעילא כו'. ע\"כ ומצאהו רעו' רבות וצרו' כו' כי אין אלקי בקרבו כו' (דברים לא, יז) וכה\"ג אבל ברית דמילה שהוא בבחי' העצמיות שלמעלה מבחי' אדם דתו\"מ שנכרתו עליה י\"ג בריתות שהוא בבחי' פנימיות דע\"י שלמעלה גם מן הח\"ס דא\"א כו'. וע\"ז א' ואף גם זאת בהיותם בארץ אויביהם לא מאסתים כו' לכלותם להפר בריתי אתם (ויקרא כו, מד) והוא מ\"ש ז\"ל גדולה מילה שנכרתו עליה י\"ג בריתות שהן י\"ג מדה\"ר שנמשכים מלמעלה מן החכ' והוא מבחי' רדכ\"ר שלמעלה ממשפט התורה למחול ולסלוח גם לעוברי רצונו והזדונות נעשו לו כזכיות ביו\"כ כידוע לפי שזהו בבחי' כריתות ברית העצמיות הנ\"ל שבלתי מורכב כלל בדבר מה גם לא בתו\"מ הגם שהן פנימיות רצה\"ע כו' וד\"ל:\n(ח) <b>וזהו</b> ומל ה' את לבבך ואת לבב זרעך לאהבה את ה' אלקיך בכל לבבך כו' למען חייך פי' למען חייך ממש שהוא חיים עצמיים שיחי' מחיי החיים דבחי' עצמות אא\"ס ממש שהוא בחי' התקשרות הפנימית ועצמיות דבחי' יחידה הנ\"ל שמקושרת בפנימית דעצמות אא\"ס שבפנימית ג\"ר דע\"י שהן י\"ג מדה\"ר העצמיים שלמעלה מי\"ג מדה\"ר שנק' י\"ג ת\"ד כו' דכתיב (במדבר ו, כה) יאר ה' פניו אליך שמאירים גם בזמן הגלות כמו בזמן בהמ\"ק ממש בשוה לפי שהן שלא ע\"י התלבשות בח\"ס שגבורות דע\"י מלובש בח\"ס וחסד דע\"י בגלגלתא ואו\"א מלבישים לזרועות דא\"א כו'. אבל י\"ג בריתות הללו הן הבאים ונמשכים מפנימית ג\"ר דע\"י בפנימית יסוד דע\"י וזהו במילה עליונה מלמעלה למטה כמ\"ש ומל ה' את לבבך כו' למען חייך העצמיים בבחי' אהבה העצמית ממש שלא יתכן בזה ענין המשכה ותשוקה כמים כלל אלא כמו אהבה עצמה ממש שהיא למעל' מברית דתו\"מ שמורכב בדבר מה ברצון וחכ' ומדות כו' וד\"ל. אך הנה א\"א לבא בחי' מילה עליונה זו מלמעלה למטה שהוא למען חייך ממש כנ\"ל כ\"א בהקדים תחלה המילה מלמט' למעלה ע\"י תו\"מ ותשובה דוקא שזהו להבדיל הפסולת מן הפנימיות לגמרי שהוא ע\"י בחי' החכמ' דוקא שהחכ' הוא המברר ומבדיל בין טו\"ר אמת ושקר. כמשל התלמידי' שיושבים בפני רבם ולומדים דבר הלכה שיש בזה תערובות טו\"ר אמת ושקר בלי נודע מהו האמת ומהו השקר וטעות אך ע\"י העיון האמיתי שבחכ' מתברר האמ' ונבדל השקר והטעו' כמצרף לכסף שמבדיל הפסול' והסיגים לגמרי ונשאר הנקי בתכלית כך מצרף לחכמה ממש ללבן ולברר להוציא תכלית האמת ולהפריד ולהבדיל כל סיג ופסולת כו'. וכך הוא בחכ' שבתורה דבחכ' אתברירו רפ\"ח ניצוצין שנפלו בק\"נ כידוע"],[2300670161,"שבחכ' דתורה הוא המברר בין טו\"ר דעה\"ד טו\"ר בתכלית הבירור כמ\"ש (ויקרא יא, מז) להבדיל כו'. וכך הוא בניצוץ האלקי שיש בה תערובת טו\"ר ע\"י שנשמתו מלובש בנה\"ט שנמשכה מעה\"ד טו\"ר דק\"נ עד שמתערב הטוב שבניצוץ כמו האהבה האלקית באהבה הטבעית דנה\"ט בחום הטבעי שיש בה אהבה זרה ונכרי' בתאוות רעות כבהמה כו' וע\"י בחי' החכמ' שבניצוץ האלקי מתברר בחי' הטוב שבניצוץ האלקי ועולה ונדבק למעלה בה' אחד במס\"נ כמ\"ש (תהלים כה, א) אליך ה' נפשי אשא בלי שום תערובות זר כלל שנק' (שם כד, ד) בר לבב כו' וכמו שא' בחנתנו א' צרפתנו כצרף כסף (שם סו, יא) בלי תערובת סיג כלל ונק' לב טהור כמ\"ש (שם נא, יב) לב טהור ברא לי כו'. עד שממילא עי\"ז הבירור האמיתי בלב ימצא בירור כזה גם בבחי' המעשה בתו\"מ וצדקה ובסור מרע כל היום ג\"כ בתכלי' הכשרון והזדככו' בתמימות שלימה בלתי שום תערובות כוונה זרה כלל רק לה' לבדו וא\"ל לא יעלה לרצון לפני ה' כלל כי לא יגורך רע כתיב וז\"ש ומלתם את ערלת לבבכם כנ\"ל. שזהו ענין בירור תערובת הרע שבנוגה שנפלו שם רפ\"ח כו'. וכאשר כבר מתברר מעה\"ד טו\"ר כל בחי' הטוב למטה אז גם למעלה בבחי' חכ' דמל' דאצילות מתברר כל הרפ\"ח כו' מכל ימי הגלו' אז נעשה קיבוץ גליות כו' וכתי' אז (זכרי' יג, ב) ואת רוח הטומאה אעביר מן הארץ וכן (ישעי' כה, ח) בלע המות כו' וגם בכנ\"י נפרד הרע מן הטוב לגמרי עד שלא יהיה לכנ\"י רק לב אחד לאביו שבשמים כו' ולזה א' והטיבך והרבך מאבותיך וכמו\"כ למעלה במל' דאצילות יהיה תכלית הבירור מרפ\"ח כו' אז נאמר ומל ה' את לבבך כו' בחי' מילה עליונה הנ\"ל שבאה מלמעלה למטה שזהו שנק' בירור אחר בירור דהיינו לאחר שכבר הוברר ע\"י בירור דחכ' דתו\"מ בתכלית ההבדלה דטו\"ר כנ\"ל. ויהי' כולו נקי בלי סיג כלל אזי ראוי שיומשך על זה מבחי' אור הפנימית ועצמות שנמשך בבחי' פנימית יסוד דע\"י (שזהו כמו העלאת מ\"ן דנוק' כשמתברר היטב ונבדל כל הפסולת אז מתברר בירור שני להכלל בבחי' מ\"ד דדכורא שהוא בירור שני כענין נשמות ומלאכי' שעולין מדי חודש ושבת להשתחוות לפני ה' בביטול העצמות ממש שנבדל מכל בחי' יש ובא לכלל בחי' אין ומה בתכלית בהשתחוואה זאת אזי בא לידי בירור שני שהוא לאשתאבא בגופא דמלכא ממש כענין מיכאל מקריב נשמות ע\"ג המזבח כו' כידוע. וכך יהיה בירור שני שהוא בירור העליון לברר למ\"ה שכבר נברר בבחי' ב\"ן דנוק' והוא מבחי' פנימית יסוד דע\"י שע\"ז אמר במשיח (שם נב, יג) ישכיל עבדי ירום ונשא כו' שזהו מבחי' פנימית ג\"ר דע\"י שלא בא' ע\"י התלבשות בחיצוניות דע\"י וא\"א באו\"א כו' והן י\"ג מדה\"ר העצמיים הנ\"ל שאינן באים ע\"י א\"א ואו\"א כו') שיכולי' להאיר גם בגלות כמו בבהמ\"ק כנ\"ל. וזהו ומל ה' את לבבך כו'. שע\"ז א' גדולה מילה שנכרתו עליה י\"ג בריתות דוקא דאע\"פ שי\"ג מדה\"ר כבר יש בכל יוה\"כ לנשמות בגופים זהו הבא ע\"י התלבשות בחיצוניות דמדות דע\"י בא\"א ואו\"א כנ\"ל. אבל בבחי' מילה עליונה שהוא ענין כריתות ברית"],[2300670177,"העצמיות שלמעלה הבא' אחר ברית דתורה דוקא עי\"ז נעשה ונמשך י\"ג מדה\"ר העצמיים שזהו בחי' הארות הפנימיות והעצמיות דא\"ס ממש כאב הכורת ברית עם בנו או ב' או\"נ בנפשותם כנ\"ל. משא\"כ עכשיו אין חיבור המאציל עם הנאצלים ע\"י י\"ג תיקונים רק בדרך הכרח כמלך שכורת ברית עם עבד שהוא הגבוה עם הנמוך שמשפיל א\"ע ולא מצד עצמותו שאין ערך ביניהם כלל כך אין ערך כלל לנאצלים לגבי עצמות המאציל רק שמתצמצם א\"ע להאיר בהם ע\"י כריתות ברית שזהו רק דרך התלבשות לבד ואין זה מעצמות המאציל ממש כו'. אבל י\"ג בריתות דמילה עליונה הן י\"ג מדה\"ר העצמיות (לחיי הנשמות) שהן באים מבחי' פנימיות ועצמות ממש שלא ע\"י הלבשה כלל וזהו ומל ה' את לבבך כו' למען חייך ממש חיי הנשמות בשרשן בעצמיות ממש שישראל עלו במח' וע\"ז נכרתו י\"ג בריתות בפנימית יסוד כו' כנ\"ל וד\"ל:\n(ט) <b>וזהו</b> בעצם היום הזה נמול אברהם כו'. פי' נימול בבחי' מילה העליונה הנ\"ל שיהיה לע\"ל שנא' ומל ה' כו'. שהוא בבחי' פנימית יסוד דע\"י שלמעל' מהתלבשות באו\"א כו' והוא ר\"ת דמי יעלה לנו כו' שהוא בירור השני שאחר בירור הראשון דע\"י תו\"מ ותש\"ת שהוא ס\"ת דמי יעלה כו' כנ\"ל. אך הנה תחלה יש להבין מהו ענין המילה הזאת דומל ה' כו' אחרי שיהי' קיבוץ גליו' והטיבך והרבך מאבותיך שהוא ימות המשיח כו' שיהיה לבנ\"י רק לב אחד לאביהם שבשמים נקי מכל סיג בתכלית וכמ\"ש ואת רוח הטומאה כו' כנ\"ל. א\"כ איך יתכן לשון מילה בזה שכבר הוברר והוסר כל ערלה וכל סיג דק שבדקות ואיך נק' בשם בירור שני מה צריך בירור בזה וענין מילה לא יתכן כ\"א בבחי' הבדלה והפרשה עכ\"פ שימול ויכרות דבר מה להבדיל ממנו החיצוניות ויגלה בחי' הפנימיות כנ\"ל. והרי לאחר שנברר הכל בתכלית הרי הכל בחי' פנימית לבד ואין שם בחי' חיצוניות כלל וכ\"ש שאין שם פסולת וסיג כלל כו' ואיך א' אחרי והטיבך כו' ומל ה' את לבבך כו' ומכ\"ש לפי המבואר למעלה במילה עליונה זו שהוא למען חייך העצמיים שהוא בבחי' התקשרות העצמיות דבחי' יחידה כו' איך שייך שם ענין מילה כלל כו'. והנה יש להקדי' לזה ענין א' והוא בבחי' ה' מדרגות נרנח\"י שבאדם דנר\"נ הוא הבא בציור אדם במוח ולב ומעשה כנ\"ל. וחיה יחידה הן בחי' ב' מקיפי' כו'. וביאור ענין ב' מקיפי' הללו ידוע במ\"ש (תהלים לט, ז) אך בצלם יתהלך איש שהן למ\"ד ומ\"ם דצלם והוא מקיף דחיה ומקיף דיחידה וההפרש ביניהם הוא שמקיף דחיה הוא המקיף לנר\"נ שבגוף לפעול בהן שינוי או התעוררות כמו הרצון שבהעלם שלמעלה מן הטעם ובא לגילוי לעורר את השכל והלב ומוד\"מ כו' וכהתעוררות תשובה פתאום בלב נשבר כו' וכמ\"ש (ישעי' לב, טו) עד יערה עלינו רוח ממרום שזהו רוח המקיף וכן בענין האהב' שיתעורר לאהבה בלתי שום הכנה לפי שבאה מן ההעלם דמקיף וכן ביראה ופחד שיתעורר פתאום לירא ולפחוד מאלקי' בלתי הכנה כלל משום דהמקיף הזה מאיר בנר\"נ במוח ולב גם במעשה וראי'"],[2300670192,"מדניאל וחביריו שאעפ\"י שחבריו לא ראו כלום מזלייהו חזי (מגלה ג, א) ונפלה עליהם חרדה גדולה הרי פעל חרדה מורגשת בגוף מן ההעלם דמזלייהו חזי כו' וד\"ל (וכענין לב יודע מרת נפשו (משלי יד, י) שהיא בהעלם ומרגיש בלב פתאום כו' וכה\"ג) וכך הוא בבחי' התענוג שבהעלם בנפש שיבא לידי גלוי בנר\"נ וכלים שלהם במורגש כמו בשור' טובה שא' (שם טו, ל) שמוע' טובה תדשן עצם וכמעשה דאספסיינוס (גיטין נו, ב) הרי התענוג הרוחני שבנפש בא לידי הגשמה ובמורגש במוח ולב עד שתדשן עצם הגשמי לעשות בו התפשטות בתוס' שמנונית ושיקוי של עצמות שנק' דשן כמו חלב ודשן תשבע נפשי שתענוג האלקי שבנשמה הי' אצלו כמו חלב ודשן שמדשן הבשר והעצמות כך תשבע נפשו בעונג האלקי במורגש ובהגשמה כחלב ודשן כמו ישבעו ויתענגו כו' וכמו כל התענוגים הגשמיים כמעדני מאכלים שמוסיף התפשטות בבשר ועצמות כמו שמנת עבית כשית (דברים לב, טו) והוא בחלב שמדשן העצם ובדם ובשר לעדן את הבשר כו' וכך כל תענוגים הרוחני' יותר כשחוק וטיול וכבוד וגדולה ועושר וכל חמדת עוה\"ז כו'. וכל זה הוא שבא מן ההעלם שבנפש לבא במורגש עד גם התענוג שבשכל ורצון בדבר מה שהעיקר הוא התענוג המורגש בו ונק' כל זה בחי' עונג המורגש אבל בחי' מקיף דיחידה שהוא מ\"ם דצלם הוא הבלתי מאיר ובא בנר\"נ דאדם במוח ולב כלל ונק' מקיף למקיף דחי' כנ\"ל כידוע והוא בחי' עצמות הנפש ממש שגם בחי' התענוג והרצון שבה הוא רק בבחי' תענוג ורצון הנעלם בבחי' עצמותה ומהותה ממש ונק' תענוג ורצון עצמי ופשוט בבחי' עצמיות הנפש ממש שאין ערך כלל לרצון ותענוג הבא בנר\"נ שבגוף הנ\"ל אליו כלל מאחר דמה שנמשך איזה הארה דתענוג ורצון בנר\"נ היינו רק ממקיף דחי' הנ\"ל והוא מה שהנפש נתמלאה תענוג בעצמה עדיין משמועה טובה כמו ותחי רוח יעקב (בראשית מה, כז) בעצם משמועה טובה דיוסף וכן בשרה מיצחק וכה\"ג באהבה בתענוגים ישנה בהעלם עצמות התענוג שבנפש רק שלא תוכל לבא במורגש שלא יכילנו המוח והלב כלל ולזאת לא יבא בחי' התפשטות מתענוג זה העצמי בגוף כלל רק בנפש עצמה. וראי' לזה מהיפוכו שהוא הצער שנק' מורגש בגוף לנגד עונג המורגש הנ\"ל שכל צער ויסורים הוא רק היפוך העונג כו' יש ג\"כ צער בנפש עצמו ממש מבשורה רעה מאד שנוגע לעצמות נפשו ממש וכמו בחנה שא' (ש\"א א, י) והיא מרת נפש ממש כו' רק שאינו בא במורגש במוח ולב רק בהעלם גדול לפרקים (כמו לב יודע מרת נפשו ממש אך הוא רק בהעל' ולא במורגש ממש דלא כדלעיל):\n(י) <b>והנה</b> אחר הקדמה זאת יובן ג\"כ בענין המקיפין דחי' יחידה הנ\"ל בנשמה האלקי'. ומזה יובן ג\"כ למעלה בבחי' מקיפי' הללו דנר\"נ דאדם העליון דאצילות כו' להיות שיש ב' מדרגות בתענוג ורצון שבנשמה בהתענגה על ה' א' תענוג ורצון המורגש בלב ומוח אעפ\"י שהוא למעלה מן ההשגה והטעם כו' כמו לבי ובשרי ירננו כו' (תהלים פד, ג) וכן מ\"ש (שם) כמו חלב ודשן תשבע נפשי ושפתי רננות יהלל"],[2300670207,"פי דהכוונה הוא דשפתי רננות שבפיו שבא בשיר פשוט בלב בתענוג מורגש מאד כמו תענוג המורגש הבא מחלב ודשן שתשבע נפשו ממש כענין ישבעו ויתענגו במורגש בלב בשר וחלב ודם כו' וכידוע בענין תפלת השבת שע\"ז א' אז תתענג על ה' כו' (ישעי' נח, יד) שנק' שיר אל שהוא מה שהנשמה תשיר שיר אל ממש וכמ\"ש כל הנשמה תהלל יה כו' והוא מקיף דחי' שבא לנר\"נ להתענג גם במוח ומדות ומוד\"מ כנ\"ל בשמועה טובה הנ\"ל ובמרירות היפוכו כו' והמדריגה הב' הוא בחי' מקיף דיחידה שהוא התענוג העצמי בבחי' התקשרות עצמות הנ\"ל מצד פנימיות ועצמיות הנשמה כמו שהיא דבוקה וקשורה למעלה ממש כמו רשב\"י שא' בחד קטירא אתקטרנא בי' אחידא בי' להיטא כו' וכה\"ג בכל נשמות שבבחי' אצילות ממש שהן בתמידות ההתקשרות למעלה ולא למטה כלל שאין התפעלות התענוג שבנשמה בנר\"נ במורגש ערך לזה כלל כנ\"ל (כמ\"ש במ\"א שזהו ענין עדן סתימאה שלמעלה הרבה מתענוג הנשמות שבג\"ע מזיו דמל' דאצילות והוא שעולים ומשתחוים ומתבטלים שם בכל חדש ושבת (והוא הבירור השני לאשתאבא בגופא דמלכא כו' כמשי\"ת) וזהו אה\"ר דכל מאדך שהוא אה\"ר בתענוגי' שבעצמות הנשמה ממש בבחי' התענוג הנעלם דיחידה שלא יוכל לבא במורגש כ\"א לפרקים (כמו בשבת כמשי\"ת) כמו במס\"נ בפ\"מ ולעוה\"ב כו' לפי שלא יכילנו כלי הנר\"נ כלל כנ\"ל וע\"כ אין לנר\"נ דאדם חיבור וקשר עם מקיף זה דיחידה כלל כ\"א בהעלם גדול מרחוק כו' (וע\"כ א' (תהלי' כב, כא) מיד כלב יחידתי שאין מקום לחיצונים כלל וכלל בבחי' יחידה הנ\"ל ולזה א' בזוהר ונפש כי תחטא (ויקרא ה, א) תווהא הוא כו' ושם אמר כולך יפה רעייתי כו' (ש\"ה ד, ז) כמ\"ש במ\"א) אבל מבחי' התענוג והרצון האלקי הבא במורגש בנר\"נ וכלים שלהם אעפ\"י שהוא בתכלית האמת מצד הנשמה שתהלל יה בשיר פשוט כמ\"ש לבי ובשרי כו' ושפתי רננות כו' באה\"ר בתענוגים וכמו נכספה וגם כלתה נפשי כו' (תהלים פד, ג) וכן צמאה לך נפשי כמה לך בשרי כו' וכשיר אל דשבת הנ\"ל מ\"מ יש בזה אחיזה וקשר גם לגוף להתפעל בתענוג במורגש בלב בשר כמ\"ש לבי ובשרי כמה לך בשרי כו' שזהו בחי' החיצוניות דתענוג האלקי הרוחני שבנשמה שמורכב בעונג הגופני והיו לאחדי' ממש ע\"כ יוכל להיות שיסתעף מזה העונג המורגש ליפול בתענוגים גשמיים המגשמים ממש ומרחיבים לב האדם לבא בבחי' פירוד מאלקו' והגם שאינו נוטה אחרי הרע כלל וכלל כי לבבו שלם ונקי מכל סיג ע\"י בחי' הבירור הראשון דחכמ' שבנפש בעבודה שבלב ומוח וע\"י תו\"מ כנ\"ל אך מחמת סיבת ריבוי הטוב בגשמיות התענוגים יכול ליפול מטוב לבבו כמו שא' (דברי' ח, יב-יד) ובתים טובי' תבנה כו' וכסף וזהב כו' ורם לבבך כו' וכתענוגי' גשמיי' שקפחו י' השבטי' (שבת קמז, ב) וכמו שמנת כו' וישמן ויבעט וכה\"ג וכל זה מפני שאה\"ר בתענוגים האלקי' שבא במורגש יבא בהגשמה בגוף ואין לו בירור ותיקון שיבדל מזה כל פסולת תענוג הגופני המגשם ממש כו' (וכמו סעודת השבת שמותר לאכול לתאבון וע\"כ או' דא היא סעודת' דע\"ק כו' מטעם שעונג האלקי דנשמה בא"],[2300670222,"במורגש בנשמה וכנ\"ל ולזה א' ולא פרש שבתכם עכ\"ז הוא מגשם לגוף מצד התענוג הגשמי שבגוף שאינו נברר והוא מעורב טו\"ר גמור מעה\"ד טו\"ר וכך גם שאר התענוגים הרוחניים כמו שמחה ש\"מ וכתפלה בדביקו' והתלהבות התענוג האלקי בלב בשר כנ\"ל הרי מתערב בו גם חלק התענוג הגופני להיות בבחי' יש וגסות גמור אע\"פ שאין בו רע כלל וכלל כידוע ליודעים וד\"ל:\n(יא) <b>וזהו</b> שא' ומל ה' את לבבך ואת לבב זרעך לאהב' כו' למען חייך דוקא והיינו דוקא אחר שיהי' קיבוץ גליות והטיבך והרבך מאבותיך אז ומל ה' כו' שזהו בירור השני לאחר בירור הראשון כנ\"ל ולא יקשה כלל איך שייך בירור השני במה שכבר הוברר מכל סיג ופסולת כנ\"ל ואיך שייך לשון מילה בזה כנ\"ל דהנה לפי כל הנ\"ל בענין ב' מדרגות דעונג הנעלם שבעצמות הנפש ממש ועונג הבא במורגש בנר\"נ שהן ב' מקיפי' דחי' יחידה כנ\"ל באריכות הרי עיקר ההפרש ביניהן הוא מה שבעונג העצמי הנעלם בנפש הוא כולו פנימית וטוב וא\"א שיבא ממנו הסתעפות לתענוג גשמי שבבחי' ישות וגסות כלל אבל בחי' עונג המורגש גם בהיותו בבחי' עונג האלקי הרוחני בנר\"נ יבא בהגשמת תענוג הגופני להתערב בתענוג הגשמי בישות וגסות הגוף (וכמו שמפסולת תענוג האלקי שבג\"ע נמשך שרש הסתעפו' דתענוגי' הגשמיים שבארץ בד' נהרות שיוצאי' חוץ לג\"ע כו' כמ\"ש במ\"א שזהו נפיל' רפ\"ח כו' שנפלו בד' נהרות כו') וא\"כ יובן עכ\"פ דאעפ\"י שיהי' בירור הלב בתכלית מכל סיג עפ\"י בירור דחכ' להבדיל הרע מן הטוב לגמרי והוא מה שיהי' לע\"ל בקיבוץ גליות שרוח הטומאה יעביר מן הארץ לגמרי כנ\"ל שאין ערלה בלב כלל וכלל ואמנם בהתפעלו' התענוג האלקי שבא במורגש בלב בשר יש בו פסולת התענוג האלקי שבא בהגשמ' תענוג גופני כנ\"ל ואעפ\"י שבתענוג הגשמי אין בו רע כלל כי יבוער לגמרי אבל גסות והגשמה יש בו וצריך להבדילו מן העונג האלקי הרוחני בתכלית שלא יתערב בו כמו שצריך להסיר ערלת הלב מן פנימיות שבו וזהו ע\"י הבדלת העונג האלקי בין פנימיות שבו לחיצוניות שבו עצמו והיינו שעונג האלקי המורגש בלב בשר יהי' גם הוא בבחי' אין וביטול בתכלית כמו עונג הנעלם שבעצמות ממש אעפ\"י שהוא מורגש ממש וכמו שאמר כמו חלב ודשן תשבע נפשי בעונג האלקי להיות כתענוג גשמי שמדשן הגוף כך שפתי רננות יהלל פי שהוא בחי' שיר אל דנשמה כנ\"ל ואעפי\"כ ה\"ז בתכלית הביטול ואין האלקי בלי שום גסות גופני כלל וכלל (וכמו נפשנו חכתה לה' כחיך יטעום אוכל בטעם גשמי כך אמר טעמו וראו כו' כטעם מתיקות גשמי כו' כך בטעם החכמה כמו שהיא במקורה בטעם ותענוג הנעלם שכל חיך הטועם או' לי לי כו' וכידוע דב' מדרגות עונג הנ\"ל ה\"ז ג\"כ בטעמי תורה א' בטעם המורגש בחכ' ובינה ומדות כו' וז\"ש אני תורתך שעשעתי וכן ושעשועי את בנ\"א כמו לנשמות בג\"ע שנהנין בעונג מורגש מסודות ורזין דאורייתא והב' בחי' עונג וטעם הנעלם שהן בחי' שעשועי' העצמיים שבהעל' העצמי דא\"ס"],[2300670237,"ממש נאמר בתורה ואהי' שעשועי' כו' שיתגלה לע\"ל להיות במורגש וכן בכל שבת מאיר מהעלם העונג דעדן סתימאה לנשמות בג\"ע בעלותם שם כנ\"ל) וכן מ\"ש לבי ובשרי ירננו כו' כמה לך בשרי וכה\"ג הכל הוא בא בלב בשר בתכלית ההפשטה מן הגשמיות להיות שגם עונג שבלב בשר עולה יחד עם העונג האלקי בלי שום תערובת זר כלל ואז ממילא אין הסתעפות לתענוגי' גשמיו' לגשם הגוף כלל (וכמו מזון המן שנבלע באברי' וכלחם הפנים שכולו פנים בלי גשם כלל כמו בעה\"ח שלמעלה מעה\"ד כו' וכמו סעודת לויתן לע\"ל וכלחם פנג וכה\"ג יש מעין זה בהעלם גדול בסעודת השבת עד שיכול לומר דא היא סעודתא דע\"ק שהוא עונג העליון שבח\"ע הבא מההעלם לגילוי במורגש לפי שיש בכל שבת מיום שכולו שבת דלע\"ל כו' ולכך א' ולא פרש שבתכם רק עתה שעה\"ד טו\"ר לא נתברר עדיין מגשם הוא לגוף כו' וד\"ל):\n(יב) <b>ולפי</b> זה הרי יובן עכ\"פ שא\"א להיות זה כ\"א ע\"י בחי' המילה עליונה הנ\"ל שהוא להבדיל חיצוניות העונג האלקי מן הפנימית בתכלית ואז יכול להיות גם בלב בשר בלי שום תערובת תענוג זר כלל רק עונג אלקי ממש כמו שהוא בנשמה ממש בשוה כו' ולא יהיה אחיזה מזה העונג המורגש לחיצוני' כלל וכלל דהיינו שלא יהיה בו שום גסות גופני כלל שיוכל לבא מזה בתענוגים גשמיים לגשם ממש כו' וזהו שא' אחר והטיבך והרבך מאבותיך בגשמיות בכל טוב ועונג וכל חמדת טוב עוה\"ז יותר מאבותיך בבית ראשון ואף גם ברוחניות שיבורר מהם כל סיג ופסולת רע מכל וכל שזהו בימות המשיח לאחר קיבוץ גליות אז דוקא ומל ה' את לבבך שזהו להבדיל החיצוניות מן הפנימיות דעונג העליון האלקי שבבחי' חי' דנשמה באופן שיוכל לבא בגלוי במורגש גם מבחי' פנימית התענוג הנעלם העצמיו' ממש שזהו עיקר התגלות דבחי' הפנימיות ועצמיות בבחי' פנימיות יסוד דע\"י שנכרתו עליה י\"ג בריתות שהוא מבחי' פנימית דג\"ר דע\"י כו' וע\"כ לא יהיה גם בעונג מורגש בלב בשר שום תערובת זר כלל כנ\"ל וז\"ש למען חייך דוקא חייך העצמיים דבחי' יחידה הנ\"ל שיבא מן ההעלם במורגש דוקא שהיא מעין ודוגמא של חיי העוה\"ב שא' (משלי ח, כא) להנחיל אוהבי יש ממש וכתיב (הושע ו, ב) יחיינו מיומים ביום השלישי יקימנו ונחיה לפניו ממש פי' יחיינו מיומיים זהו בימות המשיח שיגיעו לשלימות הבירורים דעה\"ד טו\"ר ויחיו בתענוג מורגש בחיי אור פנימי' דח\"ע בסודו' וטעמי תו\"מ וז\"ש והטיבך והרבך מאבותיך שקיבלו התו\"מ בחיצוניות (וגם מן האבות ששרשם רק במדות דחג\"ת דע\"י ובמשיח נא' ישכיל עבדי ירום ונשא וגבה מאד למעלה מחג\"ת דאבות והוא בג\"ר שנק' מאד) ויחיינו זה הוא בא מיומיים שהן תושב\"כ ותשבע\"פ בחי' חו\"ב שנא' (משלי ח, ל) ואהיה שעשועים יום יום ונמשך התענוג הזה בצמצום בחו\"ב שבתורה הנגלית לנו לברר לעה\"ד ומזה נמשך כח הבירור בכל ו' אלפי שנין ולזה יחיינו בימות המשיח מיומיים שקדמו דוקא ואמנם אחר ימות המשיח יהיה העוה\"ב שלמעלה מימות המשיח והוא מ\"ש ביום הג' יקימנו עוד"],[2300670252,"למעלה ונחיה לפניו ממש שזהו בחי' גלוי שעשועי המלך בעצמו בחי' התענוג הנעלם בעצמות המאציל שיבא לידי מורגש שאז א\"צ להבדיל בין פנימיות לחיצוניות העונג כלל משא\"כ בימות המשיח דכתיב ומל ה' א' את לבבך כו' משום דבעצמות התענוג ושעשועי' אין שום חיצוניות כלל והוא בחי' פנימית הכתר דע\"י שלמעלה גם מבחי' חו\"ב שבו כו' וכמו בחי' יחידה העצמית באדם למטה והסימן הוא שגם העונג הבא במורגש בגופי' ממש יהיה ממש כמו העונג הנעלם הרוחני שבעצמות בלי שום הפרש כלל וכלל שז\"ש ונחיה לפניו ממש שהוא מעדן עילאה סתימאה שיבא בגופי' קדושי' שיחיו בתחה\"מ שיהיו כלי ממש לאור העצמו' הזה משא\"כ בימות המשיח שיהיה גופים גשמיים מאב ואם והארץ תוציא לחם כו' רק שאין צריך עבודה והנער בן ק' כו' כי יזדככו מן הרע כו' אבל יש בזה צד חיצוניות העונג עכ\"פ שצריך לומר ומל ה' כו' עד שיוכל לקבל כל טוב עוה\"ז ממש וישבעו ויתענגו על ה' ממש בלי פירוד כלל (וכמו האבות שהיה להם כל טוב עוה\"ז והיו בחי' מרכבה ממש בגשמיות כמו ברוחניות בשוה כו' וכמשי\"ת) ואמנם בחי' מילה זו דומל ה' את לבבך מלמעלה למטה בימות המשיח וזה הוא רק למען חייך שהוא חיי העוה\"ב דוקא שהוא גלוי אור העצמיות ממש שיבא במורגש שאינו צריך להבדלת חיצוניות כלל כי אינו רק בחי' התגלות הפנימיות והעצמות לבד וזהו כמו שע\"י מילה שלמטה בהבדלת החיצוניות ממילא יתגלה בחי' הפנימית בפנימית יסוד כך במילה עליונה זו מלמעלה דכתיב ומל ה' כו' בימות המשיח יתגלה עי\"ז מיד בחי' הפנימית והעצמות שהוא העוה\"ב שע\"ז א' למען חייך ממש וד\"ל:\n(יג) <b>ובכל</b> זה יובן מ\"ש בעצם היום הזה נמול אברהם כו'. לפי שאברהם קיים כל התו\"מ ברוחניות קודם המילה שזהו ומלתם כו' בתכלית הבירור דעה\"ד טו\"ר כמו שיהיה בימות המשיח שהרי אמר שמע אברהם בקולי כו' וע\"כ זכה למילה עליונה זו דנמול עם ה' שעזרו ה' במעשה המילה כמ\"ש במדרש שז\"ש על ומל ה' את כו' ומיד כשנמול ע\"י ה' מלמעלה למטה נתגלה בחי' הפנימית ועצמות דא\"ס בפנימית יסוד דע\"י שלא ע\"י התלבשות בחו\"ב כנ\"ל והוא בחי' חיי העוה\"ב ממש כנ\"ל שא\"צ הבדלה עוד כי אינו רק בחי' פנימית ועצמות וכמ\"ש למען חייך העצמיים והוא מ\"ש בעצם היום הזה שזהו בחי' פנימית דע\"י מפנימית ועצמות המאציל שנק' עצם היום עצמיות של היום הזה שזהו יום שכולו טוב יום שכולו ארוך והוא יום הז' דעוה\"ב שע\"ז אמר ביום הג' יקימנו ונחיה לפניו ממש כנ\"ל וזהו שנא' ושמת שמו אברה' אחר שנימול וממילא ומצאת את לבבו נאמן לפניך בעצמות התענוג הפנימי' שאין שם בחי' חיצוניות כלל והיינו בחי' כריתות ברית שבבחי' העצמיות הנ\"ל וז\"ש וכרות עמו הברית עמו ממש כדי שיתגלה בחי' העצמיות והברית הזה מורה ע\"ז ואבות סימן לבנים לע\"ל דכתיב ומל ה' כו' וד\"ל (ובאמת מילה דאברהם היה כמו העוה\"ב ממש שהרי האבות הטעימן מעין העוה\"ב ממש כידוע והיינו גשמיות שלהם היה"],[2300670267,"כמו הרוחניות ממש בשוה כמו להנחיל אוהבי יש הנ\"ל ממש) וזהו שחזר וכפל אחר שאמר וימל את בשר ערלתו כו' שזהו מילה של מטה ועי\"ז נמול אברהם במילה עליונה שהוא בעצם היום הזה בעיצומו של יום דעוה\"ב כנ\"ל וזהו שלא קיים אברה' מצות מילה עד היותו בן צ\"ט שנה אע\"פ שקיים כל התו\"מ תחלה ברוחניות עכ\"פ לפי שמילה זו העליונה די\"ג בריתות נכרתו עליה מבחי' פנימיות ועצמיות דע\"י כנ\"ל הוא למעלה מכל התו\"מ הנגלה באבי\"ע שזהו שם הוי\"ה בכלל יו\"ד באצילות תורה דאצילות עד ה\"א בעשיה כו' (וזהו שר\"ת דמי יעלה לנו כו' מילה מל יה דהיינו מילה עליונה דמל ה' שיהי' לע\"ל והיינו השעשועים העצמיים שבתורה הקדומה שבשמים עליונים שהוא עה\"ח פנימית הטעמים"],[2300670281,"הנעלם שבעדן כו') וס\"ת שם הוי\"ה דהיינו תורה דאבי\"ע לברר לעה\"ד כו' וע\"כ תחלה קיים כל התו\"מ ברוחניות דאבי\"ע שהוא מילה שמלמטה למעלה שז\"ש ומלתם כו' כנ\"ל ואח\"כ זכה למילה עליונה שנמול עם ה' ממש כמ\"ש במ\"ר והוא שאנו או' אה\"ע ואה\"ר אהבתנו שזה ע\"י ברית דאברהם לתת לזרעו ז' אומות שיעבדו כולם שכם א' כו' ואח\"כ בעבור אבותינו כו' ותלמדם חוקי חיים כו' שהן מצות שקיים ברוחניות כן תחננו ותלמדנו כו' ותן בלבנו כו' שזהו קיום התו\"מ והאר עינינו כו' וזהו היפך סדר הנ\"ל דתו\"מ קודם למילה עליונה לפי שכאן מדבר בכח ועוז העליון דאה\"ע להיות הבירור הראשון דתו\"מ ביח\"ע דק\"ש ובפ' נצבים מדבר מלמטה למעלה דאח\"כ ומל ה' כו' וד\"ל:"],[2300670034,"(א) <b>ויאמר</b> ה' זעקת סדום ועמורה כי רבה כו' ארדה נא ואראה הכצעקתה הבאה אלי עשו כלה ואם לא אדעה כו'. הנה יש לדקדק בפסוק זה הרבה הא' דגוף לשון הכתוב שא' תחלה הכצעקתה לשון יחיד דהיינו חטאת של כללות סדום ועמורה ואח\"כ א' עשו לשון רבים הל\"ל עשתה או הל\"ל הכצעקת' הבאה אלי עשו אלא כמו שמפרש בזוהר כצעקתה של מדה\"ד כו' (וכמשי\"ת) וגם בזה יפול הקושיא מהו הספק בזה ודאי עשו כצעקת מדה\"ד עליהם כו'. והב' מה שא' ארדה נא ואראה כו' דמשמע מזה שאם לא ירד לראות למטה לא ידע האמת מי איכא ספיקא קמי קודב\"ה הלא נא' (זכרי' ד, י) עיני ה' המה משוטטים בכל הארץ כו' ועיניך פקוחות על כל דרכי בנ\"א (ירמי' לב, יט) וכן אמר (תהלים לג, יג) משמים הביט ה' כו' ממכון שבתו השגיח אל כל כו' עד המבין אל כל מעשיהם וכתיב אם יסתר איש במסתרים כו' שאפי' הנסתרות גלויות לפניו ובוחן כליות ולב ואיך יפול לפניו ספק במעשה סדום עד שהוצרך לירד ולראות שא' ארדה נא (למטה) ואראה כו'. והג' איך שייך לשון וענין ירידה באלקי' חיים שמלא כה\"כ וכתיב (ירמי' כג, כד) את השמים ואת הארץ אני מלא בהשוואה אחת ממש והוא נמצא למט' כמו למעל' ממש וא\"כ איך שייך לומר ארדה נא מלמעלה למטה כו' וגם אינו מובן מה שתלה עיקר טעם בירור הידיעה אם כצעקתה כו' אם ירד דוקא ויראה ובלתי ירידה זו לא יבורר לו אם כצעקתה עשו וזהו פלא גדול. והנה במדרש א' ארדה נא ממדה\"ר למדה\"ד שזהו נחשב ירידה מה שיורד מכסא הרחמי' לישב על כסא הדין כו'. וגם זה אינו מובן דממדה\"ר למדה\"ד איך שייך לשון ירידה מלמעלה למטה ועוד איך יתכן שבמה שירד למדה\"ד יתברר לו יותר ולמה יתלה טעם בירור הידיעה הזאת הכצעקתה כו' במדה\"ד דוקא. והנה גם בזוהר א' ע\"ד המדרש הנ\"ל וז\"ל וכי לא הוה ידע קודב\"ה דא' ארדה נא ואראה והא כולא אתגליי' קמי' אלא ארדה נא מדרגא דרחמי"],[2300670050,"לדרגא דדינא כו' דאשכחן ירידה לטב כמו (שמות יט, כ) וירד ה' על ה\"ס אשכחן ירידה לביש וכו' ואשכחן ראי' לטב וירא אלקי' את בנ\"י (שמות ב, כה) ראי' לביש ארדה נא ואראה כו' ואשגחא עלייהו בדינא וע\"ד המכסה אני מאברהם עכ\"ל. ועיקר הדקדוק בפסוק זה הוא מ\"ש בסוף ואם לא אדעה מהו ואם לא דמשמע שמסתפק הוא שמא אין האמת כצעקת מדה\"ד (שא' בזוהר כצעקתה דא גזרת דינא דתבע' על עלמא כו') הבאה לפניו ולא עשו רעה כ\"כ הלא אין דבר נעלם מאתו ית' כנ\"ל וגם מהו שאמר ואם לא אדעה כו':\n(ב) <b>אך</b> הנה כל זה יובן בהקדי' תחל' ענין א' בהשגחה האלקי' על כל הברואים בפרטות דוקא שנבוכו בה כל הפילסופים הראשונים מצד הקושיא שהוקשה להם מאד איך יכול להיות ההשגחה הפרטית שבאה בהתחלקות וריבוי ופירוד מאחדות הפשוטה בתכלית שהוא מושלל מכל ריבוי כו' ואיך ישגיח על כל חלקי הנמצאים בפרט וכתיב עיניך פקוחות על כל כו' ומבין אל כל מעשיהם וגם על חלקי החי וצומח כו' ובאמת אין מקום לקושיא זאת כלל דהא כתיב (ש\"א ב, ג) כי אל דעות ה' ולו נתכנו עלילות כו' דהיינו בחי' ד\"ע וד\"ת ד\"ע הוא בבחי' סובב כ\"ע שסוקר הכל בסקירה א' וכידוע וד\"ת הוא מה שיודע ומשגיח על כל פרטים וכמ\"ש המגביהי לשבת ואז דוקא משפילי לראות בשמים וארץ בהשגחה פרטי' ואין זה ב' הפכים כלל לפי שסובל ב' דיעות הללו יחד (וזהו ולו נתכנו ולא כו') וכמא' דאיהו תפיס בכ\"ע בפרט ולמת\"ב כלל וכך ארז\"ל הוא מקומו ש\"ע ואין העולם מקומו כו' דשניהם אמת וד\"ל (וגם בלשון הרמב\"ם מובן ע\"ד זה במ\"ש (פ\"ב מה' יסה\"ת) שבידיעת עצמו יודע את כל הנבראי' ולא יקשה איך בידיעת עצמו שהוא אחדות הפשוטה יודע את כל הנבראי' שהוא הריבוי כו' מאחר שסובל ב' הדיעות ד\"ע וד\"ת כו') ובזה יתורץ"],[2300670066,"הקושיא הנ\"ל איך שהוא ית' אחדות פשוטה בתכלית ומשגיח על כל בפרט דוקא וכמ\"ש משמים הביט ה' ראה את כל בני האד' כו' והכוונה דגם בהיותו בשמים ביח\"ע דסובב הכללי רואה ומשגיח על כל בפרט כו' וכן מ\"ש ממכון שבתו דוקא השגיח כו' עד שמבין אל כל מעשיהם בפרט $וכמ\"ש במ\"א ע\"פ $תהלים צד, ט&amp; היוצר עין הלא יביט דיש מלאכים שנק' עיינין מארי דאשגחותא וכמ\"ש עיני ה' המה משוטטים כו' עד שיש על כל א' השגחה בפרט וכמאמר דע מה למעל' ממך עין רואה ואזן שומעת כו'&amp; אך הנה באמת מאד יפלא על הפילסופי' שהקשו על ההשגחה שיותר הי' להם להקשות תחלה על עיקר ההשתלשלות שהוא התהוות הבריאה הבאה בבחי' ריבוי והתחלקות ובבחי' גבול ומדה איך ימצא הריבוי והגבול מאח\"פ ובלתי בע\"ג כלל וזה ברור גם אצלם שמאמתת המצאו נמצאו כל הנמצאי' שזהו כח האלקי שנק' עילת כל העילות כו' ולמה הוקשה להם על פרטות ההשגחה דאם יתורץ זה שיוכל להיות התהוות עיקר הבריאה מן אח\"פ בריבוי והתחלקות ממילא יתורץ גם ענין ההשגחה האלקי' על הפרט' כו' וד\"ל:\n(ג) <b>אמנם</b> הנה באמת א\"א לשכל אנושי להשיג ולידע אמתת הענין הזה ע\"י חקירה אנושית כ\"א ע\"י ידיעת והשגת חכמה האלקי' ביחוד עליון דע\"ס דאצילות בעצמו' המאציל ושרשם הראשון בבחי' קו\"ח שאחר צמצום הראשון והוא הנק' בזוהר רזא דמהימנותא כידוע והוא ענין המאמר בכלל במ\"ש אליהו אנת הוא חד ולא בחושבן אנת הוא עילאה על כל עילאין סדכ\"ס למת\"ב כלל אנת הוא דאפיקת יו\"ד תיקוני' וקרינן לון יו\"ד ספירין לאנהגא בהון עלמין סתימין כו' עד לבושין תקינת לון כו' וכל המא' כו'. ויש להבין במא' זה דקשה מרישא לסיפא דבתחלה א' ולא בחושבן שזהו ולא בחושבן י\"ס להיותו בחי' אח\"פ ממש ואח\"ז א' אפיק' יו\"ד תקונין שהן במספר עשר ולא תשע כו' ויקשה הקושיא הנ\"ל ג\"כ איך נאצלו ע\"ס במספר ורבוי מאח\"פ בתכלית וכ\"ש שיוכל להיות אורות בכלים ולבושים כו' לבא בהתחלקות וריבוי עד לאנהגא בהון עלמין כו'. ואמנם הנה באמת כללות הענין הוא דשניהם אמת ואעפ\"י שנאצלו ע\"ס בכלים ולבושים רבים עד התהוות העולמות בריבוי ההתחלקות אין זה שינוי כלל בעצמות המאציל כמו שהוא בטרם שהאציל וברא כל ממש והוא ענין שא' אנת הוא חד ולא בחושבן י\"ס גם עכשיו אחר שהאציל י\"ס כו' משום דאיהו וחיוהי חד ממש כו' ביחוד העצמות וכמו כן בהתהוות הבריאה מאצילות אין שינוי כלל כמו שאו' אתה הוא עד שלא נברא כו' (והוא מ\"ש דאע\"ג דתפיס בכ\"ע למת\"ב כמו קודם שהאציל שא' למת\"ב כלל כו' וכן מ\"ש הוא מקומו ש\"ע כו' וא\"כ אין הריבוי הזה היפך האחדות כלל וד\"ל):\n(ד) <b>ולהבין</b> זה הנה תחלה יש להקדים ענין התחלקות די\"ס מאח\"פ שזהו בא ע\"י צמצום הראשון הנק' מק\"פ שזהו עיקר התירוץ אמיתי לזה ולכל הנ\"ל וענין הצמצום הזה ידוע שזהו מה שנתצמצם אור העצמות בהעלם"],[2300670082,"אחר העלם בעצמות ממש לפי שהוא אור פשוט בתכלית שנק' אור א\"ס ממש והי' הכל בבחי' א\"ס ממש ע\"כ הוצרך לצמצם אורו שיוכלל בעצמותו ולא ישאר רק בחי' רשימו בעלמא שזהו כמו נקודה די' לבד ומן הי' נמשך קו אחד בעלמא והוא הקו\"ח שממנו נמשך ראש ומקור להתחלקות דע\"ס דאצילות במספר עשר דוקא ולבא בבחי' כלים ולבושים כו' ונמצא שבעצמות א\"ס לא הי' שם בחי' התחלקות לי' כלל וז\"ש אנת הוא חד ולא בחושבן כלל אחר שהי' הכל בבחי' אור א\"ס הפשוט בתכלי' אלא אחר צמצום אור העצמות ע\"י הארת הקו נעשה מקור שיוכל להיות התחלקות לי\"ס ואף גם זאת הרי כל האורות הנאצלים ע\"י בחי' הקו הזה הרי המה מיוחדי' בעצמות המאציל שהוא א\"ס ממש כמו שלהבת הקשורה בגחלת כמ\"ש בס\"י ונק' ע\"ס בלי מה בלי מהות כלל משום דאיהו וחיוהי חד ממש וכמו יחוד האמיתי שבעצמותו ממש שנק' יחיד לבדו וכמ\"ש אנת הוא חד ולא בחושבן י\"ס כלל אפי' בהעלם להיותו אור הפשוט בתכלית ממש כך גם לאחר שנאצלו ע\"ס ע\"י הקו מתאחדי' ומתכללים בעצמות להיות בבחי' יחוד העצמות ממש (ולא כאחד המנוי שמתאחד מן הפירוד אלא אחד פשוט ממש כמשי\"ת) וא\"כ נמצא שאין הריבוי והתחלקות דמספר ע\"ס דאצילות היפך בחי' האח\"פ דעצמות אור א\"ס כלל אלא הן מיוחדי' בעצמות א\"ס בבחי' אח\"פ ממש כמו קודם שנאצלו ממש בשוה וז\"ש אנת הוא חד ולא בחושבן י\"ס גם עכשיו אחר שהאציל כנ\"ל וד\"ל. ובזה יתורץ קושיות הפילסופים על ההשגחה פרטית הנ\"ל מאחר שגם בעצם ענין ההתחלקות וריבוי דע\"ס מאח\"פ דאור א\"ס אין זה היפך כלל וכלל משום דאם הי' ההתחלקות וריבוי במספר דא\"ס בעצמות דאור א\"ס ב\"ה ממש הי' ראוי לשאול איך ימצא הריבוי מן האח\"פ אבל הרי אין ההתחלקות דע\"ס בעצם האור דא\"ס כלל רק אחר בחי' הצמצום בעצמו ולא נשאר רק הארה דהארה לבד בקו\"ח ואף גם זאת לא שהתחלקות דע\"ס שע\"י הקו\"ח הוא היפך האח\"פ אלא אדרבה הרי המה מיוחדי' בעצמות א\"ס בתכלית עד שנק' ע\"ס בלי מה בלי מהות כלל כנ\"ל וד\"ל:\n(ה) <b>ולהבין</b> כל זה הנה ידוע בענין ע\"ס דאצילות דרך כלל שנק' בזוהר רזא דשמא קדישא שהן רק בחי' שמות לבד והן ד' שמות ע\"ב ס\"ג מ\"ה ב\"ן ע\"ב במילוי יודין בבחי' החכמ' ס\"ג בבינה במילוי ההי\"ן ומ\"ה במילוי אלפין במדות וב\"ן במל' (ושם אהי' בכתר כידוע) וזהו הכולל כל הע\"ס דאצילות מכתר עד המל' כידוע וענין השמות הללו היינו מה שנאצלו הע\"ס ע\"י בחי' אותיות לבד כמו ע\"י אותיות דשם ע\"ב במילוי יודין נאצל אור חכמ' דאצילות וכן ע\"י אותיות דשם ס\"ג במילוי ההי\"ן נאצל אור בינה דאצילות וכה\"ג כל האורות דע\"ס שלזה נק' בכלל רזא דשמא קדישא לבד כמו קריאת שם חכם ע\"י שם ע\"ב הוא שנק' חכים כו' וכמו שא' עבד מאנא וקרא בי' גרמי' חכם כו' ומאנא זאת היא בחי' שם ע\"ב שהוא רק בחי' הארה דהארה לבד לגבי עצמות אור א\"ס הפשוט בתכלית והן מיוחדי' וכלולים"],[2300670098,"בעצמותו בתכלית היחוד והתכללות וזהו הנק' יחודא עילאה בזוהר והן כוונת שבפסו' ראשון דק\"ש באמרו הוי\"ה אחד שהן ע\"ס שכלולים באח\"פ כידוע וד\"ל. ולהבין ביאור כל זה הנה ידוע ע\"ד דוגמא בנפש האדם שמלובשת באברי הגוף שאנו רואים שכחות הנפש שבאים בהרכבה גשמי' באברי' שמקבלים חיות מן הנפש הרי הן בבחי' ריחוק הערך מאד מעצם הנפש הרוחני' שמושללת לגמרי מכל תואר גשם כזה שנמצא באברי' בגוף כמו כח הראי' בכלי חומר העין שחומר העין הוא מקבל כח הראי' ונעשה חומר לצורה ממש בקרוב הערך שהוא לראות ולתפוש בכלי העין דבר גשמי בכח הראי' שבה המורכבת בה בהגשמה זו וכן כלי האוזן מקבל כח השמיעה הרוחנית שבאה באזן בהרכבה גשמי' לשמוע קול גשמי ממש וכה\"ג בכל כחות חיצוני' ופנימי' שמורכבים באברי הגוף כידוע והנה ודאי א\"א לומר שבנפש עצמה כמו שהיא ממש טרם בואה בהרכבת אלה יש בה ג\"כ מהות כח ראי' עין כזה ומהות כח שמיע' אזן הגשמי' שא\"א לומר שהנפש תראה ראי' גשמי' לתפוס דבר גשמי וא\"א לומר שתשמע שמיעה גשמי' לקול גשמי אם היא מושללת מתוארי' גשמיים כאלה ומ\"מ אנו רואים שעיקר סיבת מציאת שנמצאו תוארים הגשמיים הללו בכחות האברי' כראי' ושמיע' גשמיי' אינו אלא מן הנפש עצמה דוקא (וראי' לזה מן התפעלות הנפש עצמה ממאורעות כחות הגופניים כמו בראי' ושמיעה לטוב ורע שהוא עונג וצער בנפש עצמה וכן עונג וצער שבגוף הניכר בדמות שבפנים אם טוב או רע שפניו רעי' או טובים הכל הוא מצד הנפש עצמה אם היא מרת נפש או שמחת הנפש כו' וכן בהתחכמות בכלי המוח הגשמי בא מכח המשכיל ההיולי שבנפש עצמה שנק' נפש השכלית או החסד וטוב הגשמי שבאיש טוב תלוי בעצם נפשו שהיא נפש טובה ולהיפך איש רע כו' והעיקר הוא מה שהנפש תתפעל בעצמה מכל מאורעות כחות אברי הגוף בהרגשה ממש כידוע):\n(ו) <b>והנה</b> להבין זה איך יבא הדבר בדילוג הערך כזה מן הרוחניות שבעצם הנפש בהגשמת אברי הגוף להיות מתאחדים כ\"כ בחומר וצורה עד שיש קשר וחיבור זע\"ז ממש כנ\"ל הנה אנו רואים כמו בענין נפש וגוף ממש גם בחלק הצומח שהצומח הגשמי כעשב הגשמי שנתפס במישוש וראות יצמח מן כח הצומח הרוחני שבארץ וכן יצמח פרי התפוח באילן שגם בזה ודאי א\"א לומר שהתהוות גשם העשב והתפוח בעצם כח הצומח הרוחני כמו שנראים בהגשמה בצמיחתם וכי יתכן לומר שיש מתיקות תפוח גשמי בכח הצומח הרוחני או מרירות בחריפות וחמיצות גשמי וכן בגשם העשבי' למיניהם ישנם במהותם הגשמי בעצם כח הצומח הרוחני שנבדל בערך לגמרי מהגשמה כזו ואעפי\"כ אנו רואים בחוש הטבעי שהעשב צומח מרוחנית דכח הצומח שבארץ דוקא וכן טעמי התפוח הגשמיים ואיך יצא מן הרוחני אל הגשם וצריך לומר שבהכרח יש מבחי' רוחניות דעשב ותפוח בבחי' הרוחניות דכח הצומח מאחר שהוא המצמיח אותן לבא בהגשמה ועכ\"פ הולך ונמשך מרוחניות לגשמיות ויש קשר"],[2300670114,"וחיבור להתהוות מציאות הגשם מן הרוחני ומתאחדי' יחד ממש כו' (וכמ\"ש במ\"א שהוא ע\"י ממוצע דהיינו מגשמיות שברוחניות נמשך רוחניות שבגשמיות כמו מבחי' ההגשמה דכח הצומח הרוחני יצמח צמיחה מן הרוחני אל צמיחה גשמית כצמיחת העשב ותפוח בטעמי' ומינים חלוקים שזהו שנעשה רוחניות לגשמי' הצומח כו' וע\"כ יש להם חיבור וקשר יחד ממש וכמו\"כ בחיות הנפש הרוחניות נתגשמה בבואה להחיות הגוף והוא בדם הוא הנפש ונעשה בחי' רוחניות לגשמיות האברי' והן כמו כח הראי' שבעין שנק' רוחניות שבגשמיות שנמשך מבחי' גשמי' דראי' הרוחנית שבנפש וכן בשמיעה שבאזן ושכל שבמוח ובתנועה והרגשה גשמי' כו') (וכן גם בעונג וצער הרוחני שבנפש הרוחנית באים בדם שבפנים ממש להיות פניו רעים או טובי' וכך הוא כל ענין התפעלות הנפש בעצמה במורגש מכל מקרות האברי' שבהגשמ' הנ\"ל) וכך הוא בענין התהוות כחות הגשמיים כראי' בעין ושמיעה באוזן וטעימה בחיך וריח בחוטם וכה\"ג באברי' הגשמיים דעין ואזן וחיך כו' מרוחניות החיות של כחות הללו עצמן כמו שהן בעצם הנפש ממש עד שיש להן קשר וחיבור והתאחדות יחד שהרי א\"א שיראה אדם בעין אם לא שנמשך לכלי העין ההארה של כח הראי' הגשמי' מן הנפש עצמה בבחי' רוחניות דאור הראי' הכלולה בנפש והרי מתאחדת הראי' הגשמי' בבחי' אור וחיות הרוחנית שלה שבנפש הרוחניות והיו לאחדים ממש עד שא\"א לומר ענין הבדל וחילוק ביניהם כלל (שהרי תתפעל הנפש ממאורע שבכלי העין לטוב ולרע כנ\"ל) כמו שכלי העין החומרי מתאחד מאד עם הצורה דראי' הרוחניות שבה מצד שהעין חומר מוכן לקבל צורת הראי' המאיר בה והיו לאחדי' ממש בלתי הבדל וחילוק ביניהן כלל וככה ממש מתאחדת כח הראי' שבעין ברוחניות האור וחיות שלה שבנפש עצמה כו' וכך הוא באזן שומעת לקול גשמי ומבחין בין טו\"ר הוא שנמשך ובא מעצם הנפש הרוחניות כמו שא' (איוב יב, יא) אזן מלין תבחן כו' כחומ' לצורה דאזן לכח השמיעה הגשמי' וכך הוא בכל כחות של האברי' הרי המה מתאחדי' מאד בעצם הנפש הרוחניות ממש עד שתרגיש הנפש בכאב הציפורן שברגל כו' אעפ\"י שאין ביניהם דמיון וערך כלל כמו שאין ערך כלל לגשם עם הרוחני כנ\"ל וד\"ל:\n(ז) <b>והנה</b> הדוגמא מכל זה יובן למשכיל למעלה בע\"ס דאצילות שנק' אדם העליון דאצילות אעפ\"י שאין לו גוף ולא דמות הגוף כי הרי דברה תור' כלשון בנ\"א למעלה בכינוי תואר אדם וכמ\"ש (יחזקאל א, כו) ועל דמות הכסא דמות כמראה אדם ולא אדם ממש (וכמ\"ש בסוף המאמר הנ\"ל ולאו מכל אינון מדות כלל ונק' ע\"ס בלי מה כנ\"ל) דהיינו בציור אדם באברי' שנק' או\"כ (כמבואר במא' דאליהו שא' גופין תקינת לון כו' ואתקריאו בתקונא דא חסד דרועא ימינא גבורה דרועא שמאלא ת\"ת גופא נו\"ה תרין שוקין כו' ומסיים בסוף דבריו כולא לאחזאה איך מתנהג עלמא אבל לאו דאית לך צדק ידיעא דאיהו דין כו' ולאו מכל אינון"],[2300670130,"מדות כלל) שהרי מצינו בכתובי' כל תוארי אדם למעלה כמו ה' עיניו משוטטות כו' פקח עיניך וראה כו' וירא ה' כי רבה כו' ואמר בזוהר אשכחן ראי' לטב כו' וכן הטה אזנך ושמע וישמע ה' וירח ה' את ריח כו' וכן בכל פרטי תוארי האדם בהילוך וישיבה כאברי האדם הגשמיים כו' וישב ה' כו' (תהלים כט, י) והנה ה' נצב כו' (עמוס ז, ז) וכן הילוך שהתהלך בגן לרוח היום וכה\"ג רבות בכתובי' וידוע שבאמת אין כל בחי' תואר הגשמה למעלה ח\"ו (וכמ\"ש במא' דאליהו אף לאחר שנאצל או\"כ ובך לית דמיון ודיוקנא מכל מה דלגיו ולבר שהן האו\"כ) ועכ\"ז הרי הזכיר בלשון בנ\"א בציור אדם והענין הוא לפי שבאמ' עצמות אור הא\"ס הוא פשוט בתכלית כמ\"ש אנת הוא חד ולא בחושבן י\"ס כלל כנ\"ל ואמנם אחר הצמצום הראשון שנתעלם אור העצמות דא\"ס עצמו ונמשך רק דרך בחי' קו\"ח הוא שנעשה מקור להתחלקות או\"כ דע\"ס דאצילו' כנ\"ל והיינו כמו עד\"מ הנ\"ל מכחות הנפש באברי האדם שהנפש מתצמצמת בעצמותה להיות נמשך מן הרוחניות בשנוי המהות להיות בבחי' אור וחיות לאברי' כמו כח הראי' בעין וכח השמיעה באזן וכמשל התהוות גשם הצומח דעשב ותפוח מן הרוחניות דכח הצומח שבא בדילוג הערך מאד כך נתצמצם עצמות אור א\"ס ע\"י בחי' הקו\"ח להיות נמשך מקור להתחלקות ע\"ס דאצילות כמו אור החכ' דאצילות בכלי המוחין דז\"א כמו שא' חכמה מוחא כו' כמו עד\"מ הנ\"ל בנפש שנמשך כח השכל מרוחניות הנפש בהגשמת השכל שבמוח אעפ\"י שאין דמיון כלל לשכל שבמוח עם כח השכל שבנפש ההיולי שנק' כח המשכיל או נפש השכלית וכה\"ג וכן עד\"ז נתצמצם אא\"ס בקו\"ח זה להאיר ולהמשיך אור הבינה ואור הדעת בג' חללי גלגלתא כו' שהן ג' מוחין אורות בכלים וכן המדות חג\"ת וענפיהן עד דאתקריאו בתקונא דא חסד דרועא ימינא כו' וכן שאר כינויי תוארי אדם כראי' ושמיעה בעין ואזן וכה\"ג הנז' למעל' כמו ה' עיניו משוטטות שהוא בחי' אור הראי' בכלי העין וכמ\"ש היוצר עין הלא יביט כו' (תהלים צד, ט) וכתיב עיניך פקוחות ממש כראי' באדם להשגיח על כל העולמות והברואים וכן א' פקח עיניך כו' וכן בשמיעה שבאזני ה' כמ\"ש הטה אזנך ושמע כו' (מלאכי ג, טז) וכן ויקשב ה' וישמע כו' (שמות ו, ה) וגם אני שמעתי כו' אם צעק יצעק אלי אשמע צעקתו (שם כב, כב) וכן בתפלות שומע תפלת כל פה והכל הוא ע\"י צמצו' הארת הקו להמשיך אורות מצומצמי' ומוגבלים בכלים מכלים שונים כראיה בעין ונק' עין ה' וכן הילוך וישיבה ועמידה כנ\"ל במשל בהתלבשות הנפש בכחות אברי הגוף שאע\"פ שהוא בא בדילוג הערך מאד מ\"מ יש להם קשר וחיבור עם העצמות כך למעלה בי\"ס או\"כ כמ\"ש אפיקת יו\"ד תיקונין וקרית לון י' ספירן כו' אע\"פ שבאים בדילוג הערך ואין להם דמיון לגבי בחי' העצמות דא\"ס כלל מ\"מ יש להם חיבור וקשר יחד שמאיר מעצם החכ' דא\"ס בחכ' המצומצמת בכלי המוחי' דז\"א וכן באור הראיה ושמיעה וכה\"ג כנ\"ל במשל באריכות ויחוד וקשר הזה הוא ע\"י בחי' הקו הזה (כיחוד וקשר הגשם דצמיחת"],[2300670146,"העשב כנ\"ל) ובחי' היחוד הזה הוא בב' אופנים א' שמייחד ומקשר לעצמות אא\"ס להאיר בהן מלמעלה למטה כמשל חיבור עצם הנפש באורות וכחות שבאברים והב' להיפך שמתייחדים ומתכללים כל הע\"ס בעצמות המאציל כשלהבת הקשורה בגחלת כו' ע\"י בחי' הקו הזה שהוא המגביל כל האורות בכלים והוא המעלה ומייחד אותם בעצמות המאציל וכמ\"ש חכים ולא בחכמ' ידיעא עד ולאו מכל אינון מדות כלל וזהו הכונות שבק\"ש בפסוק באיכות היחוד והתכללות דע\"ס בעצמות ע\"י הקו\"ח דוקא כמו שהוא טרם שנעשה מקור לאורות להגבילם בכלים כו' וד\"ל:\n(ח) <b>והנה</b> כל בחי' היחוד וההתכללות הנ\"ל הנז' בזוהר תמיד בשם לשון רזא דמהימנותא או רזא דשמא קדישא הוא יחוד עליון דע\"ס שהן ד' שמות דע\"ב ס\"ג מ\"ה וב\"ן שהן חו\"ב ומדות ודיבור וזהו הנק' יחודא עילאה שנכללים הע\"ס ע\"י הקו בעצמות א\"ס בתכלית היחוד עד שא' ע\"ס בלי מה בלי מהות כלל כו' וכמובן מתוך משל הנ\"ל בכחות הנפש שבאברי' שכלולים ומתאחדי' בעצמות הנפש ממש כו' והנה כמו\"כ ממש יובן ג\"כ בבחי' יחוד' תתאה שהוא בחי' התלבשות דבחי' מל' דאצילות בבי\"ע להחיות רוח שפלים מאין ליש ממש כידוע שנק' אדם דבריאה ג\"כ בציור או\"כ בע\"ס דחב\"ד חג\"ת ונה\"י כו' כמו בחי' אדם העליון דאצילות הנ\"ל (וכמ\"ש בצלמנו כדמותנו צלם בדכורא ודמות בנוק' ונק' המל' בבריא' בשם דמות כבוד הוי\"ה דז\"א דאצילות כידוע) אך ההפרש הוא שבבחי' אדם דאצילות כל מיני כינויי תוארי אדם הוא בבחי' זכר (כאדה\"ר שיצר ה' אותו בצלם אלקי' ממש ואח\"כ בנה ממנו בנין חוה כו') וכמו עיני ה' המה משוטטי' לשון דכר ובבחי' המל' בבריאה א' ה' עיניו משוטטות לשון נוק' וכה\"ג לפעמים א' ימי עולם ולפעמים א' ימות עולם שהוא ענין ההפרש בין מדות דז\"א דאצילות למדות דנוק' כידוע וד\"ל וביאור הענין ידוע שכל ענין דע\"ס דאצילות הנ\"ל הכל הוא עדיין בבחי' עצמות האצילות בבחי' חו\"ב ומדות וגם שארי כינויים דראי' ושמיעה שהכל הוא בבחי' או\"כ דאצילות שמיוחדי' בעצמות המאציל דאיהו וחיוהי חד ממש אבל בחי' המל' דאצילות שיורד למטה בבי\"ע הוא ענין ירידת האור למטה להיות התהוות הבריאה מאין ליש ממש בבחי' נפרד כמלאכים ונשמות דבי\"ע (שנק' חוה כי היא היתה אם כל חי) והוא בחי' שם ב\"ן דמל' דאצילות שנק' דמות כבוד הוי\"ה דז\"א כאותיות החותם שנחקקים בשעוה שזהו אתוון אתגליפו וכידוע וגם בבחי' אור זה שנק' הארה דהארה לגבי עצם אור האצילות יש ע\"ס באו\"כ ולבושים כו' והן ע\"ס דבריאה בכלל והכלים מגבילים ומלבישים את האורות כמו האברים באדם ככלי העין וכלי האזן וכלי המוח כנ\"ל רק שבבחי' זו דמל' בבריאה הכלים הן המגבילים האור ממש והן המלאכי' שנק' אברי' דשכינתא כמ\"ש בזוהר שהן בע\"ג ממש וכמו מלאכי' שנק' מארי דעיינין ויש מלאכי' שנקראו מארי דאודנין והענין הוא שהן כחות ממוצעין בע\"ג ממש ונמשכו בבחי' הגבלה ממש בכלי"],[2300670162,"העין בראי' מוגבלת ומצומצמת והן המלאכים שנק' מארי דאשגחותא שהן כחות אלקים שנק' בעלי ההשגחה האלקי' שעל ידן יתפשט אור ההשגחה האלקי' הפרטי' על כל נברא ונברא בפרט דוקא וז\"ש ה' עיניו משוטטות לשון נוקבא והוא מ\"ש היוצר עין הלא יביט פי' היוצר עין מלאכים שנק' עיינין בבחי' ההשגחה הפרטית הנ\"ל הלא יביט (שהוא כמו כח הראיה שבעצם שמושלל מן הגבלה דכלי העין כו' וכענין צופה ומביט עד סוף בסקיר' א' שנק' ידיעה כללית טרם שיוגבל האור בכלי ההשגחה בפרט בעולמות המוגבלים) וכמו וירא ה' כי רבה כו' (בראשית ו, ה) וכתיב עיניך פקוחות על כל דרכי בנ\"א עד שיש מלאך א' שמשגיח על אדם א' בפרט וכמו שא' דע מה למעלה ממך עין רואה ואוזן שומעת וכל מעשיך בספר נכתבים כו' וכה\"ג במלאכים שנק' מארי דאודנין שמתצמצם כח אלקי בריבוי ממוצעים עד שיש מלאך מיוחד שישמע לקול תפלה פרטי' או לצעקת עני וכמ\"ש אז נדברו כו' ויקשב ה' וישמע כו' (מלאכי ג, טז) וכה\"ג (אבל בכינוי תוארי אדם דאצילות אין זה בבחי' גבול ככלים דמלאכים דבריאה ועכ\"ז נק' מלאכי' דז\"א דאצילות שהן עיני ה' המה משוטטים לשון דכר כו' וכן כשאו' עיניך פקוחות או פקח עיניך או הטה אלקי אזנך ושמע כו' שזהו כמו שהוא בבחי' האצי' ממש טרם שבא לכלל השתלשלות מאצילות לבריאה עדיין כמ\"ש במ\"א וד\"ל):\n(ט) <b>ובכל</b> זה יובן במה שמצינו בכמה כתובים בתורה וכן גם בנביאים שהמלאכים עליונים דבריאה או דיצירה ועשיה אע\"פ שהן בבחי' גבול ותכלית יכולים לומר על עצמן בשם ה' ממש כאלו הוא בעצמו שם ה' המדבר או המשפיע שפע זו מכח עצמו ממש כמו שמצינו במלאכים שהיו אצל אברהם שהלכו בשליחות להפוך את סדום וא' מהם אמר לו שוב אשוב אליך כעת חיה והנה בן לשרה אשתך כו' וכן במלאך ה' מן השמים שאמר לאברהם אל תשלח ידך אל הנער ואל תעש לו מאומה כי עתה ידעתי כי ירא אלקים אתה ולא חשכת את בנך את יחידך ממני הרי א' שוב אשוב אליך דמשמע שבו הדבר תלוי והוא יתן לשרה בן וכן כשא' עתה ידעתי כו' ולא חשכת כו' ממני כאלו הוא שם הוי\"ה בעצמו ממש וזה פלא גדול אחר שהמלאך נק' שליח לבד לעשות רצון ה' אדון כל הארץ איך יאמר על עצמו כאלו הוא האומר וגוזר ומקיים מכח עצמו ומה גם מ\"ש ממני כו' וכן בפעם ב' שא' בי נשבעתי נאם ה' ממש כו' וכן במלאך שא' ללוט הנה נשאתי פניך גם לדבר הזה איך אמר על עצמו שהוא ישא פנים לבקשתו כו' (וכאשר הוד' בעצמו לא אוכל לעשו' דבר כו') וכן ביעקב שא' (בראשי' מח, טז) המלאך הגואל אותי כו' יברך את הנערי' כו' איך יש ביכולת המלאך לברך מצד עצמו כו' וכן במלאך ה' שאמר להגר הרבה ארבה את זרעך וכה\"ג רבים בכתובים. אך התירוץ לכל זה הוא מטעם הנ\"ל דמלאכים דבי\"ע נק' אברי' דשכינתא כו' כי הנה אדרבה היא הנותנת משום דמלאכים נק' שלוחים שהן בתכלית ביטול במציאותם לגבי אור האלקי שבהם ע\"כ"],[2300670178,"או' בשם ה' ממש כאלו הוא הנותן והמשפיע מאחר שאינם בבחי' מציאות ומהות בפ\"ע כלל ואין לשון זה ענין פירוד כלל כמו כשאו' שוב אשוב או עתה ידעתי כו' זהו רוח האלקי' המדבר בו ממש ואינם דברי עצמו כלל וכן כל מה שאמר המלאך בלשון עצמו כמו עתה ידעתי כו' נשאתי פניך כו' וכמו הרבה ארבה כו' הכל הוא כח האלקי המלובש בו ואו' ידעתי ממש וכה\"ג (ודוגמא לדבר זה הוא דבר ה' בפי הנביא דרוח ה' הוא המדבר בו וכל דבריו אינם דברי עצמו כלל כי שליח הוא ואינו אלא כלי להכיל דבר ה' בפיו כו' ועכ\"ז אינו כמו מלאך ממש שהרי או' בתחלה כה אמר ה' צבאות כו' והמלאך אינו מזכיר כלל שהוא שליח כמו שאו' שוב אשוב או עתה ידעתי כו' לפי שהמלאכים הן בחי' כלים ממש לאור האלקי בלתי נראה ליש ודבר בפ\"ע כלל ויש מלאכי' שהן מבחי' כלים חיצונים דמל' ויש שהן מבחי' כלים פנימי' יותר שנק' אברין דשכינתא כמלאכים שנק' מארי דעיינין ומארי דאודנין כנ\"ל ועד\"מ העין והאזן שהן חומר לצורה ומתאחדים כא' ואין להבדיל ביניהם כלל וכלל והרי כאשר יראה האדם בעיניו אע\"פ שעיקר הראי' הוא כח הראי' הרוחנית שבעין עכ\"ז יאמר עיני ראו או אזני שמעו כו' אע\"פ שהעין והאזן אינם אלא חומר מוכן לקבל הצורה הרוחניות דראיה ושמיעה אמנם להיותה מיוחדת ומתכללת בצורה הרוחנית יאמר עיני ראו ואזני שמעו וכן בהילוך ברגלי הלכתי ובידי עשיתי וכה\"ג ומובן מזה ג\"כ להיפוך שכאשר יאמר אדם ראיתי או שמעתי והלכתי וכה\"ג אע\"פ שע\"י כלי העין ראה וע\"י האזן שמע והרגל הוא ההולך עכ\"ז יאמר ראיתי ולא יזכיר לומר ראיתי בעיני ושמעתי באזני כו' לפי שהכלים דעין ואזן מתאחדים בצורה דראיה ושמיעה עד שלא יתכן לכנות שם דבר בפ\"ע לעין ואזן ויד ורגל וכה\"ג דמסתמא בראיה הרוחנית ראה בכלי עינו כו' כי נכללים האברי' בפנימיות חיות נפש האדם הרואה ושומע כו' ואין להבדיל ביניהם כלל וכך הן המלאכים שנק' עיינין ואודנין וכמ\"ש היוצר עין שהוא הכלי הממוצע שנק' עיני ה' הלא יביט ממש שאין להבדיל ביניהן כלל מצד ביטול הכלי בתכלית אל האור וכן אמר הנוטע אזן שהן המלאכים שנק' מארי דאודנין הלא ישמע כו' וכן להיפך כשאו' וירא ה' וישמע כו' זהו ע\"י המלאכים שנק' עיני ה' ואזני ה' כו' כמו ה' עיניו משוטטות בכל הארץ שנק' מארי דאשגחותא כנ\"ל שאינן בבחי' יש ודבר במציאות בפ\"ע כלל ואינן נבדלים מפנימית כח האלקי שבהן כלל אלא הן נכללים בכח האלקי ממש כחומר המוכן לקבל הצורה כו' שהוא כח האלקי המאיר בהן בתמידות ומצד גודל התאחדות שבהן בכח האלקי בתכלית ע\"כ יוכל המלאך לומר בלשון עצמו כנ\"ל ואין זה פירוד כלל אדרבה מחמת גודל עוצם הביטול וההתכללות כחומר בצורה שאין להבדיל ביניהם כלל משא\"כ אם היו המלאכים בבחי' יש ודבר בפ\"ע נבדל מכח האלקי הי' הדיבור בלשון עצמו כנ\"ל נק' בחי' פירוד אבל מאחר שהן בחי' כלים ואברים דשכינתא כנ\"ל הוא הטעם שאו' בלשון עצמו כמו ממני"],[2300670193,"ושוב אשוב כו' וכה\"ג כנ\"ל וד\"ל):\n(י) <b>ויש</b> מלאכים שהן רק בחי' מרכבה לבד כמו (יחזקאל א, י) פני ארי' פני שור ונק' חיות הקודש וכן האופני' וגם השרפים שהן בריה בפ\"ע בציור קומה כמו (ישעי' ו, ב. ג) בשתים יכסה פניו כו' ואמר קדוש כו' שזה לא יתכן כ\"א בהיותם בבחי' בריאה נבדלת בפ\"ע עכ\"פ ואף גם במלאכים דבריאה כמט\"ט שרו ש\"ע שהוא מבחי' כלים דו\"ק דבריאה שא' (תהלים לז, כה) נער הייתי גם זקנתי כו' (חגיגה טו, א) וא' אפקוה למט\"ט כו' וכן סנדל' ביצירה שקושר כתרים לקונו כו' וכ\"ש מלאכים אשר נק' שלוחי השפע למטה ממש כמו המלאכים שנשלחו להפוך סדום לדין ולחסד לבשורת שרה שהן מיכאל וגבריאל ורפאל וכה\"ג שנק' עומדים מוימ\"ב וכן בכל ר\"ה שאו' ויבאו בני אלקים להתיצב על הוי\"ה שהן בני רברבניא ע' שרים העליונים דבריאה ויצירה ועשיה ויש שנק' שר צבא ה' (יהושע ה, יד) דיש מחנה אלקי' וכמו ד' מחנות שכינה ועד\"ז ד' מחנות דאצי' בשם הוי\"ה ונקרא שר צבא הוי\"ה וכן מה שלפעמים או' מלאך האלקים וכמו ויסע מלאך האלקים ויש שנק' מלאך הוי\"ה בבחי' האצי' ויש מלאכים שהן מחיצוניות הכלים ביותר כמ\"ש בזוהר בענין רתיכין ומשיריין כו' ויש שנק' סוסים כמו בנבואת זכרי' (א, ח) או עננים למרכב וכמו עד\"מ כלים החיצונים שפועלים בהן פעולת מלאכה כגרזן ביד כו'. ובדרך כלל כל המלאכים דבי\"ע עד המזלות שבגלגלים כולן הן בבחי' הביטול בתכלית לאלקות ולא יוכלו להיות בבחי' פירוד ליש בפ\"ע כלל וכלל כי הן הכל כלים מכלים שונים לרצון והשגחה האלקי' שפועל על ידם כמו מסדר את הכוכבים כו' כרצונו דוקא וכמ\"ש (דניאל ד, לב) וכמצביה עבד בחיל שמיא כו' וד\"ל:\n(יא) <b>והנה</b> אחר כל הנ\"ל בביאור ענין יח\"ע דאצי' באו\"כ ובחי' יח\"ת דמל' דאצילות בבי\"ע שהן רק בחי' כלים מכלים שונים המגבילים את אור האלקי בריבוי השתלשלות עו\"ע ועכ\"ז כולם מתאחדים בתכלית באור האלקי כנ\"ל הרי מכל זה יובן היטב התירוץ על הקושיא דפילסופים הנ\"ל בענין התהוות הריבוי והתחלקות מאח\"פ כו' וענין ההשגחה האלקית הפרטית מאח\"פ על הריבוי כו' כמו עיניך פקוחות על כל כו' ומבין אל כל מעשיהם שכל זה אינו ירידת אור האחדות הפשוטה לבא בהתחלקות וריבוי וגבול ומדה כו' מאחר שמבואר למעלה בענין הצמצום הראשון דקו\"ח וכן בצמצום האחרון יותר מאצילות לבי\"ע כו' ועכ\"ז הרי יש קשר וחיבור ומתאחדים כולם באחדות פשוטה ממש כמו קודם שהאציל וברא ויצר ועשה ממש כהתאחדות אברים בנפש כו' א\"כ אין הריבוי והתחלקות היפך לבחי' האחדות כלל רק מה שבא ההתחלקות וריבוי היינו ענין ריבוי הממוצעים שהן בחי' כלים רבים שהן בחי' אמצעים בין עצם אור האלקי דע\"ס דאבי\"ע לנבראים ועולמות שעי\"ז יתהוו' הריבוי והתחלקות מציאות כל הברואים והוא ג\"כ ענין התחלקות ההשגחה הפרטית בכל העולמות עד עוה\"ז השפל גם בחלק הצומח וחי כמלאכים דנק' מארי דעיינין שהן רק כלים בלבד להשגיח על כל פרטי הנבראים שבארץ וכן עד\"ז כל הממוצעים שבין אלקות לנבראים בירידת"],[2300670208,"האור עוד בהשתלשלות מעילה לעלול עד צבא השמים שבגלגל המזלות שמשפיעי' רוחניות בגשמיות דדצח\"מ וארמ\"ע הגשמיי' כידוע שגם אין עשב למטה שאין לו מזל כו' והמזלות מקבלי' משמרי האופנים ואופנים מחיות כו' וכן עד\"ז גבוה מעל גבוה שהאופנים וחיות דעשי' ויצירה מקבלים ממלאכים דבריאה בדרך קבלת עלול מהעילה שלו וכולם אינם רק בבחי' כלים דע\"ס דבי\"ע וכן מבריאה לאצילות (כמו מט\"ט דבריאה מקבל מחיצוניות הכלים דמל' דאצילות בבריאה ולמעלה יותר מבחי' ו\"ק דז\"א דאצילות שנא' בו הנה אנכי שולח מלאך לפניך כו' כי שמי בקרבו כו') ועד\"ז הן ריבוי והתחלקות דכלים לאורות דע\"ס דאצילות שמיוחדים בעצמות המאציל ממש כנ\"ל במשל כחות הנפש באברי האדם בראי' ושמיעה כו':\n(יב) <b>ולפ\"ז</b> מאחר שכל זה הוא בחי' התלבשות העליון בתחתון ממאציל לאצילות ומאצילות לבריאה ובריאה ביצירה ויצירה בעשיה והיו לאחדים ממש א\"כ הרי יובן מזה עכ\"פ שיוכל להיות בחי' השגחה האלקי' הפרטית מעצמות המאציל ממש גם בסוף כל המדרגות דעשיה דהיינו עד חיצוניות דחיצוניות הכלים דמל' דמל' דעשיה שנתהוו על הברואים דעוה\"ז השפל בפ\"מ שיהיה בהם השגחה פרטית כל צבא השמים ועל הארץ וכל אשר בה ועל כל מעשה בנ\"א בפרט כמו שא' (תהלים לז, כג) מה' מצעדי גבר כו' עד שא' (חולין ז, ב) אין אדם נוקף אצבעו מלמטה אא\"כ מכריזין עליו מלמעלה פי' ענין הכרוז הוא הצווי ממלאכים דעשי' שמקבלים מחיצוניות דמל' דעשיה אדון כל הארץ שיורד ע\"י בחי' ממוצעי' רבים עד שבא למטה ממש לענוש האדם בדין שיכשל בהילוכו ברגליו במקום סכנה עד גם עונש קל שינקף אצבעו כו' כמ\"ש מה' מצעדי גבר כו' הכל מכריזין עליו בתחלה וכן בהפסד בממונו שיומשך בו מחשבה ועצה לרעתו דוקא וכמו כן ברוחניות לעוררו לדבר רע ומזיק לנפשו ברוחניות כמו ריבוי המזון שנמשך ממלאך רע כידוע שיש מלאכים דעשי' שהן מעורבי' טו\"ר וכן להיפוך בהשגחה לטובה יבא לאדם מחשבה טובה להציל נפשו מכל דבר רע המזיק לנפשו וכן בגשמיות שינצל מן הסכנה שלא ילך למקום רע כו' שז\"ש מה' מצעדי גבר כו' (רק שעכ\"ז תלוי בבחירה שבדרך שאדם רוצה לילך מוליכי' אותו (מכות י, ב) כמ\"ש במ\"א בענין הידיעה ובחירה כו') וכן על כל מעשה בנ\"א נמשך ע\"י הממוצעי' להשפיל ולהרים אם יצליח אם להיפך הכל בהשגחה פרטית שאדם נידון בכל יום ויום (ר\"ה טז, א) וכן משגיח על כל יושבי הארץ כמ\"ש המבין כו' וגם על הנהגו' שפע הגשמיות בצומח וחי נמשך הכל ע\"י הממוצעים כמו שא' חלקה אחת תמטר כו' (עמוס ד, ז) לפי שיצוה על העננים שילכו ממקום זה למקום אחר כמ\"ש בגמ' (תענית פ\"ג) וכמ\"ש מעלה נשיאים מקצה הארץ כו' ובדרך כלל כל שינוי הנהגות שפע בדצח\"ם לטוב או להיפך הכל בא בהשגחה האלקית הפרטית על כל מלכי האדמה באדמה כו' עד גם בדומם וצומח כמו כי ההרים ימושו והוא שמשפיל מזל של ההר כו' וא\"כ הרי מובן ממילא שכל מעשה בנ\"א אם לטוב או לרע הכל עולה למעלה ע\"י ריבוי הממוצעים דמלאכי' מסוף עולם"],[2300670223,"העשיה עד עצמות אור א\"ס שבאצילות כמו כאשר רבה רעת האדם וכל יצר מחשבות לבו רק רע ולא טוב יעלה אותו מעשה הרע בפ\"מ ואותיות המח' הרעה למע' בשרשו בכחות הרוחניים דמלאכים דעשיה שהן הכלים היותר חיצונים כו' והן מעלים אותו למלאכים העליונים מהם שמשם מקבלים בדרך עו\"ע כנ\"ל וגבוה מעל גבוה כו' כנ\"ל מעשיה ליצירה ומיצירה לבריאה ומבריאה לאצילות עד שיעלה במקור הראשון דאצילות כמו וירא ה' כי רבה רעת האדם כו' ראיה זאת בפנימית אור הראי' דאדם דאצילו' שנק' הוי\"ה וכן בשמיע' קול דמי אחיך צועקים אלי כו' וכן כי אם צעק יצעק כו' אשמע כו' וכן כאן הכצעקתה הבאה אלי ממש כו' שהן כל חטאת מעשה סדום שעלו למעלה ממש (וכמ\"ש במ\"א בפי' שטרי חובותינו שמכל עון וחטא נעשה צירופי אותיות רעים וחטאים עד רום המעלות עד שנכתב בספר ונק' שטרי כו') כי כל זה הוא ע\"י בחי' כלים דאורות דאדם דאצילות שמתלבשים במל' דאצי' והמל' מתלבשת בכלים דע\"ס דבריאה כמו ה' עיניו משוטטות כנ\"ל ובריאה ביצירה ויצירה בעשיה כנ\"ל וד\"ל (ודוגמא לדבר במעשה דשרה אצל אבימלך שא' לו (בראשית כ, ו) גם אנכי ידעתי כי בתם לבבך כו' ע\"כ לא נתתיך לנגוע אליה כו' שנשמר מלמעלה מעשות חטא זה וכמ\"ש ואחשוך גם אנכי אותך מחטו לי והוא ע\"י שלוחי' ממוצעים וכמו שא' שבא מלאך והדפו כו' וא' בזוהר בפי' מחטו חסר א' כמחט כו' שכל עון וחטא עושה פגם למעלה בכלים דע\"ס דמל' דעשי' וכמו ענין שא' (חגיגה טז, א) כאלו דוחק רגלי השכינה וכה\"ג (אבל באורות דע\"ס אין זה פגם כמו שא' (איוב לה, ו) ורבו פשעיך מה תעשה לו כו' ולזה א' ולו נתכנו עלילות ולא נתכנו כו' וכן בכל צרתם לא צר ולו צר כו' ושניהם אמת משום דמסט' דשכינה נא' (דברים ד, טו) לא ראיתם כל תמונה כו' ואין הפגם רק בבחי' הכלים וכמו ענין הפושעים בי (ישעיה סו, כד) בגופא דמלכא כו') וכן במעשה הטוב דבנ\"א עולה הכל למעלה מתחתון לעליון וכמו שומע תפלת כל פה שעולה למעלה ע\"י הממוצעי' הרבים דמלאכים מעשיה ליצירה כו' עד העצמות ממש ואפי' מח' טובה מצרפה למעשה כו' ומעורר למעלה ירידת אור חסד עליון או רחמים העליונים שיורד למטה מטה ע\"י הממוצעי' עד נותן לחם לכ\"ב כו' וכמו כי שמע אלקי' אל קול הנער באשר הוא שם כו' וכה\"ג) וגם הדיבור הטוב עולה למעלה כקול תורה ותפלה ואפי' הרהור תשובה בעלמא (וכמו אז נדברו יראי ה' כו' ויקשב ה' וישמע כו') ונמצא מובן עכ\"פ שבאמצעות ענין ריבוי הכלים ולבושי' דמלאכים שיורד מעילה לעלול בג' עולמות עד עוה\"ז יש קשר וחיבור מלמעלה למטה עד שהוא ית' יודע את הכל ומשגיח על הכל על כל פרטי חלקי המדרגות שבכל העולמות דאבי\"ע מראש כל המדרגות עד סוף המדרגה היותר תחתונה שבבחי' דומם שבעשי' משום שאין זה בבחי' פירוד כלל מן אח\"פ שלפני האצילות לפי שע\"י התלבשות האורות בכלים ולבושים דאבי\"ע הרי מתאחדי' כולם בעצמות (וכמאמר וגם כל היצור לא נכחד כו' ולכך יודע תעלומות סתרי כל חי ואין דבר נעלם מאתו כו' כידוע):"],[2300670238,"(יג) <b>ושרש</b> הענין הוא מטעם הנ\"ל בענין אל דעות ה' כו' שסובל ב' הדעות דד\"ע וד\"ת שהוא ענין א' עם מ\"ש הרמב\"ם דבידיעת עצמו יודע את כל הנבראים כנ\"ל ואעפ\"י שידיעת עצמו הוא בחי' אח\"פ אין הכוונה על עצמות אורו הפשוט בתכלית שזה בא בצמצום והעלם בעצמו כנ\"ל בענין הצמצום הראשון שלפני הקו\"ח כו' שמצד זה בא האור ושפע הנמשכת מן העצמות ע\"י הקו הזה במספר יו\"ד ובגבול דכלים כו' אלא הכוונה הוא על ההמשכה הכללית שנמשך מאור העצמות בקו זה שנתחלק אח\"כ בריבוי או\"כ כו' (שזהו הנק' בחי' ד\"ע שנק' ידיעה כללית או מח' א' שצופה ומביט מראש עד סוף הכל בבת א' שגם זה נק' ידיעת עצמו שיודע בה כל ההשתלשלות בדרך פרט שנק' ד\"ת ואין ידיעה זאת נק' ידיעה שחוץ ממנו אלא ידיעת עצמו דוקא אעפ\"י שאין זה עצם אורו כנ\"ל מאחר שכל ההשתלשלות דקו\"ח בד' עולמות דאבי\"ע אינם נבדלים מן העצמות אלא מתאחדי' בעצמות אא\"ס שבקו הזה כנ\"ל א\"כ אין הידיעה פרטית נבדלת כלל מידיעה הכללית אלא מתאחדת הידיעה פרטית בידיעה הכללית הנ\"ל והיו לאחדי' ממש בלתי הבדל כלל ביניהן כמו שא\"א להבדיל הפרט מן הכלל מאחר שהפרט הוא הכלל הכוללו יחד כו' ועד\"מ אדם שיודע א\"ע שבידיעה זו יודע ממילא כל פרטי כחות אבריו בידיעת עצמו בסקירה א' הרי מה שיודע א\"ע הוא כללית ההמשכה של הנפש מהעלם לגלוי מראש לסוף) והוא כמו מה שמרגיש א\"ע מראשו לרגלו בבת א' ממש ואעפ\"י שגם המשכה כללית זו הוא עצם אור פשוט וגם זה בא אחר העלם אור עצם הנפש ממש (שזהו אינו רק בחי' גשמיות שברוחניות עצם הנפש כנ\"ל כמו גשמיות שבכח הצומח כו') וכחות האברי' רבי' הם אבל להיותם מתאחדי' ומתכללים בעצם אור כללי זה א\"כ מתאחדת הידיעה פרטית בידיעה כללית זו וזהו שבידיעת עצמו יודע ידיעה פרטי' ולא בידיעה שחוץ ממנו כאדם שיודע בכלל כל פרטי מעשה הבנין או כדור הארץ שנק' חוץ ממנו אבל פרטי כחות אברי' נכללים בידיעה העצמות אעפ\"י שאינו אור עצמי ממש כמו שהוא כי הרי גם מה שבא אור הנפש באברים אין בזה שינוי כלל בעצם הנפש כנ\"ל וד\"ל:\n(יד) <b>וכך</b> הוא ממש ענין אל דעות ה' כו' שע\"ז א' איהו תפיס בכ\"ע ולמדת\"ב והוא מקומו ש\"ע כו' דידיעה כללית דמח' א' הנ\"ל זהו מ\"ש איהו תפיס בכ\"ע ולמת\"ב מטעם בחי' צמצום העצמות ע\"כ גם לאחר שהאציל וברא כו' הוא כמו קודם שהאציל וברא ממש כנ\"ל ולפ\"ז ב' הדיעות כלל ופרט שוין ממש ואין הפרש כלל ביניהן וא\"כ יתכן לומר גם בידיעת עצמו ממש שיודע בה הכלל עם הפרט דד\"ע וד\"ת כא' לפי שהוא למעלה משניהם ואין הצמצום הראשון שינוי כלל לגבי עצמותו ממש עד שגם עכשיו אחר ההשתלשלות דקו\"ח אמר אנת הוא חד באח\"פ ממש ולא בחושבן י\"ס כלל אפי' בהעלם העצמות כנ\"ל וד\"ל:\n<b>וזהו</b> ארדה נא ואראה הכצעקתה הבאה אלי עשו כו'. פי' הכצעקתה הבאה אלי יובן ע\"ד הפשוט דקאי על מ\"ש"],[2300670253,"תחלה זעקת סדום ועמורה כי רבה כו' דהיינו מפני שכל מעשיהם הרעי' וחטאים מאד עלה הכל למעלה מעלה ממש עד כי באה אלי ממש והוא מובן עפ\"י כל הנ\"ל בענין ריבוי התחלקות הכלים ולבושים מעולם העליון לעולם התחתון מאצי' לבריאה ומבריאה ליציר' ומיציר' לעשי' עד בחי' הכלי' ולבושי' החיצוני' דמל' דמל' דעשי' בע\"ש דנוגה דעשי' כו' שמתאחדים הכל כא' בין מלמעלה למטה בין מלמטה למעלה כנ\"ל בענין ההשגחה הפרטי' על כל מעשה בנ\"א לטוב ולרע כו' שכל מעשה בנ\"א למטה יעלה הכל למעלה מעלה ע\"י ריבוי הממוצעי' דמלאכים דבי\"ע שמקבלים זה מזה כו' עד שיכול לעלות מעשה האדם בגופו הגשמי ומחשבותיו מסוף עולם העשי' עד עצמות אור א\"ס ב\"ה שבאצילות כו' וגם כאן בזעקת סדום כו' הרי כל חטאתם עלה תחלה למעלה בשרשם במזלות ומלאכי' הרוחנים שמקבלים מחיצוניות הכלים דמל' דעשי' והן מעלים אותן עוד למעלה מהם למלאכי' דיצירה שמקבלים מהם בדרך עו\"ע כנ\"ל ורק עד\"ז הולך ועולה מיצירה לבריאה ומבריאה לאצילות והוא בבחי' מל' דאצילות שהוא בחי' מקור חיות כללי לכל הג' עולמות דבי\"ע כידוע והוא שם אדני אדון כל הארץ או שופט כל הארץ בכלל והוא אדני אותיות דינא בחי' דינא דמלכותא כו' שע\"ז אמרו וה' הוא ובית דינו כידוע וז\"ש בזוהר בפי' הכצעקתה לשון נוק' שהוא צעקתה של מדה\"ד והוא הכוונה על בחי' המל' שנק' בשם ב\"ד של מעלה ששופט כל הארץ בדין ומשפט על כל הברואים שאין מלך בלא עם כו' וידוע דלגבי בחי' עצמות האורות העליונים דאצילות שבאו\"א וז\"א אינו אלא בחי' מקבל לבד (כידוע בענין אמת ואמונה כל זאת כו' דמה שהוא בבחי' מקבל באצילו' נעשה ראש ומקור להשפיע לבי\"ע כו') וז\"ש בזהר דדא הוא גזרת דינא דתבעא על עלמא כו' שהוא בחי' הגבורות ודינין שבבחי' המל' שעולה הכל למעלה באצילות לפי העלאת מעשה התחתונים שבבי\"ע כו' וכמ\"ש בזוהר בפ' זו במ\"ש הבאה אלי דא הוא רזא כמו בערב היא באה ובבוקר היא שבה ודא הוא הבאה אלי כגוונא דא קץ כל בשר בא לפני כו' דר\"ל שבלילה עולה המל' בבחי' או\"ח שהוא בבחי' הגבורות ודינין ובבוקר היא שבה בבחי' ירידה דאו\"י בבחינת החסדים להאיר בגעה\"ע וגעה\"ת שז\"ש אל בית הנשים שני כו' לפי שכל בחינת העלאת מ\"ן דמלאכי' ונשמות דבי\"ע שנכללים ועולים עם בחי' המל' דוקא שנק' פתח ושער להוי\"ה דאצי' וכמ\"ש בזוהר ע\"פ (בראשית כט, ט) ורחל באה עם הצאן אשר לאביה כי רועה היא כו' שהוא בחי' המל' שעולה למעלה עם כל העולמות שנק' רועה עליהם כו' ונק' ג\"כ רחל עקרת הבית כו' ולפי שהכל עולים ע\"י בחי' המל' דאצילות בכלל ע\"כ לפעמי' עולה למעלה באצילות בבחי' הדינין וגבורות ולפעמים עולה בבחי' החסדי' לפי שאין העלאה זאת רק לפי אופן העלאת מעשה התחתוני' ע\"י הממוצעי' הרבים כנ\"ל שהוא ע\"י המלאכי' דבי\"ע כנ\"ל וז\"ש בזוהר ע\"פ אבן ספיר דמות כסא דעלמא עילאה שהוא בחי' המל' כספיר זה דמתחז' בגוונא סומקא וגוונא חוורא כו' לפי אופן העלאת עלמא תתאה אם מגבורו' או מחסד כו' (וע\"כ א' ואל יבא בכל עת אל הקדש דהאי"],[2300670268,"עת כלול הוא מחו\"ג כו' לפעמי' עולה בבחי' הדין נא' עת לחשות כו' ולפעמי' עולה בבחי' החסדי' נא' עת לדבר או עת לעשות לה' כו' ולזאת לא בכל עת יבא אל הקודש כו' וד\"ל) וז\"ש בזוהר הבאה אלי תדיר משום דעליית המל' תמיד הוא בכל יום ונק' עולת תמיד כו' (וכמ\"ש (ויקרא ו, ו) אש תמיד תוקד על המזבח שהן בחי' ה\"ג דמל' שעולה תמיד למעלה שע\"ז א' (תהלים פג, ב) אלקי' אל דמי לך כו' דנה\"א קארי תדיר לנה\"ח דז\"א דאצילות ולא שכיך לעלמי' וז\"ש למען יזמרך כבוד ולא ידום כו' וכמ\"ש במ\"א):\n(טו) <b>ועפ\"ז</b> יובן גם כאן במ\"ש הכצעקתה דדא הוא גז\"ד דתבעא על עלמא כו' שהוא עליית המל' בבחי' הדינים הקשי' שעולה ממעשה התחתונים וזהו שא' בזוהר שזהו כמו קץ כל בשר בא לפני שהוא הקטרוג היותר קשה שעולה ומסטין ששרשו בבחינת דין הקשה ביותר ונק' קץ כל בשר שמכלה כל בשר ונק' קץ הימים כו' בקטרוגי' הקשים שנק' גבורות קשות דק\"נ ועולה גם הוא ונכלל בבחי' גבורות דבחי' המל' (וכמו בכל ר\"ה שיבואו בני האלקי' להתיצב לנגד שם הוי\"ה דחסדים דז\"א להיותם מבחי' הגבורות דשם אלקי' ואז ויבא גם השטן בתוכם שהן בחי' גבורות הקשות ביותר כו' וד\"ל) וזהו הכצעקתה של מדה\"ד דגבורות קשות שעלה עם בחי' המל' ממעשה חטאת סדום כן עשו כו' לפי שכל מה שלמטה עולה הכל ע\"י הממוצעים שהן כחות אלקים (כנ\"ל בפי' שטרי חובותינו כו') דגם בעשות אדם פרטי איזה דבר רע יורשם הפועל הרע הזה ויעשה ממנו צירופי' רעים בשרשו הרוחני ועולה עוד למעלה יותר ע\"י הממוצעי' הרבים עד רום המעלות ממש כנ\"ל בענין וירא ה' כי רבה רעת האדם כו' שהוא מטעם התאחדות הממוצעים הרבים עד שעולי' לבחי' העצמות ממש וזהו הכצעקתה הבאה אלי ממש כנ\"ל וד\"ל:\n(טז) <b>והנה</b> מעתה עדיין יש להבין בפשט הכתוב במה שמסתפק ואו' אם כצעקתה של מדה\"ד כן עשו דמשמע שמסתפק בדבר זה אם עשו בפ\"מ כמו שבאה צעקת מדה\"ד אלי כו' וה\"ז פלא גדול דודאי כפי ההעלאה של חטאתם כן עלה למעלה בבחי' המל' ואם לא הי' במעשה כן לא הי' עולה צעקת מדה\"ד דמסתמא אינו עולה למעלה רק לפי אופן של מעשה התחתונים דוקא אם לרע או לטוב כפי המבואר למעלה ועוד יש להבין בגוף ענין זה שא' ארדה נא ואראה הכצעקתה כו' מהו ענין ירידה זאת מלמעלה למטה הלא את השמים ואת הארץ אני מלא כו' (ירמי' כג, כד) ונמצא למטה כמו למעל' ולפי כל הנ\"ל בענין ההשגח' האלקי' הפרטית שמתאחדת בידיעה הכללית וכמ\"ש (תהלים קיג, ה-ו) המגביהי לשבת המשפילי לראות בשמים כו' וכמ\"ש (ירמי' לב, יט) עיניך פקוחות על כל דרכי בנ\"א (תהלים לג, טו) ומבין אל כל מעשיהם כו' ובזוהר א' ג\"כ וכי לא גליא קמי' קודב\"ה כו' ומ\"ש דאשכחן ירידה לטב וירידה לביש והוא מ\"ש כאן ארדה נא שירד מדרגא דרחמי לדרגא דדינא וכך א' במדרש כנ\"ל זה עצמו יש להבין למה ירד לאשגחא עלייהו בדינא כו' אחר שכבר עלה לפניו צעקת מדה\"ד במ\"ש הבאה אלי ואדרבה הרי הוא"],[2300670282,"מסתפק בדבר אם עשו כפי צעקת מדה\"ד כו' ועוד למה תלה בירור הספק במה שירד במדה\"ד דוקא ואין זה תירוץ כלל על גוף ענין טעם ירידה זו כו':\n(יז) <b>אך</b> הנה כל זה יובן בהקדי' תחלה שרש ענין מדה\"ד ומדה\"ר למעלה ואח\"כ יובן ענין הירידה ממדה\"ר למדה\"ד כו' והוא ענין הידוע בבחי' התחלקות הקווין לימין ושמאל בחכ' שיש שכל המטה כלפי חסד דוקא ויש שכל המטה כלפי דין דוקא כמו ושפטו העדה והצילו העדה שבסנהדרין יש הרבה מזכין ומצילין בטענות שכל של זכות והרבה מחייבים בטענות ושכל של שכל וטעם המחייב לדין וכך הוא בכל דין ומשפט הוראה כמו ב\"ש אוסרין וב\"ה מתירין וזהו הנק' מדות דחו\"ג שבחכ' שהן ב' קווין שקולין לימין ושמאל ויש מכריע שהוא בחי' דעת נוטה להכריע לחסד או לדין כו' והכרעה זו בא ג\"כ מצד השכל והחכ' כידוע ואמנם הנה אנו רואים שיש הכרע' להגביר הקו ימין דחסד שבחכ' על קו השמאל של הדין והוא בא ממקום גבוה יותר מן החכ' והוא הרצון שכפי שיטה הרצון כך יטה את השכל והחכ' ללמוד זכות גם למי שראוי עפ\"י השכל לדין ויכול לסתור כל טענות שכל של חוב ולהפוך הכל לזכות כמו שמצינו בענין השוחד שא' כי השוחד יעור עיני חכמים כעובדא דר\"י שהביא לו כלכלה דפרי והתחיל לצדד בזכותו וא' לו טענות לזכותו כו' (כתובות קה, ב) ולכאורה דבר זה תמוה שהרי עיקר השוחד הוא להטות ולעוות משפט במזיד שיודע שהדין לחוב רק מחמת השוחד שקיבל יפסוק להיפוך ממ\"ש בתורה וא\"כ אין כאן הטיית שכל לזכות כלל וזה אינו במשמעות ענין יעור עיני חכמים מאחר שבמזיד פוסק הדין להיפך ממש ממ\"ש בתורה אלא ענין יעור הוא שרואה בעקלתון כעור ממש והוא רק ענין הטעות שמטעה א\"ע ביותר וכמו שוגג הוא בדבר זה שמחמת השוחד נמשך הרצון בנפשו לטוב ולחסד עד שנדמה לו הדין ומשפט באמת לזכות ולא לחוב כלל וגם זה תמוה דגם אם יש את נפשו ורצונו לטוב מהיכן יפול בטעות גמור כזה לדון לזכות אחר שהדין ומשפט זה מפורש בתורה לחוב אלא צריך לומר דאעפ\"י שהדין מפורש לחוב מ\"מ יטה את המשפט לזכו' אך לא שיפסוק היפוך ממ\"ש בתורה אלא ימצא שכליים וסברות רבות לומר שזה החוב אינו מחייב לאיש זה בענין זה כלל מכמה טעמים של זכות שימצא עליו עד שיהופך מדין וחוב לזכות וחסד ממש להצדיק את הרשע כו' וא\"כ הרי גם בדבר שכבר מפורש לדין וחוב יטה כח שכלו מצד הרצון לטוב להפוך החוב לזכות לעשות מרע טוב כו' וגם זה אינו מובן לכאורה דאיך יכול להפוך ולסתור שכל וטעם של דין העומד לנגד הזכות לעשותו לזכות אך הענין הוא דמצד רצון נפשו לטוב לא יראה בעין השכל לטענה של חוב לחייב כלל כי מרוב אהבתו ותשוקתו לטוב וחסד יטעה א\"ע כ\"כ עד שהוא כעור בלתי יראה כלל את החוב והדין וכלא נחשב ממש מריבוי טענות של הזכות שממציא בשכלו כו'. וע\"ד דוגמא באדם עצמו שאינו רואה חוב לעצמו כלל ולא שאינו מוצא שום חוב ודין ע\"ע כלל אלא מצד רוב אהבתו א\"ע אינו רואה החוב שבו לחוב ודין כלל כי מוצא"],[2300670295,"בנפשו רוב זכות וצדק להצדיק א\"ע ביתר עז שיקטין העון וחטא שעליו בעיניו מאד עד שלא יראה אותו לחוב כלל כי מפני אהבתו א\"ע מטה כח שכלו הכל לזכות עד שאינו רואה חוב כלל בנפשו כו'. וכך הוא בענין השוחד שיעור עיני חכמים להטעות א\"ע עד שאינו רואה את החוב כלל וכלל וזהו מצד טובו וחסדו שברצון שהוא הגובר על עין השכל להטעותו מן הקצה לקצה ממש לעשות מרע טוב כו'. ומזה מוכרח לומר שיש כח במדות שברצון למעלה ממדות שבחכ' שע\"כ השוחד יעור עיני חכמים ג\"כ כנ\"ל וד\"ל:\n(יח) <b>אך</b> הנה לפ\"ז עדיין אין זה נק' היפוך הדין לזכות באמת כלל שהרי שכל המטה כלפי דין וחוב במקומו ותקפו עומד רק שמצד הרצון לטוב וחסד אינו רואה אותו לחוב כלל כנ\"ל וא\"כ איך יובן מזה למעלה בענין התחלקות חו\"ג שבחכ' שיש בכח הרצון העליון שהוא בחי' אור הכתר להגביר החסד על הדין להפוך אותו לחסד ממש וכמו שאנו אומרים יהי רצון מלפניך שיכבשו רחמיך את כעסך כו' הרי מחמת כח הרצון העליון הוא שגובר על טענה של מדה\"ד וכעס להפכו לחסד ורחמים (כמו בקי\"ס שטענה מדה\"ד מה נשתנו אלו מאלו כו' והפך כח החסד לכח הדין לפי שרצה ה' בעמלו כו' ואיך נצח למדה\"ד להפכו לחסד אחר שיש לו מקור בשכל וחכ') (ובמ\"א מבואר בענין העונ' איש\"ר מברך בכל כחו שקורעים לו גז\"ד של שבעים שנה (שבת קיט, ב) לפי שמגביר כח החסד שהוא בבחי' רצון של חסד על כח הדין שבכחו וזהו ענין לאגברא ימינא על שמאלא כו' וזהו ענין ד' שנכנסו לפרדס להמתיק כח הדין בהתגברות אור החסד שבכתר עליון כו' שעי\"ז ממילא נחלש כח הדין שבחכ' כו' וזהו ענין יהי רצון מלפניך שיכבשו רחמיך כו' כמשי\"ת) ואמנם הענין הוא שיש בזה ב' אופנים הא' כאשר יש ב' מיני שכליים א' מטה כלפי חסד והב' מטה כלפי דין והרצון מכריע דוקא כמו שכל של דין או של חסד אין זה הכרעת השכל לשכל ולא נצח והיפך זה לזה כלל ע\"ד דוגמא ויכוח בב' שרים במשפט מב' דייני המלך זה גוזר שכלו לזכות וזה לחוב והמה יביאו המשפט לפני המלך והוא מכריע כא' מהם זהו הכרעת רצון המלך שרוצה לחסד או לדין וגם אם יכריע זה מצד שכלו שמטה כלפי חסד יותר עדיין לא נהפך השכל של דין כלל (וכמו בענין קללה דבלעם שא' (דברים כג, ו) ולא אבה ה' אלקיך לשמוע אל בלעם מצד חפצו בחס' וטוב לישראל ונמצא שאין זה היפוך בשכל עצמו כי השכל והטעם שמטה כלפי דין הוא שכל וטעם אחר ובמקומו ותקפו עומד כמו בראשונה ולא נחלש כחו כלל וכן להיפוך כשיכריע הרצון לדין היפוך החסד לא נהפך שכל וטעם של חסד כלל) ואמנם אופן הב' הוא הטיית והיפוך הדין לזכות והזכות לחוב שיכולים להתהפך מן הקצה לקצה גם בשכל וטעם א' שאותו השכל והטעם שהיה מטה כלפי דין ישכיל באותו שכל עצמו לזכות דוקא שזהו ברצון תליא מלתא ברצותו לטוב יהפוך לשכל של דין לחסד שהוא עצמו יחייב לחסד וזכות וברצותו להטות לחוב ודין ישכיל באותו שכל וטעם של חסד שהוא עצמו יחייב לחוב בדין הרי הגם שכבר נגמר הסכם וחיוב"],[2300670307,"השכל וטעם א' לדין יהופך לחסד ברצותו לזכות או להיפוך אם כבר חייב השכל וגזר לזכות יהפכנו לדין וחוב אם רצונו בזה ונמצא ברצון תליא מלתא ולא בשכל אע\"פ שהשכל וטעם א' הוא וזהו הנק' שינוי בגוף השכל עצמו שיהופך מדין לחסד או מחסד לדין ע\"פ הרצון המכריע וד\"ל:\n(יט) <b>וזהו</b> ענין אמרינו בכלל יהי רצון מלפניך שיכבשו רחמיך את כעסך כו'. ולכאורה איך יהיה ביכולת הרצון העליון להפוך כח השכל וטעם של דין וכעס שבודאי יש חכ' וטעם למדת הדין וכעס שהוא מפני שעברו בנ\"י על התו\"מ או על ביטול מ\"ע וכה\"ג ואיך מבקשים שיכבשו רחמיך את כעסך כו'. אך הענין הוא דבודאי יש שכל וטעם לרחמים וחסד בפ\"ע ושכל וטעם לדין וכעס בפ\"ע ואין בכח השכל של חסד ורחמים להכריע לשכל וטעם של דין אך כאשר יאיר אור הרצון העליון באור פני מלך חיים כמו שאו' יהי רצון מלפניך כו' אזי יכריע הרצון ויכבוש אור ושכל של חסד על היפוכו שהוא של דין דהיינו ע\"י הרצון שהוא עושה ומהפך משכל של דין לחסד ורחמים דהיינו שמאותו שכל וטעם עצמו שגזר לדין הוא עצמו יגזור ויחייב לזכות וחסד היפוכו שזהו שינוי גמור בגוף עצם השכל בעצמו שנתהפך מן הקצה לקצה (וכמו שקטיגור נעשה סניגור ששכלו של דין נהפך ללמוד זכות וחסד בראותו הארת אור רצון המלך לחסד וטוב כמו בבלע' שרצה לקטרג על ישראל ע\"פ טוב טעם ודעת כו' ובראותו רצון ה' לברכם נעשה מטעם הקטרוג שלו זכות וחסד שהרי נהפך מקללה לברכה כו' וכמשי\"ת). וזהו יהי רצון מלפניך פי' שיכריע הרצון הטוב להפוך הטעם ושכל של דין ורוגז להיות הוא עצמו טעם ושכל לזכות וחסד וזהו שיכבשו רחמיך את כעסך שהוא מיתוק הדין בשרשו וד\"ל:\n(כ) <b>ודוגמא</b> לזה מצינו בכתו' בענין המבול שא' (בראשי' ו, ה-ז) וירא ה' כי רבה רעת האד' בארץ וכל יצר מחשבות לבו רק רע כל היום וינחם ה' כי עשה את האדם כו' ויאמר ה' אמחה את האדם כו' כי נחמתי כי עשיתם ואח\"כ כשיצא נח מן התיבה והקריב קרבן כתיב וירח ה' את ריח הניחוח ויאמר ה' אל לבו לא אוסיף לקלל עוד את האדמה בעבור האדם כי יצר לב האדם רע מנעוריו כו' והרי בתחלה כשגזר מדה\"ד למחות את האדם אשר עשה תלה הטעם ושכל לגזר ופס\"ד זה מפני שא' שכל יצר מחשבות לבו רק רע כו' וע\"כ וינחם ה' על אשר עשה את האדם ואח\"כ כאשר חזר בו וא' לא אוסיף כו' תלה הטעם והשכל לפסק דין זה לחסד וטוב ג\"כ מצד אותו השכל והטעם שתלה בו לחוב ודין והוא באומרו כי יצר לב האדם רע מנעוריו והרי זה היה הטעם לדין וחוב בתחלה כשגזר למחות את האדם ואיך יתהפך שכל וטעם א' מדין לחסד שיהי' זה השכל וטעם עצמו גוזר ומחייב לחסד הי' לו למצוא שכל וטעם אחר לחסד ולזכות ולא אותו השכל והטעם שגזר וחייב לדין בתחלה שנראה כסותר א\"ע בשכל וטעם א' כו' אך שרש ענין הטייה זו להטות אותו השכל עצמו מדין לחסד הוא בא ע\"י כח הרצון העליון הטוב כשהריח בריח קרבן נח כו' שיש בכח הרצון הטוב הזה"],[2300670319,"שינוי גמור מן הקצה אל הקצה גם בשכל וטעם א' שכב' גזר וחייב לדין שיתהפך הוא עצמו לגזור מטעם זה עצמו לחסד ורחמים וכמו טעם דיצר מחשבות לבו רק רע שהוא שגזר וחייב למחות האדם ולמאוס ולהנחם על בריאתו בתחלה וכמ\"ש אמחה את כו' ואח\"כ כשהריח בריח הקרבן ועלה לרצון לפני ה' גזר הטעם הזה עצמו שלא יוסיף עוד להכות את כל חי באמרו כי יצר לב האדם רע מנעוריו והכוונה שזהו עצמו זכות לאדם לפי שיצרו הרע שבקרבו מנעוריו הוא המחטיאו ואין עליו אשמה וחוב כ\"כ אחרי שיצרו תקפו מנעוריו ואין לבו ברשותו לעמוד לנגד יצרו הרע ביותר והרי הטעם הזה עצמו שיצר מחשבות לבו רק רע כל היום שגזר בתחילה לדין ועונש למחות את האדם הוא עצמו שנהפך לטעם ושכל לזכות להצילו לפי שיצר לב האדם כו' וזהו שינוי בגוף שכל וטעם א' להתהפך מן הקצה לקצה מדין לחסד מפני כח רצון העליון שנרצה בקרבן של נח כמו ענין הנ\"ל בפי' יהי רצון מלפניך שיכבשו רחמיך כו' וד\"ל:\n(כא) <b>אך</b> הנה עדיין היא גופא יש להבין מאין יש בכח הרצון לגבור על השכל של דין להפכו לזכות וחסד כנ\"ל מאחר שהשכל וטעם של דין ורוגז בא גם הוא מן הרצון של דין כמו מדת הכעס והרוגז שבא מצד שעברו על רצונו בתו\"מ כמ\"ש יכבשו רחמיך את כעסך ואין כעס ורוגז רק על עוברי רצונו ית' כמו וחרה אף ה' כו' ואיך אנו אומרים שיהי רצון מלפניך שיכבשו רחמיך את כעסך מאין יהי' בכח הרחמים הללו לכבוש לכח הדין והרוגז ולהפכו לחסד ורחמי' כמו ברוגז רחמי' תזכור כו' אדרבה כמו שיש בכח הרצון של חסד להפוך לשכל של דין לזכות כנ\"ל בענין רעת אנשי דור המבול כך יש בכח הרצון של דין ורוגז להפוך לשכל וטעם של חסד וזכות לדין וחוב מאחר שיש בכח הרצון להפוך שכל וטעם א' מן הקצה לקצה וכנ\"ל דברצותו לחוב ישכיל באותו שכל וטעם עצמו שחייב לזכות להפכו לחוב שהוא יהי' הטעם בעצמו לחוב כו' ואין אופן כלל לומר במה שיגבור הרצון להפוך השכל של דין לזכות שאין זה רק בכח שלמעלה מן הרצון עצמו דוקא. אמנם הרי ודאי כמו שיש ב' קווין דחו\"ג בחכ' לחוב ולזכות כך יש גם ב' קוין הללו ברצון שלמעלה מן החכ' שנק' מדות חו\"ג שבכתר וגם הן שקולין ואיך יכריע זה לזה אם לא בכח העליון מן כח הרצון שיגביר הקו הא' דרצון על רצון שכנגדו כקו המשקולת שיכול להכריע משמאל לימין ומימין לשמאל וזהו שאו' יהי רצון מלפניך פי' מלפניך דוקא והוא שיבא כח העליון מן הרצון והוא שנק' רדכ\"ר ואז יהי' רצון זה בכח לגבור על רצון של דין ורוגז להמתיקו והוא כח הרחמי' שיכבשו לכעס ורוגז כמו ברוגז רחמי' תזכור לגבור על הכעס ורוגז להפכו לחסד ממש והוא מה שיתהפך השכל וטעם של דין עצמו שיהי' מחייב לחסד וזכות כנ\"ל. וזהו הנק' בזוהר לאגברא ימינא על שמאלא שהוא להגביר כח החסד שברצון על כח הדין ורוגז שברצון ואז ממילא יהופך השכל וטעם של דין הוא עצמו לזכות כנ\"ל (וכנ\"ל בענין קי\"ס שנצח מדה\"ר וכה\"ג). אמנם עדיין אין זה מוכרח שיהי' התגברות כח החסד על"],[2300670330,"הדין דכמ\"כ ממש יוכל להיות להיפוך לגבור כח הדין שברצון על כח החסד שברצון כמו קו המשקולת שיכול להכריע מימין לשמאל כמו שיכול להכריע משמאל לימין ואם מפני שבאה ההכרעה לרצון של חסד מכח העליון שלמעלה מן הרצון כנ\"ל הרי מכח העליון הזה יכול להגביר כח הדין שברצון על כח החסד שברצון כו' ואיך מבקשי' יהי רצון כו' מאחר דגם למע' מן הרצון נמשך בב' קוין דחו\"ג וא\"כ אין הבקשה רק שיכריע לימין ומשמעות הפשוט שיש בכח הרצון העליון שהוא נמשך מבחי' רדכ\"ר הנ\"ל לכבוש תמיד לרצון של דין ורוגז בלי נטי' להיפוך לעולם כו' (וזהו הנק' לאכללא שמאלא בימינא ולא לאגברא ימינא על שמאלא בלבד דהיינו שנכלל ומתאחד כל עצם של כח השמאל להוסיף כח בחסד דימין כענין קטיגור נעשה סניגור וכברכות דבלעם שנהפך מן הקללה עצמ' לברכה כו' וד\"ל):\n(כב) <b>אך</b> שרש הענין הוא כידוע שיש ב' מדרגות בחכ' שבכתר שנק' ח\"ס דא\"א א' בחי' החיצוניות שבו שנחלק לקוין ימין ושמאל והוא הנק' טעם כמוס לרצון לחסד או להיפוכו לדין (כמו בר\"ע שא' (מנחות כט, ב) זו תורה וזו שכרה והשיב שתוק כך עלה במח' לפני וכמ\"ש במ\"א) שממנו בא תולדות המדות שברצון של חסד או רצון של דין לפי אופן ההטייה דחכ' שבכתר שנק' טעם כמוס (כמו בשכל הגלוי שיש ב' קוין להטות כלפי חסד או דין) (והתחלקות זו דשכל הגלוי לחו\"ג נובע ממקורו שהוא בחי' ח\"ס הנ\"ל שהוא המשכיל כל שכל וטעם לזכות מן ההעלם לגילוי או להיפוך שממנו נובע כל שכל וטעם לדין וחוב כמו (ירמי' ד, כב) חכמים המה להרע שמשכיל לדין וחוב תמיד כו') וב' קוין הללו שקולין הן ואין בא' כח להכריע לשכנגדו כמו ב' כפות המאזניים שעומדים בשוה. ואמנם מדרגה הב' דח\"ס הנ\"ל הוא בחי' הפנימי' שבו שנחשב בבחי' פנימית הכתר שנק' כתר שבכתר שהוא למעלה מהתחלקות ונטיות הללו שברצון הנק' טעם כמוס לרצון כו' ושם הוא ענין כח ההכרעה להכריע מימין לשמאל ומשמאל לימין בב' המדרגות דרצון וחכ' דהיינו שיגביר הרצון של חסד שבא מכח הטיית החסד של טעם כמוס הנ\"ל על רצון של דין שבא ג\"כ מכח הדין של טעם כמוס זה או להיפוך להגביר כח הדין דח\"ס על כח החסד שבו וממילא יהיו ב' הכרעות הפכיים הללו בבחי' החכ' שהוא שכל הבא בגילוי להטות כלפי חו\"ג שישונה מחסד לדין ומדין לחסד בהתהפכות מן הקצה לקצה בשכל וטעם א' כנ\"ל מצד ההתהפכות הזאת במקורו בח\"ס בהעלם ומקור שנק' טעם כמוס לרצון שבא מכח של העליון ממנו יותר והוא בחי' כתר שבכתר שלמעלה גם מטעם כמוס לרצון כו' והוא עצם נקודת הרצון כמו שהוא שנק' רצון הפשוט שבכחו להטות ולהכריע בב' קוין דחו\"ג דח\"ס וד\"ל:\n(כג) <b>וזהו</b> שמבקשי' יהי רצון כו' לאגברא ימינא על שמאלא שזהו להגביר כח הימין דחסד דח\"ס הנ\"ל על כח השמאל שבו ע\"י בחי' הרצון הפשוט שנק' רדכ\"ר והוא עיקר ענין סליחת העונות בהמשכת י\"ג מדה\"ר מרדכ\"ר שלמעלה"],[2300670341,"מח\"ס למחול ולסלוח גם לעוברי רצונו אע\"פ ששרש התו\"מ הוא בפנימי' דח\"ס שהוא הטעם כמוס לרצה\"ע שבאו ג\"כ בב' קוין דימין ושמאל ה\"ח דמ\"ע וה\"ג דל\"ת שזהו חו\"ג דכתר שהוא אנכי ולא יהי' לך כידוע ומבקשי' שיסלח וימחול גם לעובר פנימי' רצה\"ע מצד הר\"ר שברדכ\"ר הנ\"ל שביכולתו להכריע לקו השמאל דח\"ס לימין להיותו למעלה מהתחלקות דחו\"ג דתו\"מ ולא לאגברא ימינא לבד אלא גם שיהפך כח השמאל גם הוא להוסיף כח בימין והוא מה שזדונות עצמן נעשים זכיות דהיינו מה שהקללה דל\"ת עצמה נהפך לברכה שזהו קטיגור עצמו נעשה סניגור כנ\"ל בענין קללה דבלעם כו' והוא ע\"י התשובה דוקא שנהפך הרע עצמו לטוב כידוע בענין טוב מאוד זה מ\"ה שנהפך לחיים שיותר גדול מחיים עצמו וזהו ימינך ה' ב\"פ א' לאגברא ימינא לבד שהוא ההכרעה לבד והב' תרעץ אויב כאשר השמאל דכח הדין עצמו נהפך להוסיף כח בימין בתוס' יותר מכח הימין עצמו שאז תרעץ אויב ובזה יתפרש יהי רצון מלפניך שיכבשו כו' שיהפכו הדינין להוסיף כח בחסד שזהו לאכללא שמאלא בימינא ולא רק לאגברא ימינא כו' (אבל עדיין דבר זה צריך ביאור למה יהי' כח לפנימי' הכתר רק להפוך כח השמאל שיוכלל כל עצמו בימין בלי נטי' להיפוך שכח הימין יוכלל בשמאל מאחר שהוא למעלה משניהם זה הטעם יחייב ג\"כ שיכול להכריע מחסד דימין לשמאל ולהפכו ג\"כ שיוסיף כח בשמאל כו' ולמה יכריע ויהפוך הכל משמאל לימין ויתבאר זה בסמוך). והנה לפ\"ז הרי יכול להיות מכח ומקור העליון שלמעלה מהתחלקות הרצון נטי' מרצון לרצון היפוכו גם להיות היפוך הרצון של חסד לדין וכמו שאנו רואים להיפוך מסליחת העונות שיגבר כח הרצון של דין ורוגז על הרצון של חסד עד שלא יועיל זכות דתו\"מ ולא הרחמי' כלל כמו (תהלים צ, יא) מי יודע עוז אפך כו' (וכיסורי אורך הגלות שלא יעלה זכות דתו\"מ ולא זכות אבות כלל כמו (איכה ה, כב) כי אם מאוס מאסתנו קצפת עלינו עד מאד כו' שמחמת כח הקצף יוקטן כל החסד וטוב ויהופך הכל לחוב כמו בהיפוכו מדין לחסד כמו (ישעי' א, טו) ובפרשכם כפיכם אעלים עיני כו' וא\"כ הרי יש שרש בבעל הרצון עצמו שיטה גם עצם רצון הפשוט הנ\"ל מדין לחסד ומחסד לדין ולזה מבקשי' יהי רצון מלפניך שיכבשו רחמיך כו' ומאין יהי' רצון זה להכריע משמאל לימין דוקא מאחר שיכול להיות להיפוך ממש כנ\"ל אך צריך להקדי' תחלה מהו שרש ענין ב' הכרעות מלמעלה מן הרצון להכריע מרצון לרצון היפוכו הנ\"ל:\n(כד) <b>ויובן</b> זה בתוס' טעם בהקדמת ענין א' שאנו רואים בטבע האדם שיוכל להתהפך תמיד מחסדי' לגבורות ודינין ומדינין וגבורות לחסדים גם בנקודת הרצון שבנפשו ממש שלמעלה מן השכל והטעם כמו באב לבנו או לאוהבו הנאמן כנפשו ממש שבודאי אהבתו לבנו שהוא יוצא חלציו טבעית ועצמית וכן עצמיות התקשרותו אל אוהבו הנאמן לו ביותר והנה אנו רואים בחוש שמצד אהבת האב לבנו ואוהבו כנפשו ישפיע להם תמיד בעין טובה להטיב להם בכל מילי דמטיב לנפשם מכל אשר לו בלי גבול ומדה כלל ולא"],[2300670352,"יועיל כל מקטרג עליהם אף שיקטרגו בדבר עון וחטא קשה וידבר סרה להבאישם בעיניו לא יטה אזנו לשמוע כלל וכלל ואמנם אנו רואים להיפוך גמור ג\"כ שאם לפעמים יכעוס ויקצוף עליהם ע\"ד איזה מעשה רעה שהוא לנגד רצונו בתכלית אזי יתאכזר ויעשה להם כל הרעה אשר יוכל גדולה יותר מן הטובה אשר עשה עמהם וזהו כמו פלא גדול איך ישתנה מטוב לרע כ\"כ מן הקצה לקצה. אך הענין הוא כך שבאהבתו הנפלאה להם מאד כאהבת נפשו ממש ע\"כ הוא רואה תמיד בעין טובה עליה' וענין ההסתכלות בעין טובה ידוע שהיא הבאה מחמת אה\"ר העצמית כמו שאוהב א\"ע ממש עד שמחמת זה יסתכל עליו בעין השכל הכל לטוב דהיינו מפני שכל פנימית ועצמות רצונו בהם ע\"כ גורם ג\"כ הטיית השכל לדין לדון כל מעשיהם לטוב דוקא וכנראה בחוש באב לבנו שמפני אהבתו אותו מאד ישבחנו תמיד במעלות ומדות טובות שאין בו גם חלק הי' מן הטוב ומעלה כזה לפי שמחמת הסתכלותו עליו בעין טובה מאד אזי גם מעט הטוב שבו יגדל בעיניו מאד כערך מאה פעמים מכמו שהוא ולהיפוך כל חלקי הרע שימצא בו יקטן מאד בעיניו הגם שהוא רב מאד עד שלא יחשב בעיניו לרע כלל והוא רק לעוצם העין טובה שרואה עליו עד שכלא ממש נחשב כל הרע שבו וכאילו אינו רואה אותו כלל וכלל כמו שבאהבת אדם א\"ע אינו רואה חוב לעצמו כלל כנ\"ל מזה הטעם ג\"כ מפני שרואה בעין טובה א\"ע מצד אהבת עצמו ביותר (וכמו\"כ באהבת ה' לישראל שנק' בנים כמו שאו' אה\"ע אהבתנו כו' כמו שאוהב א\"ע כביכול ע\"כ אינו רואה רק בעין טובה על ישראל שיגדל בעיניו הטוב שבהם ביותר וכל הרע שבהם אינו רואה לחוב ורע כלל והוא מה שראה בלעם שה' מביט בעין טובה על ישראל אמר לא הביט און ביעקב כלל כו') והנה בהכרח שע\"י הסתכלות בעין טובה כנ\"ל ימצא כל בחי' הטוב שרואה עליו בשכל וטעם דוקא כי מחמת הראי' בעין טובה ממילא יטה כח שכלו למצוא לו רוב שכליים וסברות לדון כל מעשיו במדות של חסד וטוב (ובל\"א ער זעהט דאס אן לטוב) שיטה שכלו להשכיל ולדון בטוב טעם ודעת לזכות וחסד וע\"כ תמיד יגזור ויחייב שכלו להטיב לו בכל מילי דמטיב בלי גבול ולא יועיל כל מנגד בקטרוג איזה דבר רע מאחר שאינו רואה לחוב כלל מטעם העין טובה כנ\"ל וד\"ל:\n(כה) <b>אך</b> הנה כאשר יכעוס ויקצוף האב על בנו האהוב או או\"נ כנפשו הגם שהי' התקשרות נפשו באה\"ר עצמית וטבעית אליהם אבל מפני כעסו שהכעיסו אותו עד שנגע בנקודת רצונו ובפנימי' נפשו ביותר אזי יוסר מעליהם העין טובה הנ\"ל ויתחיל להסתכל עליהם בעין רעה שהוא היפך העין טובה ממש והענין הוא שע\"י הסתכלותו בעין רעה שבאה מפני השנאה ששנאם ע\"י הכעס העצום יראה עין שכלו עליהם הכל לרע ולא לטוב כלל דהיינו שגורם שישכיל שכלו בכל מעשיהם ומדותיהן שהן רעים וחטאים ביותר הרבה מכמו שהוא עד שמעט חלק הרע שנמצא בהם באמת יגדל מאד בעיניו והי' לחטא ועון גדול מנשוא וכל ריבוי הטוב שבהם"],[2300670363,"באמת יקטן מאד בעיניו עד שכלא ממש חשיב וכאילו אינו רואה טוב כלל וכלל כמו שבעין טובה אינו רואה את החוב כלל כנ\"ל (כמו (במדבר כג, כא) לא הביט און ביעקב (כלל) או כמ\"ש (איוב יא, יא) וירא און ולא יתבונן כלל שאעפ\"י שרואה את העון אינו מתבונן בו כלל) וכך הוא להיפוך ממש בעין רעה שיתבונן דוקא בחלק הרע להגדילו ביותר הרבה מכמו שהוא עד ק' פעמים ויותר ולא יתבונן בבחי' הטוב כלל אדרבה מקטינו לגמרי עד שכלא נחשב ממש ובודאי כל זה ימצא בשכל וטעם דוקא מפני שעין רעה זו יגרום כל הטיית השכל וסברא לדון הכל לחוב דוקא כמו שבעין טובה יגרום הטיית כל השכליים וסברות לזכות כנ\"ל לפי שהן ב' קוין הפכיים בתכלית מן הקצה לקצה ממש וד\"ל. (ונמצא מובן שב' קוין דעין טובה ועין רעה הן ב' הפכי' רחוקים ועמוקים בנפש יותר עד שגם הרצון וחכ' וגם נקודת הרצון העצמי כאב לבנו יהופך מהיפוך להיפוך ממש כנ\"ל וא\"כ בהכרח שיש בבעל הרצון ב' נטיות להטות לנקודת עצם הרצון לטוב שהוא ע\"י עין טובה או להיפוך להטות לנקודת עצם הרצון לרעה שהוא ע\"י עין רעה כו' והרי יכול להתהפך מעין טובה לעין רעה או להיפוך גם באהבה העצמי' דאב לבנו א\"כ ודאי יש בעצמות הנפש כח עליון משניהם (וכמשי\"ת בסמוך) עד שמחמת זה יוכל להחליף מעין טובה לעין רעה כמו האב כשכועס על בנו או להיפוך כשירצה וימחול האב לבנו יחזור לראות עליו בעין טובה ועכ\"ז כח הימין דעין טוב גובר על כח השמאל דעין רעה עד שיוכלל בו ממש מטעם שית' בסמוך דתרין עיינין אתהדרו לחד כו' וזהו שמבקשי' יהי רצון מלפניך כו' וד\"ל):\n(כו) <b>ונמצא</b> מובן מכל הנ\"ל דיכול להיות הטיות הרצון והשכל להצדיק ולהרשיע מן הקצה לקצה והכל תלוי בעין טובה ועין רעה כמו שאם ידונו את אדם החוטא לפני המלך אם יסתכל עליו המלך בעין טובה ימצא לו כל הזכיות להצדיק את הרשע כצדיק גמור הגם שחטא חטא גדול ימחול לו כי לא יתבונן כלל על כל חטאיו ועל כל הרע שעשה יקטין הדבר מאד אבל אם יסתכל המלך בעין רעה גם לאיש צדיק מעיקרו ירשיע ולא יועילו לו כל צדקותיו הרבים כי לא יתבונן אליהם כלל ועונו תגדל בעיניו גם שהוא עון קל מאד עד שהוא כרשע גמור כו' ונמצא נעש' הטיית השכל לשפוט לצדיק כרשע גמור ולרשע כצדיק גמור דהיינו שיגזור השכל ורצון לעשות מעון וחטא גדול באמת להקטינו מאד או להיפוך להגדיל חטא ועון קל ביותר עד שיגדל במאד ומצד זה יבא המשפט בשינוי גדול מן הקצה לקצה להצדיק את הרשע ולהרשיע את הצדיק והכל בשכל וטעם א' דאותו השכל והטעם שחייב וגזר לדין ועונש הוא יגזור לזכות וחסד מצד האהבה והרחמי' שהוא כשמסתכל בעין טובה כנ\"ל כי הרי צריך לתרץ על העון וחטא גדול שעשה באותו הטעם עצמו שחייבו לדין להפכו לזכות ולהקטינו מאד וכמו בענין דור המבול שאמר תחלה וירא כי רבה רעת האדם שהגדיל הרע שלהם ביותר ונתחייבו כליי' כו' מטעם זה ואח\"כ כשנסתכל עליהם בעין טובה ע\"י שהריח בריח קרבן נח א' כי יצר לב האדם רע כו' שמטעם זה עצמו נידון"]]});
